tool_schemas.implementation:
def get_workspace_hierarchy(workspaceId=None, teamId=None, includeArchived=None, includeDeleted=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    # Usage/audit logging best-effort: only if file exists in store list or can be created.
    def _log(status, workspace_id=None, team_id=None, error_code=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().isoformat() + "Z"
            logs.append({
                "request_id": "req_" + now.replace(":", "").replace("-", "").replace(".", ""),
                "endpoint": "get_workspace_hierarchy",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "workspace_id": workspace_id,
                "team_id": team_id,
                "error_code": error_code
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    # Validate inputs
    if workspaceId is None and teamId is None:
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either workspaceId or teamId must be provided.")
    if workspaceId is not None:
        if not isinstance(workspaceId, str):
            _log("error", None, teamId, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspaceId must be a string.")
        if not re.match(r"^cu_wsp_[0-9A-Z]{18,}$", workspaceId):
            _log("error", workspaceId, teamId, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspaceId does not match expected format.")
    if teamId is not None and not isinstance(teamId, str):
        _log("error", workspaceId, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "teamId must be a string.")
    if includeArchived is not None and not isinstance(includeArchived, bool):
        _log("error", workspaceId, teamId, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeArchived must be a boolean.")
    if includeDeleted is not None and not isinstance(includeDeleted, bool):
        _log("error", workspaceId, teamId, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeDeleted must be a boolean.")
    includeArchived = bool(includeArchived) if includeArchived is not None else False
    includeDeleted = bool(includeDeleted) if includeDeleted is not None else False

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        _log("error", workspaceId, teamId, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unreadable.")

    wsp = None
    if workspaceId is not None:
        for w in workspaces:
            if isinstance(w, dict) and w.get("workspace_id") == workspaceId:
                wsp = w
                break
    else:
        for w in workspaces:
            if isinstance(w, dict) and w.get("clickup_team_id") == teamId:
                wsp = w
                break

    if not wsp or wsp.get("status") != "active":
        _log("error", workspaceId, teamId, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found or not active.")

    ws_id = wsp["workspace_id"]
    team_id = wsp.get("clickup_team_id")

    # Determine freshness
    TTL_SECONDS = 300  # configured TTL for hierarchy cache freshness
    now_dt = datetime.datetime.utcnow()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    updated_at_dt = _parse_dt(wsp.get("updated_at"))
    cache = wsp.get("hierarchy_cache")
    fresh = False
    if cache is not None and isinstance(cache, dict) and updated_at_dt is not None:
        age = (now_dt - updated_at_dt).total_seconds()
        if age >= 0 and age <= TTL_SECONDS:
            fresh = True

    containers = _load("containers.json")
    if not isinstance(containers, list):
        _log("error", ws_id, team_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unreadable.")

    # Refresh "from ClickUp" (offline): rebuild hierarchy_cache from containers rows.
    # Only include containers in this workspace, and honor includeArchived/includeDeleted flags.
    def _visible_container(c):
        if c.get("workspace_id") != ws_id:
            return False
        if not includeDeleted and c.get("status") == "deleted":
            return False
        if not includeArchived and bool(c.get("archived")) is True:
            return False
        return True

    if not fresh:
        # Build hierarchy snapshot
        by_id = {c.get("container_id"): c for c in containers if isinstance(c, dict) and c.get("workspace_id") == ws_id}
        spaces = []
        for c in by_id.values():
            if c.get("type") == "SPACE" and _visible_container(c):
                spaces.append(c)
        # deterministic order by name then id
        spaces.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("container_id") or ""))

        def _folder_children(space_id):
            out = []
            for c in by_id.values():
                if c.get("type") == "FOLDER" and c.get("parent_container_id") == space_id and _visible_container(c):
                    out.append(c)
            out.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("container_id") or ""))
            return out

        def _list_children(parent_id):
            out = []
            for c in by_id.values():
                if c.get("type") == "LIST" and c.get("parent_container_id") == parent_id and _visible_container(c):
                    out.append(c)
            out.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("container_id") or ""))
            return out

        hierarchy = {
            "workspace": {
                "workspace_id": ws_id,
                "clickup_team_id": team_id,
                "name": wsp.get("name"),
                "timezone": wsp.get("timezone"),
            },
            "spaces": []
        }

        for sp in spaces:
            sp_node = {
                "container_id": sp.get("container_id"),
                "clickup_container_id": sp.get("clickup_container_id"),
                "type": "SPACE",
                "name": sp.get("name"),
                "archived": bool(sp.get("archived")),
                "status": sp.get("status"),
                "folders": [],
                "lists": []
            }
            # lists directly under space
            for lst in _list_children(sp.get("container_id")):
                sp_node["lists"].append({
                    "container_id": lst.get("container_id"),
                    "clickup_container_id": lst.get("clickup_container_id"),
                    "type": "LIST",
                    "name": lst.get("name"),
                    "archived": bool(lst.get("archived")),
                    "status": lst.get("status"),
                    "content": lst.get("content"),
                })
            # folders under space (and their lists)
            for fol in _folder_children(sp.get("container_id")):
                fol_node = {
                    "container_id": fol.get("container_id"),
                    "clickup_container_id": fol.get("clickup_container_id"),
                    "type": "FOLDER",
                    "name": fol.get("name"),
                    "archived": bool(fol.get("archived")),
                    "status": fol.get("status"),
                    "override_statuses": fol.get("override_statuses"),
                    "lists": []
                }
                for lst in _list_children(fol.get("container_id")):
                    fol_node["lists"].append({
                        "container_id": lst.get("container_id"),
                        "clickup_container_id": lst.get("clickup_container_id"),
                        "type": "LIST",
                        "name": lst.get("name"),
                        "archived": bool(lst.get("archived")),
                        "status": lst.get("status"),
                        "content": lst.get("content"),
                    })
                sp_node["folders"].append(fol_node)

            hierarchy["spaces"].append(sp_node)

        # Persist cache onto workspace
        wsp["hierarchy_cache"] = hierarchy
        wsp["updated_at"] = now_dt.isoformat() + "Z"
        # write back
        for i, w in enumerate(workspaces):
            if isinstance(w, dict) and w.get("workspace_id") == ws_id:
                workspaces[i] = wsp
                break
        _save("workspaces.json", workspaces)
        cache = hierarchy

    _log("ok", ws_id, team_id, None)
    return {
        "workspace_id": ws_id,
        "team_id": team_id,
        "hierarchy": cache,
        "cache_fresh": fresh,
        "include_archived": includeArchived,
        "include_deleted": includeDeleted
    }

def create_task(listId=None, listName=None, name=None, description=None, status=None, priority=None, dueDate=None, startDate=None, assigneeUserIds=None, parent=None, tags=None, customFields=None, **_extra):
    import json, os, datetime, uuid, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_task"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, task_id=None, list_container_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "task_id": task_id,
            "list_container_id": list_container_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.", field=field)
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid ISO-8601 date-time.", field=field, value=s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        return dt.isoformat() + "Z", None

    # ---- Validate inputs ----
    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", detail={"field": "name"})
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    nm = name.strip()
    if len(nm) < 1 or len(nm) > 1024:
        _log("VALIDATION_ERROR", detail={"field": "name"})
        return _err("VALIDATION_ERROR", "name length must be between 1 and 1024.", field="name")

    if listId is None and (listName is None or not isinstance(listName, str) or not listName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["listId", "listName"]})
        return _err("VALIDATION_ERROR", "You must provide exactly one list target: listId or listName.", fields=["listId", "listName"])
    if listId is not None and not isinstance(listId, str):
        _log("VALIDATION_ERROR", detail={"field": "listId"})
        return _err("VALIDATION_ERROR", "listId must be a string when provided.", field="listId")
    if listName is not None and not isinstance(listName, str):
        _log("VALIDATION_ERROR", detail={"field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string when provided.", field="listName")

    if description is not None and not isinstance(description, str):
        _log("VALIDATION_ERROR", detail={"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
    if status is not None and not isinstance(status, str):
        _log("VALIDATION_ERROR", detail={"field": "status"})
        return _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")
    if priority is not None:
        if not isinstance(priority, int):
            _log("VALIDATION_ERROR", detail={"field": "priority"})
            return _err("VALIDATION_ERROR", "priority must be an integer when provided.", field="priority")
        if priority < 1 or priority > 4:
            _log("VALIDATION_ERROR", detail={"field": "priority"})
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4 when provided.", field="priority")

    due_z, err = _parse_dt(dueDate, "dueDate")
    if err:
        _log("VALIDATION_ERROR", detail={"field": "dueDate"})
        return err
    start_z, err = _parse_dt(startDate, "startDate")
    if err:
        _log("VALIDATION_ERROR", detail={"field": "startDate"})
        return err

    if assigneeUserIds is not None:
        if not isinstance(assigneeUserIds, list) or any(not isinstance(x, str) for x in assigneeUserIds):
            _log("VALIDATION_ERROR", detail={"field": "assigneeUserIds"})
            return _err("VALIDATION_ERROR", "assigneeUserIds must be an array of strings when provided.", field="assigneeUserIds")

    if parent is not None and (not isinstance(parent, str) or not parent.strip()):
        _log("VALIDATION_ERROR", detail={"field": "parent"})
        return _err("VALIDATION_ERROR", "parent must be a non-empty string when provided.", field="parent")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _log("VALIDATION_ERROR", detail={"field": "tags"})
            return _err("VALIDATION_ERROR", "tags must be an array of strings when provided.", field="tags")

    if customFields is not None:
        if not isinstance(customFields, list):
            _log("VALIDATION_ERROR", detail={"field": "customFields"})
            return _err("VALIDATION_ERROR", "customFields must be an array when provided.", field="customFields")
        for i, cf in enumerate(customFields):
            if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or any(k not in ("id", "value") for k in cf.keys()):
                _log("VALIDATION_ERROR", detail={"field": f"customFields[{i}]"})
                return _err("VALIDATION_ERROR", "customFields items must be objects with required keys ['id','value'] only.", field=f"customFields[{i}]")
            if not isinstance(cf.get("id"), str) or not cf["id"].strip():
                _log("VALIDATION_ERROR", detail={"field": f"customFields[{i}].id"})
                return _err("VALIDATION_ERROR", "customFields[].id must be a non-empty string.", field=f"customFields[{i}].id")

    # ---- Resolve destination list + workspace ----
    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")
    workspaces = _load("workspaces.json")
    if not isinstance(containers, list): containers = []
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    dest_list = None
    if listId:
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == listId and c.get("type") == "LIST" and c.get("status") != "deleted":
                if c.get("workspace_id") in active_ws:
                    dest_list = c
                    break
        if dest_list is None:
            # do not fail if the ID is of a different kind; treat as not found
            _log("NOT_FOUND", detail={"field": "listId", "value": listId})
            return _err("NOT_FOUND", "Destination list not found.", field="listId")
    else:
        ln = listName.strip()
        matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "LIST" and c.get("status") != "deleted" and (c.get("name") or "") == ln and c.get("workspace_id") in active_ws]
        if len(matches) == 1:
            dest_list = matches[0]
        elif len(matches) == 0:
            _log("NOT_FOUND", detail={"field": "listName", "value": ln})
            return _err("NOT_FOUND", "Destination list not found.", field="listName")
        else:
            _log("CONFLICT", detail={"field": "listName", "matches": len(matches)})
            return _err("CONFLICT", "listName is ambiguous; provide listId to disambiguate.", field="listName", matches=len(matches))

    workspace_id = dest_list.get("workspace_id")
    if workspace_id not in active_ws:
        _log("UNAUTHORIZED", workspace_id=workspace_id, list_container_id=dest_list.get("container_id"), detail={"reason": "workspace_not_active"})
        return _err("UNAUTHORIZED", "Workspace is not active for this operation.", workspace_id=workspace_id)

    # ---- Validate parent task (if provided) ----
    parent_clickup_task_id = None
    if parent is not None:
        p = parent.strip()
        parent_candidates = []
        for t in tasks_rows:
            if not isinstance(t, dict): 
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("workspace_id") != workspace_id:
                continue
            if t.get("clickup_task_id") == p or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == p):
                parent_candidates.append(t)
        if len(parent_candidates) == 0:
            _log("NOT_FOUND", workspace_id=workspace_id, list_container_id=dest_list.get("container_id"), detail={"field": "parent"})
            return _err("NOT_FOUND", "Parent task not found in this workspace.", field="parent")
        # if both match (custom id == task id), pick the one with exact clickup_task_id first
        exact = [t for t in parent_candidates if t.get("clickup_task_id") == p]
        chosen = exact[0] if exact else parent_candidates[0]
        parent_clickup_task_id = chosen.get("clickup_task_id")

    # ---- Create task row ----
    existing_clickup_ids = {(t.get("workspace_id"), t.get("clickup_task_id")) for t in tasks_rows if isinstance(t, dict)}
    def _gen_clickup_task_id():
        # vendor-like unique id
        for _ in range(100):
            cid = "CU-" + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(6))
            if (workspace_id, cid) not in existing_clickup_ids:
                return cid
        return "CU-" + uuid.uuid4().hex[:8].upper()

    new_task_id = _gen_id("cu_tsk")
    new_clickup_task_id = _gen_clickup_task_id()
    nowz = _utcnow_z()

    row = {
        "task_id": new_task_id,
        "workspace_id": workspace_id,
        "list_container_id": dest_list.get("container_id"),
        "clickup_task_id": new_clickup_task_id,
        "clickup_custom_id": None,
        "name": nm,
        "description": description,
        "status_name": status,
        "priority": priority,
        "due_date": due_z,
        "start_date": start_z,
        "assignee_user_ids": assigneeUserIds[:] if isinstance(assigneeUserIds, list) else None,
        "parent_clickup_task_id": parent_clickup_task_id,
        "custom_fields": customFields[:] if isinstance(customFields, list) else None,
        "tags": [t.strip() for t in tags if isinstance(t, str) and t.strip()] if isinstance(tags, list) else None,
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }

    tasks_rows.append(row)
    _save("tasks.json", tasks_rows)

    _log("OK", workspace_id=workspace_id, task_id=new_task_id, list_container_id=dest_list.get("container_id"))
    return {"task": row}

def get_task(taskId=None, taskName=None, listName=None, subtasks=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _log(status_s, workspace_id=None, task_id=None, error_code=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().isoformat() + "Z"
            logs.append({
                "request_id": "req_" + now.replace(":", "").replace("-", "").replace(".", ""),
                "endpoint": "get_task",
                "timestamp": now,
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
                "workspace_id": workspace_id,
                "task_id": task_id,
                "error_code": error_code
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    if taskId is None and taskName is None:
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided.")
    if taskId is not None and not isinstance(taskId, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskId must be a string.")
    if taskName is not None and not isinstance(taskName, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskName must be a string.")
    if listName is not None and not isinstance(listName, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "listName must be a string.")
    if subtasks is not None and not isinstance(subtasks, bool):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "subtasks must be a boolean.")

    subtasks = bool(subtasks) if subtasks is not None else False

    tasks = _load("tasks.json")
    containers = _load("containers.json")
    if not isinstance(tasks, list) or not isinstance(containers, list):
        _log("error", None, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unreadable.")

    def _list_id_by_name_in_workspace(ws_id, lname):
        matches = [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == ws_id and c.get("type") == "LIST" and c.get("status") != "deleted" and c.get("name") == lname]
        if len(matches) == 0:
            return None, _err("NOT_FOUND", "List not found in workspace for listName scope.")
        if len(matches) > 1:
            return None, _err("CONFLICT", "Multiple lists matched listName in workspace; cannot disambiguate.", matches=len(matches))
        return matches[0].get("container_id"), None

    found = None
    if taskId is not None:
        # resolve by clickup_task_id or clickup_custom_id
        candidates = [t for t in tasks if isinstance(t, dict) and t.get("status") != "deleted" and (t.get("clickup_task_id") == taskId or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == taskId))]
        if len(candidates) == 0:
            _log("error", None, None, "NOT_FOUND")
            return _err("NOT_FOUND", "Task not found.")
        # should be unique per workspace; if multiple, error
        ws_ids = sorted({t.get("workspace_id") for t in candidates if t.get("workspace_id")})
        if len(candidates) > 1:
            _log("error", None, None, "CONFLICT")
            return _err("CONFLICT", "Multiple tasks matched taskId across workspaces; cannot disambiguate.", matches=len(candidates), workspace_ids=ws_ids)
        found = candidates[0]
    else:
        # name search; must be scoped if ambiguous
        candidates = [t for t in tasks if isinstance(t, dict) and t.get("status") != "deleted" and t.get("name") == taskName]
        if len(candidates) == 0:
            _log("error", None, None, "NOT_FOUND")
            return _err("NOT_FOUND", "Task not found by taskName.")
        if listName is None:
            # ambiguous?
            if len(candidates) > 1:
                _log("error", None, None, "CONFLICT")
                return _err("CONFLICT", "taskName matched multiple tasks; provide listName to disambiguate.", matches=len(candidates))
            found = candidates[0]
        else:
            # Need a workspace context to resolve listName; if candidates span multiple workspaces -> ambiguous
            ws_ids = sorted({t.get("workspace_id") for t in candidates if t.get("workspace_id")})
            if len(ws_ids) != 1:
                _log("error", None, None, "CONFLICT")
                return _err("CONFLICT", "taskName matched tasks in multiple workspaces; cannot resolve listName scope.", workspace_ids=ws_ids)
            ws_id = ws_ids[0]
            list_id, err = _list_id_by_name_in_workspace(ws_id, listName)
            if err:
                _log("error", ws_id, None, err["error"]["code"])
                return err
            scoped = [t for t in candidates if t.get("workspace_id") == ws_id and t.get("list_container_id") == list_id]
            if len(scoped) == 0:
                _log("error", ws_id, None, "NOT_FOUND")
                return _err("NOT_FOUND", "Task not found in specified listName scope.")
            if len(scoped) > 1:
                _log("error", ws_id, None, "CONFLICT")
                return _err("CONFLICT", "Multiple tasks matched taskName within list scope; cannot disambiguate.", matches=len(scoped))
            found = scoped[0]

    ws_id = found.get("workspace_id")
    response = {"task": found}

    if subtasks:
        # include full details for subtasks where parent_clickup_task_id matches this task's clickup_task_id
        pid = found.get("clickup_task_id")
        subs = [t for t in tasks if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") == ws_id and t.get("parent_clickup_task_id") == pid]
        subs.sort(key=lambda x: ((x.get("created_at") or ""), (x.get("task_id") or "")))
        response["subtasks"] = subs

    _log("ok", ws_id, found.get("task_id"), None)
    return response

def update_task(taskId=None, taskName=None, listName=None, name=None, description=None, status=None, priority=None, dueDate=None, startDate=None, assigneeUserIds=None, parent=None, tags=None, customFields=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _log(status_s, workspace_id=None, task_id=None, error_code=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            now = datetime.datetime.utcnow().isoformat() + "Z"
            logs.append({
                "request_id": "req_" + now.replace(":", "").replace("-", "").replace(".", ""),
                "endpoint": "update_task",
                "timestamp": now,
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
                "workspace_id": workspace_id,
                "task_id": task_id,
                "error_code": error_code
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    if taskId is None and taskName is None:
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided.")
    if taskId is not None and not isinstance(taskId, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskId must be a string.")
    if taskName is not None and not isinstance(taskName, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskName must be a string.")
    if listName is not None and not isinstance(listName, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "listName must be a string.")

    # Ensure at least one mutable field provided
    provided = {
        "name": name, "description": description, "status": status, "priority": priority,
        "dueDate": dueDate, "startDate": startDate, "assigneeUserIds": assigneeUserIds,
        "parent": parent, "tags": tags, "customFields": customFields
    }
    if all(v is None for v in provided.values()):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one update field must be provided.")

    # Validate update fields
    if name is not None:
        if not isinstance(name, str) or len(name.strip()) == 0 or len(name) > 1024:
            _log("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string length 1..1024.")
    if description is not None and not isinstance(description, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if status is not None and not isinstance(status, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be a string.")
    if priority is not None:
        if not isinstance(priority, int):
            _log("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer.")
        if priority < 1 or priority > 4:
            _log("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be between 1 and 4 when provided.")
    if dueDate is not None and not isinstance(dueDate, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "dueDate must be an ISO-8601 string.")
    if startDate is not None and not isinstance(startDate, str):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "startDate must be an ISO-8601 string.")
    if assigneeUserIds is not None:
        if not isinstance(assigneeUserIds, list) or not all(isinstance(x, str) for x in assigneeUserIds):
            _log("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "assigneeUserIds must be an array of strings.")
    if tags is not None:
        if not isinstance(tags, list) or not all(isinstance(x, str) for x in tags):
            _log("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of strings.")
    if customFields is not None:
        if not isinstance(customFields, list):
            _log("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "customFields must be an array of {id,value} objects.")
        for cf in customFields:
            if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or len(cf.keys() - {"id", "value"}) != 0:
                _log("error", None, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "customFields must be an array of objects with required keys ['id','value'] and no extra properties.")
            if not isinstance(cf["id"], str) or len(cf["id"]) == 0:
                _log("error", None, None, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "customFields[].id must be a non-empty string.")
    if parent is not None and (not isinstance(parent, str) or len(parent) == 0):
        _log("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent must be a string clickup task id/custom id.")

    tasks = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks, list) or not isinstance(containers, list) or not isinstance(workspaces, list) or not isinstance(activity, list):
        _log("error", None, None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Datastore unreadable.")

    # Resolve target task
    target = None
    if taskId is not None:
        candidates = [t for t in tasks if isinstance(t, dict) and t.get("status") != "deleted" and (t.get("clickup_task_id") == taskId or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == taskId))]
        if len(candidates) == 0:
            _log("error", None, None, "NOT_FOUND")
            return _err("NOT_FOUND", "Task not found.")
        if len(candidates) > 1:
            ws_ids = sorted({t.get("workspace_id") for t in candidates if t.get("workspace_id")})
            _log("error", None, None, "CONFLICT")
            return _err("CONFLICT", "Multiple tasks matched taskId across workspaces; cannot disambiguate.", matches=len(candidates), workspace_ids=ws_ids)
        target = candidates[0]
    else:
        # by taskName
        candidates = [t for t in tasks if isinstance(t, dict) and t.get("status") != "deleted" and t.get("name") == taskName]
        if len(candidates) == 0:
            _log("error", None, None, "NOT_FOUND")
            return _err("NOT_FOUND", "Task not found by taskName.")
        if listName is None:
            # must fail if multiple
            if len(candidates) > 1:
                _log("error", None, None, "CONFLICT")
                return _err("CONFLICT", "taskName matched multiple tasks; provide listName to disambiguate.", matches=len(candidates))
            target = candidates[0]
        else:
            ws_ids = sorted({t.get("workspace_id") for t in candidates if t.get("workspace_id")})
            if len(ws_ids) != 1:
                _log("error", None, None, "CONFLICT")
                return _err("CONFLICT", "taskName matched tasks in multiple workspaces; cannot resolve listName scope.", workspace_ids=ws_ids)
            ws_id = ws_ids[0]
            list_matches = [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == ws_id and c.get("type") == "LIST" and c.get("status") != "deleted" and c.get("name") == listName]
            if len(list_matches) == 0:
                _log("error", ws_id, None, "NOT_FOUND")
                return _err("NOT_FOUND", "List not found in workspace for listName scope.")
            if len(list_matches) > 1:
                _log("error", ws_id, None, "CONFLICT")
                return _err("CONFLICT", "Multiple lists matched listName in workspace; cannot disambiguate.", matches=len(list_matches))
            list_id = list_matches[0].get("container_id")
            scoped = [t for t in candidates if t.get("workspace_id") == ws_id and t.get("list_container_id") == list_id]
            if len(scoped) == 0:
                _log("error", ws_id, None, "NOT_FOUND")
                return _err("NOT_FOUND", "Task not found in specified listName scope.")
            if len(scoped) > 1:
                _log("error", ws_id, None, "CONFLICT")
                return _err("CONFLICT", "Multiple tasks matched taskName within list scope; cannot disambiguate.", matches=len(scoped))
            target = scoped[0]

    ws_id = target.get("workspace_id")
    wsp = next((w for w in workspaces if isinstance(w, dict) and w.get("workspace_id") == ws_id), None)
    if not wsp or wsp.get("status") != "active":
        _log("error", ws_id, target.get("task_id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace context available for this operation.")

    # Validate parent task if provided
    if parent is not None:
        if parent == target.get("clickup_task_id") or (target.get("clickup_custom_id") and parent == target.get("clickup_custom_id")):
            _log("error", ws_id, target.get("task_id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Task cannot be its own parent.")
        parent_task = None
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("workspace_id") != ws_id or t.get("status") == "deleted":
                continue
            if t.get("clickup_task_id") == parent or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == parent):
                parent_task = t
                break
        if parent_task is None:
            _log("error", ws_id, target.get("task_id"), "NOT_FOUND")
            return _err("NOT_FOUND", "Parent task not found in workspace.")
        # set to parent's clickup_task_id
        parent_clickup_task_id = parent_task.get("clickup_task_id")
    else:
        parent_clickup_task_id = None

    # Validate assignees against member cache if present
    if assigneeUserIds is not None:
        members = wsp.get("members_cache")
        if members is not None and isinstance(members, list):
            known_ids = set()
            for m in members:
                if isinstance(m, dict):
                    if isinstance(m.get("id"), str): known_ids.add(m["id"])
                    if isinstance(m.get("user", {}).get("id"), str): known_ids.add(m["user"]["id"])
                    if isinstance(m.get("clickup_user_id"), str): known_ids.add(m["clickup_user_id"])
            unknown = [uid for uid in assigneeUserIds if uid not in known_ids]
            if unknown:
                _log("error", ws_id, target.get("task_id"), "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "One or more assigneeUserIds are not valid workspace member ids.", unknown_user_ids=unknown)

    # Tag validation against SPACE_TAG catalog
    def _get_container(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == cid:
                return c
        return None

    def _find_space_for_list_container(list_container_id):
        cur = _get_container(list_container_id)
        for _ in range(5):
            if cur is None:
                return None
            if cur.get("type") == "SPACE":
                return cur
            pid = cur.get("parent_container_id")
            if pid is None:
                return None
            cur = _get_container(pid)
        return None

    if tags is not None:
        space = _find_space_for_list_container(target.get("list_container_id"))
        if not space or space.get("status") == "deleted":
            _log("error", ws_id, target.get("task_id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cannot validate tags: task list is not under a valid space.")
        space_id = space.get("container_id")
        space_tags = set()
        for a in activity:
            if isinstance(a, dict) and a.get("type") == "SPACE_TAG" and a.get("workspace_id") == ws_id and a.get("space_container_id") == space_id and a.get("status") != "deleted":
                if isinstance(a.get("tag_name"), str):
                    space_tags.add(a["tag_name"])
        missing = [t for t in tags if t not in space_tags]
        if missing:
            _log("error", ws_id, target.get("task_id"), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "One or more tags do not exist in the space tag catalog.", missing_tags=missing, space_container_id=space_id)

    # Apply updates only for provided fields
    now = datetime.datetime.utcnow().isoformat() + "Z"
    updated = False

    if name is not None:
        target["name"] = name
        updated = True
    if description is not None:
        target["description"] = description
        updated = True
    if status is not None:
        target["status_name"] = status
        updated = True
    if priority is not None:
        target["priority"] = priority
        updated = True
    if dueDate is not None:
        target["due_date"] = dueDate
        updated = True
    if startDate is not None:
        target["start_date"] = startDate
        updated = True
    if assigneeUserIds is not None:
        target["assignee_user_ids"] = assigneeUserIds
        updated = True
    if parent is not None:
        target["parent_clickup_task_id"] = parent_clickup_task_id
        updated = True
    if tags is not None:
        target["tags"] = tags
        updated = True
    if customFields is not None:
        target["custom_fields"] = customFields
        updated = True

    if not updated:
        _log("error", ws_id, target.get("task_id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No valid updates were provided.")

    target["updated_at"] = now

    # Persist task update back to tasks.json
    found_idx = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("task_id") == target.get("task_id"):
            found_idx = i
            break
    if found_idx is None:
        _log("error", ws_id, target.get("task_id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found (race).")
    tasks[found_idx] = target
    _save("tasks.json", tasks)

    # If tags provided, also reconcile TASK_TAG activity associations (idempotent)
    if tags is not None:
        import random, string
        def _new_id(prefix, rows, key):
            existing = {r.get(key) for r in rows if isinstance(r, dict)}
            for _ in range(200):
                sfx = "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(20))
                nid = f"{prefix}{sfx}"
                if nid not in existing:
                    return nid
            return f"{prefix}{int(time.time()*1000)}"

        clickup_task_id = target.get("clickup_task_id")
        # Soft-delete removed tag associations
        existing_links = [a for a in activity if isinstance(a, dict) and a.get("type") == "TASK_TAG" and a.get("workspace_id") == ws_id and a.get("clickup_task_id") == clickup_task_id]
        desired = set(tags)
        for a in existing_links:
            tn = a.get("tag_name")
            if tn is None:
                continue
            if tn not in desired and a.get("status") != "deleted":
                a["status"] = "deleted"
                a["updated_at"] = now
        # Add missing
        existing_active = {a.get("tag_name") for a in existing_links if a.get("status") != "deleted"}
        for tn in desired:
            if tn in existing_active:
                continue
            activity.append({
                "activity_id": _new_id("cu_act_", activity, "activity_id"),
                "workspace_id": ws_id,
                "type": "TASK_TAG",
                "task_id": target.get("task_id"),
                "clickup_task_id": clickup_task_id,
                "space_container_id": None,
                "clickup_comment_id": None,
                "comment_text": None,
                "comment_assignee_clickup_user_id": None,
                "notify_all": None,
                "clickup_attachment_id": None,
                "filename": None,
                "source_type": None,
                "source_ref": None,
                "size_bytes": None,
                "tag_name": tn,
                "tag_fg_color": None,
                "tag_bg_color": None,
                "status": "active",
                "created_at": now,
                "updated_at": now
            })
        _save("task_activity.json", activity)

    _log("ok", ws_id, target.get("task_id"), None)
    return {"task": target}

def move_task(taskId=None, taskName=None, sourceListName=None, listId=None, listName=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Observability store (best-effort, no schema provided)
    def _log(status, detail=None):
        try:
            logs = _load("request_log.json")
            logs.append({
                "request_id": "req_" + uuid.uuid4().hex,
                "endpoint": "move_task",
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    # Input validation
    if taskId is not None and not isinstance(taskId, str):
        _log("error", "taskId type")
        return _err("VALIDATION_ERROR", "taskId must be a string")
    if taskName is not None and not isinstance(taskName, str):
        _log("error", "taskName type")
        return _err("VALIDATION_ERROR", "taskName must be a string")
    if sourceListName is not None and not isinstance(sourceListName, str):
        _log("error", "sourceListName type")
        return _err("VALIDATION_ERROR", "sourceListName must be a string")
    if listId is not None:
        if not isinstance(listId, str):
            _log("error", "listId type")
            return _err("VALIDATION_ERROR", "listId must be a string")
        if not re.match(r"^cu_ctr_[0-9A-Z]{18,}$", listId):
            _log("error", "listId pattern")
            return _err("VALIDATION_ERROR", "listId must match ^cu_ctr_[0-9A-Z]{18,}$")
    if listName is not None and not isinstance(listName, str):
        _log("error", "listName type")
        return _err("VALIDATION_ERROR", "listName must be a string")

    if not taskId and not taskName:
        _log("error", "missing task ref")
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required")
    if taskName and not taskId and not sourceListName:
        _log("error", "missing sourceListName")
        return _err("VALIDATION_ERROR", "sourceListName is required when moving by taskName")
    if not listId and not listName:
        _log("error", "missing destination list")
        return _err("VALIDATION_ERROR", "Either listId or listName is required")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks = _load("tasks.json")

    active_ws_ids = {w["workspace_id"] for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws_ids:
        _log("error", "no active workspace")
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request")

    def _container_by_id(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == cid and c.get("status") != "deleted":
                return c
        return None

    def _resolve_list_container_by_id(cid):
        c = _container_by_id(cid)
        if not c or c.get("type") != "LIST":
            return None
        if c.get("workspace_id") not in active_ws_ids:
            return None
        return c

    def _resolve_list_container_by_name(name, workspace_id=None):
        # If workspace_id is provided, scope to it; else search across all active workspaces.
        matches = []
        for c in containers:
            if not isinstance(c, dict): 
                continue
            if c.get("status") == "deleted":
                continue
            if c.get("type") != "LIST":
                continue
            if (c.get("name") or "") != name:
                continue
            if c.get("workspace_id") not in active_ws_ids:
                continue
            if workspace_id is not None and c.get("workspace_id") != workspace_id:
                continue
            matches.append(c)
        if len(matches) == 1:
            return matches[0], None
        if len(matches) == 0:
            return None, "NOT_FOUND"
        return None, "AMBIGUOUS"

    def _resolve_task_by_id_or_custom(tid):
        matches = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("workspace_id") not in active_ws_ids:
                continue
            if t.get("clickup_task_id") == tid or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == tid):
                matches.append(t)
        if len(matches) == 1:
            return matches[0], None
        if len(matches) == 0:
            return None, "NOT_FOUND"
        return None, "AMBIGUOUS"

    def _resolve_task_by_name_scoped(task_name, src_list_name):
        # First resolve source list by name; must be unambiguous (per business rules)
        src_list, reason = _resolve_list_container_by_name(src_list_name, workspace_id=None)
        if reason == "AMBIGUOUS":
            return None, _err("VALIDATION_ERROR", "sourceListName is ambiguous; provide a unique source list name")
        if reason == "NOT_FOUND" or src_list is None:
            return None, _err("NOT_FOUND", "Source list not found")
        src_list_id = src_list.get("container_id")
        wsid = src_list.get("workspace_id")

        matches = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("workspace_id") != wsid:
                continue
            if t.get("list_container_id") != src_list_id:
                continue
            if (t.get("name") or "") == task_name:
                matches.append(t)
        if len(matches) == 1:
            return matches[0], None
        if len(matches) == 0:
            return None, _err("NOT_FOUND", "Task not found in the specified source list")
        return None, _err("VALIDATION_ERROR", "Task name lookup is ambiguous within the specified source list", matches=len(matches))

    # Resolve task
    if taskId:
        task, reason = _resolve_task_by_id_or_custom(taskId)
        if reason == "AMBIGUOUS":
            _log("error", "taskId ambiguous")
            return _err("CONFLICT", "Multiple tasks matched the provided taskId/customId; use a unique id")
        if not task:
            _log("error", "task not found")
            return _err("NOT_FOUND", "Task not found")
    else:
        task, err = _resolve_task_by_name_scoped(taskName, sourceListName)
        if err:
            _log("error", err["error"]["code"])
            return err

    wsid = task.get("workspace_id")
    if wsid not in active_ws_ids:
        _log("error", "workspace disabled")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Resolve destination list
    if listId:
        dest_list = _resolve_list_container_by_id(listId)
        if not dest_list:
            _log("error", "dest list not found")
            return _err("NOT_FOUND", "Destination list not found")
        if dest_list.get("workspace_id") != wsid:
            _log("error", "dest list wrong workspace")
            return _err("VALIDATION_ERROR", "Destination list must be in the same workspace as the task")
    else:
        dest_list, reason = _resolve_list_container_by_name(listName, workspace_id=wsid)
        if reason == "AMBIGUOUS":
            _log("error", "dest list ambiguous")
            return _err("VALIDATION_ERROR", "Destination list name is ambiguous in this workspace; use listId")
        if not dest_list:
            _log("error", "dest list not found")
            return _err("NOT_FOUND", "Destination list not found")

    # Ensure task's current list exists and not deleted
    cur_list = _container_by_id(task.get("list_container_id"))
    if not cur_list or cur_list.get("type") != "LIST":
        _log("error", "current list missing")
        return _err("NOT_FOUND", "Task's current list is not available")

    # Idempotent: already in destination list
    if task.get("list_container_id") == dest_list.get("container_id"):
        _log("ok", "no-op already in list")
        return {
            "task": task,
            "moved": False,
            "destination_list": {"container_id": dest_list.get("container_id"), "name": dest_list.get("name")},
            "meta": {"idempotent": True}
        }

    # Perform move: update list_container_id, refresh updated_at, potentially reset status_name (vendor may change)
    updated = False
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("task_id") == task.get("task_id"):
            tasks[i] = dict(t)
            tasks[i]["list_container_id"] = dest_list.get("container_id")
            # Accept that status may change/reset after move: clear status_name to be refreshed later
            tasks[i]["status_name"] = None
            tasks[i]["updated_at"] = now
            task = tasks[i]
            updated = True
            break

    if not updated:
        _log("error", "task row missing during update")
        return _err("NOT_FOUND", "Task not found")

    _save("tasks.json", tasks)
    _log("ok", "moved")

    return {
        "task": task,
        "moved": True,
        "source_list": {"container_id": cur_list.get("container_id"), "name": cur_list.get("name")},
        "destination_list": {"container_id": dest_list.get("container_id"), "name": dest_list.get("name")}
    }

def duplicate_task(taskId=None, taskName=None, sourceListName=None, listId=None, listName=None, **_extra):
    import json, os, datetime, time, uuid, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, detail=None):
        try:
            logs = _load("request_log.json")
            logs.append({
                "request_id": "req_" + uuid.uuid4().hex,
                "endpoint": "duplicate_task",
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail
            })
            _save("request_log.json", logs)
        except Exception:
            pass

    # Input validation
    if taskId is not None and not isinstance(taskId, str):
        _log("error", "taskId type")
        return _err("VALIDATION_ERROR", "taskId must be a string")
    if taskName is not None and not isinstance(taskName, str):
        _log("error", "taskName type")
        return _err("VALIDATION_ERROR", "taskName must be a string")
    if sourceListName is not None and not isinstance(sourceListName, str):
        _log("error", "sourceListName type")
        return _err("VALIDATION_ERROR", "sourceListName must be a string")
    if listId is not None:
        if not isinstance(listId, str):
            _log("error", "listId type")
            return _err("VALIDATION_ERROR", "listId must be a string")
        if not re.match(r"^cu_ctr_[0-9A-Z]{18,}$", listId):
            _log("error", "listId pattern")
            return _err("VALIDATION_ERROR", "listId must match ^cu_ctr_[0-9A-Z]{18,}$")
    if listName is not None and not isinstance(listName, str):
        _log("error", "listName type")
        return _err("VALIDATION_ERROR", "listName must be a string")

    if not taskId and not taskName:
        _log("error", "missing task ref")
        return _err("VALIDATION_ERROR", "Either taskId or taskName is required")
    if taskName and not taskId and not sourceListName:
        _log("error", "missing sourceListName")
        return _err("VALIDATION_ERROR", "sourceListName is required when duplicating by taskName")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks = _load("tasks.json")

    active_ws_ids = {w["workspace_id"] for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws_ids:
        _log("error", "no active workspace")
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request")

    def _container_by_id(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == cid and c.get("status") != "deleted":
                return c
        return None

    def _resolve_list_container_by_id(cid):
        c = _container_by_id(cid)
        if not c or c.get("type") != "LIST":
            return None
        if c.get("workspace_id") not in active_ws_ids:
            return None
        return c

    def _resolve_list_container_by_name(name, workspace_id=None):
        matches = []
        for c in containers:
            if not isinstance(c, dict):
                continue
            if c.get("status") == "deleted":
                continue
            if c.get("type") != "LIST":
                continue
            if (c.get("name") or "") != name:
                continue
            if c.get("workspace_id") not in active_ws_ids:
                continue
            if workspace_id is not None and c.get("workspace_id") != workspace_id:
                continue
            matches.append(c)
        if len(matches) == 1:
            return matches[0], None
        if len(matches) == 0:
            return None, "NOT_FOUND"
        return None, "AMBIGUOUS"

    def _resolve_task_by_id_or_custom(tid):
        matches = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("workspace_id") not in active_ws_ids:
                continue
            if t.get("clickup_task_id") == tid or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == tid):
                matches.append(t)
        if len(matches) == 1:
            return matches[0], None
        if len(matches) == 0:
            return None, "NOT_FOUND"
        return None, "AMBIGUOUS"

    def _resolve_task_by_name_scoped(task_name, src_list_name):
        src_list, reason = _resolve_list_container_by_name(src_list_name, workspace_id=None)
        if reason == "AMBIGUOUS":
            return None, _err("VALIDATION_ERROR", "sourceListName is ambiguous; provide a unique source list name")
        if reason == "NOT_FOUND" or src_list is None:
            return None, _err("NOT_FOUND", "Source list not found")
        src_list_id = src_list.get("container_id")
        wsid = src_list.get("workspace_id")

        matches = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("workspace_id") != wsid:
                continue
            if t.get("list_container_id") != src_list_id:
                continue
            if (t.get("name") or "") == task_name:
                matches.append(t)
        if len(matches) == 1:
            return matches[0], None, src_list
        if len(matches) == 0:
            return None, _err("NOT_FOUND", "Task not found in the specified source list"), src_list
        return None, _err("VALIDATION_ERROR", "Task name lookup is ambiguous within the specified source list", matches=len(matches)), src_list

    # Resolve source task
    src_list = None
    if taskId:
        src_task, reason = _resolve_task_by_id_or_custom(taskId)
        if reason == "AMBIGUOUS":
            _log("error", "taskId ambiguous")
            return _err("CONFLICT", "Multiple tasks matched the provided taskId/customId; use a unique id")
        if not src_task:
            _log("error", "task not found")
            return _err("NOT_FOUND", "Task not found")
        src_list = _container_by_id(src_task.get("list_container_id"))
        if not src_list or src_list.get("type") != "LIST":
            _log("error", "source list missing")
            return _err("NOT_FOUND", "Source list not found for task")
    else:
        src_task, err, src_list = _resolve_task_by_name_scoped(taskName, sourceListName)
        if err:
            _log("error", err["error"]["code"])
            return err

    wsid = src_task.get("workspace_id")
    if wsid not in active_ws_ids:
        _log("error", "workspace disabled")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Resolve destination list; defaults to source list
    dest_list = None
    if listId or listName:
        if listId:
            dest_list = _resolve_list_container_by_id(listId)
            if not dest_list:
                _log("error", "dest list not found")
                return _err("NOT_FOUND", "Destination list not found")
            if dest_list.get("workspace_id") != wsid:
                _log("error", "dest list wrong workspace")
                return _err("VALIDATION_ERROR", "Destination list must be in the same workspace as the task")
        else:
            dest_list, reason = _resolve_list_container_by_name(listName, workspace_id=wsid)
            if reason == "AMBIGUOUS":
                _log("error", "dest list ambiguous")
                return _err("VALIDATION_ERROR", "Destination list name is ambiguous in this workspace; use listId")
            if not dest_list:
                _log("error", "dest list not found")
                return _err("NOT_FOUND", "Destination list not found")
    else:
        dest_list = src_list

    # Generate new ids, enforce uniqueness
    existing_task_ids = {t.get("task_id") for t in tasks if isinstance(t, dict)}
    def _gen_task_id():
        while True:
            cand = "cu_tsk_" + secrets.token_hex(10)
            if cand not in existing_task_ids:
                return cand

    existing_clickup_ids = {(t.get("workspace_id"), t.get("clickup_task_id")) for t in tasks if isinstance(t, dict) and t.get("clickup_task_id")}
    def _gen_clickup_task_id():
        while True:
            cand = "dup_" + secrets.token_hex(12)
            if (wsid, cand) not in existing_clickup_ids:
                return cand

    new_row = {
        "task_id": _gen_task_id(),
        "workspace_id": wsid,
        "list_container_id": dest_list.get("container_id"),
        "clickup_task_id": _gen_clickup_task_id(),
        "clickup_custom_id": None,  # must not copy
        "name": src_task.get("name"),
        "description": src_task.get("description"),
        "status_name": src_task.get("status_name"),
        "priority": src_task.get("priority"),
        "due_date": src_task.get("due_date"),
        "start_date": src_task.get("start_date"),
        "assignee_user_ids": src_task.get("assignee_user_ids"),
        "parent_clickup_task_id": src_task.get("parent_clickup_task_id"),
        "custom_fields": src_task.get("custom_fields"),
        "tags": src_task.get("tags"),
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Constraints validation (basic)
    nm = new_row.get("name")
    if not isinstance(nm, str) or not (1 <= len(nm) <= 1024):
        _log("error", "name constraint")
        return _err("VALIDATION_ERROR", "Task name must be between 1 and 1024 characters")
    pr = new_row.get("priority")
    if pr is not None:
        if not isinstance(pr, int) or not (1 <= pr <= 4):
            _log("error", "priority constraint")
            return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4")
    au = new_row.get("assignee_user_ids")
    if au is not None:
        if not isinstance(au, list) or any(not isinstance(x, str) for x in au):
            _log("error", "assignees constraint")
            return _err("VALIDATION_ERROR", "assignee_user_ids must be an array of strings")
    cf = new_row.get("custom_fields")
    if cf is not None:
        if not isinstance(cf, list) or any((not isinstance(x, dict) or "id" not in x or "value" not in x) for x in cf):
            _log("error", "custom_fields constraint")
            return _err("VALIDATION_ERROR", "custom_fields must be an array of objects with keys ['id','value']")

    tasks.append(new_row)
    _save("tasks.json", tasks)
    _log("ok", "duplicated")

    return {
        "task": new_row,
        "source_task": {"task_id": src_task.get("task_id"), "clickup_task_id": src_task.get("clickup_task_id")},
        "destination_list": {"container_id": dest_list.get("container_id"), "name": dest_list.get("name")}
    }

def delete_task(taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_task"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, task_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "task_id": task_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if taskId is None and (taskName is None or not isinstance(taskName, str) or not taskName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["taskId", "taskName"]})
        return _err("VALIDATION_ERROR", "You must provide taskId or taskName.", fields=["taskId", "taskName"])
    if taskId is not None and not isinstance(taskId, str):
        _log("VALIDATION_ERROR", detail={"field": "taskId"})
        return _err("VALIDATION_ERROR", "taskId must be a string when provided.", field="taskId")
    if taskName is not None and not isinstance(taskName, str):
        _log("VALIDATION_ERROR", detail={"field": "taskName"})
        return _err("VALIDATION_ERROR", "taskName must be a string when provided.", field="taskName")
    if listName is not None and not isinstance(listName, str):
        _log("VALIDATION_ERROR", detail={"field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string when provided.", field="listName")

    tasks_rows = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(containers, list): containers = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    resolved = None
    if taskId is not None:
        tid = taskId.strip()
        # taskId can be internal task_id OR clickup_task_id OR clickup_custom_id
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("task_id") == tid or t.get("clickup_task_id") == tid or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == tid))]
        if len(candidates) == 1:
            resolved = candidates[0]
        elif len(candidates) > 1:
            # should not happen due to uniqueness, but be safe
            _log("CONFLICT", detail={"field": "taskId", "matches": len(candidates)})
            return _err("CONFLICT", "taskId matched multiple tasks; provide a more specific identifier.", field="taskId", matches=len(candidates))
        else:
            _log("NOT_FOUND", detail={"field": "taskId"})
            return _err("NOT_FOUND", "Task not found.", field="taskId")
    else:
        tn = taskName.strip()
        # Must be disambiguated by listName if multiple
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("name") or "") == tn]
        if listName is not None and listName.strip():
            ln = listName.strip()
            # resolve list containers by name in same workspace
            list_ids_by_ws = {}
            for c in containers:
                if not isinstance(c, dict): 
                    continue
                if c.get("status") == "deleted" or c.get("type") != "LIST":
                    continue
                if (c.get("name") or "") == ln and c.get("workspace_id") in active_ws:
                    list_ids_by_ws.setdefault(c.get("workspace_id"), set()).add(c.get("container_id"))
            scoped = []
            for t in candidates:
                ws = t.get("workspace_id")
                if ws in list_ids_by_ws and t.get("list_container_id") in list_ids_by_ws[ws]:
                    scoped.append(t)
            candidates = scoped

        if len(candidates) == 0:
            _log("NOT_FOUND", detail={"field": "taskName"})
            return _err("NOT_FOUND", "Task not found.", field="taskName")
        if len(candidates) > 1:
            _log("CONFLICT", detail={"field": "taskName", "matches": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous; provide taskId or scope by listName to disambiguate.", field="taskName", matches=len(candidates))
        resolved = candidates[0]

    # mutate
    updated = False
    for t in tasks_rows:
        if isinstance(t, dict) and t.get("task_id") == resolved.get("task_id"):
            if t.get("status") == "deleted":
                _log("NOT_FOUND", workspace_id=t.get("workspace_id"), task_id=t.get("task_id"), detail={"reason": "already_deleted"})
                return _err("NOT_FOUND", "Task not found.", field="taskId")
            t["status"] = "deleted"
            t["updated_at"] = _utcnow_z()
            updated = True
            break

    if not updated:
        _log("NOT_FOUND", detail={"reason": "no_row_matched"})
        return _err("NOT_FOUND", "Task not found.")

    _save("tasks.json", tasks_rows)
    _log("OK", workspace_id=resolved.get("workspace_id"), task_id=resolved.get("task_id"))
    return {"deleted": True, "task_id": resolved.get("task_id"), "clickup_task_id": resolved.get("clickup_task_id")}

