        scoped_ws = None
        if lst_name:
            lists = _list_matches_by_name(lst_name, workspace_id=None)
            if len(lists) == 0:
                return [], "LIST_NOT_FOUND"
            if len(lists) > 1:
                return [], "LIST_AMBIGUOUS"
            scoped_list_ids = {lists[0].get("container_id")}
            scoped_ws = lists[0].get("workspace_id")

        matches = []
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("workspace_id") not in active_ws_ids:
                continue
            if (t.get("name") or "") != task_name:
                continue
            if scoped_list_ids is not None:
                if t.get("workspace_id") != scoped_ws:
                    continue
                if t.get("list_container_id") not in scoped_list_ids:
                    continue
            matches.append(t)
        return matches, None

    # Resolve task
    task = None
    if taskId:
        matches = _resolve_task_by_id_or_custom(taskId)
        if len(matches) == 0:
            _log("error", "task not found")
            return _err("NOT_FOUND", "Task not found")
        if len(matches) > 1:
            _log("error", "taskId ambiguous")
            return _err("CONFLICT", "Multiple tasks matched the provided taskId/customId; use a unique id")
        task = matches[0]
    else:
        matches, reason = _resolve_task_by_name(taskName, listName)
        if reason == "LIST_NOT_FOUND":
            _log("error", "list not found")
            return _err("NOT_FOUND", "List not found")
        if reason == "LIST_AMBIGUOUS":
            _log("error", "list ambiguous")
            return _err("VALIDATION_ERROR", "listName is ambiguous; provide a unique list name")
        if len(matches) == 0:
            _log("error", "task not found")
            return _err("NOT_FOUND", "Task not found")
        if len(matches) > 1:
            _log("error", "taskName ambiguous")
            return _err("VALIDATION_ERROR", "taskName lookup is ambiguous; provide taskId or scope with listName", matches=len(matches))
        task = matches[0]

    wsid = task.get("workspace_id")
    if wsid not in active_ws_ids:
        _log("error", "workspace disabled")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Collect comments for this task (ordered by created_at then activity_id)
    tid_internal = task.get("task_id")
    tid_clickup = task.get("clickup_task_id")

    rows = []
    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "deleted":
            continue
        if a.get("type") != "TASK_COMMENT":
            continue
        if a.get("workspace_id") != wsid:
            continue
        # Match by internal task_id when present; fallback to clickup_task_id
        if tid_internal and a.get("task_id") == tid_internal:
            rows.append(a)
        elif tid_clickup and a.get("clickup_task_id") == tid_clickup:
            rows.append(a)

    def _sort_key(a):
        # created_at is ISO; lex sort is OK for normalized UTC 'Z'
        return (a.get("created_at") or "", a.get("activity_id") or "")
    rows.sort(key=_sort_key)

    # Apply startId cursor (start after this activity_id)
    if startId:
        idx = None
        for i, a in enumerate(rows):
            if a.get("activity_id") == startId or (a.get("clickup_comment_id") == startId):
                idx = i
                break
        if idx is None:
            # Cursor not found: treat as validation error (invalid pagination parameter)
            _log("error", "startId not found")
            return _err("VALIDATION_ERROR", "startId does not match any comment in this result set")
        rows = rows[idx + 1 :]

    # Apply offset start
    offset = start or 0
    if offset:
        if offset > len(rows):
            rows = []
        else:
            rows = rows[offset:]

    # Default page size (vendor-like); not provided in tool params
    page_size = 50
    page = rows[:page_size]
    has_more = len(rows) > page_size
    next_cursor = page[-1].get("activity_id") if (has_more and page) else None

    _log("ok", "listed")

    return {
        "task": {"task_id": task.get("task_id"), "clickup_task_id": task.get("clickup_task_id"), "name": task.get("name")},
        "comments": page,
        "meta": {
            "total": len(page) + (len(rows[page_size:]) if has_more else 0),
            "count": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "page_size": page_size
        }
    }

def create_task_comment(commentText, taskId=None, taskName=None, listName=None, notifyAll=None, assignee=None, **_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_task_comment"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, task_id=None, activity_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "task_id": task_id,
            "activity_id": activity_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(commentText, str) or not commentText.strip():
        _log("VALIDATION_ERROR", detail={"field": "commentText"})
        return _err("VALIDATION_ERROR", "commentText is required and must be a non-empty string.", field="commentText")
    if notifyAll is not None and not isinstance(notifyAll, bool):
        _log("VALIDATION_ERROR", detail={"field": "notifyAll"})
        return _err("VALIDATION_ERROR", "notifyAll must be a boolean when provided.", field="notifyAll")
    if assignee is not None and (not isinstance(assignee, str) or not assignee.strip()):
        _log("VALIDATION_ERROR", detail={"field": "assignee"})
        return _err("VALIDATION_ERROR", "assignee must be a non-empty string when provided.", field="assignee")

    if taskId is None and (taskName is None or not isinstance(taskName, str) or not taskName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["taskId", "taskName"]})
        return _err("VALIDATION_ERROR", "You must provide taskId or taskName.", fields=["taskId", "taskName"])

    # For name-based, require listName (per business rule)
    if taskId is None:
        if listName is None or not isinstance(listName, str) or not listName.strip():
            _log("VALIDATION_ERROR", detail={"field": "listName"})
            return _err("VALIDATION_ERROR", "listName is required when using taskName to resolve a task.", field="listName")
    if listName is not None and not isinstance(listName, str):
        _log("VALIDATION_ERROR", detail={"field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string when provided.", field="listName")
    if taskId is not None and not isinstance(taskId, str):
        _log("VALIDATION_ERROR", detail={"field": "taskId"})
        return _err("VALIDATION_ERROR", "taskId must be a string when provided.", field="taskId")

    tasks_rows = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(containers, list): containers = []
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(activity, list): activity = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # resolve task
    resolved = None
    if taskId is not None:
        tid = taskId.strip()
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("task_id") == tid)]
        if len(candidates) == 0:
            # allow internal id pattern mismatch by also trying clickup ids
            candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("clickup_task_id") == tid or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == tid))]
        if len(candidates) != 1:
            _log("NOT_FOUND", detail={"field": "taskId"})
            return _err("NOT_FOUND", "Task not found.", field="taskId")
        resolved = candidates[0]
    else:
        tn = taskName.strip()
        ln = listName.strip()
        # resolve list(s) by name in active workspaces
        list_ids_by_ws = {}
        for c in containers:
            if not isinstance(c, dict): 
                continue
            if c.get("status") == "deleted" or c.get("type") != "LIST":
                continue
            if (c.get("name") or "") == ln and c.get("workspace_id") in active_ws:
                list_ids_by_ws.setdefault(c.get("workspace_id"), set()).add(c.get("container_id"))
        if not list_ids_by_ws:
            _log("NOT_FOUND", detail={"field": "listName"})
            return _err("NOT_FOUND", "List not found for listName scope.", field="listName")

        candidates = []
        for t in tasks_rows:
            if not isinstance(t, dict): 
                continue
            if t.get("status") == "deleted":
                continue
            ws = t.get("workspace_id")
            if ws not in list_ids_by_ws:
                continue
            if t.get("list_container_id") in list_ids_by_ws[ws] and (t.get("name") or "") == tn:
                candidates.append(t)
        if len(candidates) == 0:
            _log("NOT_FOUND", detail={"field": "taskName"})
            return _err("NOT_FOUND", "Task not found.", field="taskName")
        if len(candidates) > 1:
            _log("CONFLICT", detail={"field": "taskName", "matches": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous within the provided listName scope.", field="taskName", matches=len(candidates))
        resolved = candidates[0]

    workspace_id = resolved.get("workspace_id")

    # validate assignee against workspace member cache when present
    if assignee is not None:
        ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("workspace_id") == workspace_id), None)
        members = (ws_row or {}).get("members_cache")
        if isinstance(members, list):
            member_ids = set()
            for m in members:
                if isinstance(m, dict):
                    mid = m.get("id") or m.get("user_id") or m.get("clickup_user_id")
                    if isinstance(mid, str):
                        member_ids.add(mid)
                elif isinstance(m, str):
                    member_ids.add(m)
            if member_ids and assignee.strip() not in member_ids:
                _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "assignee"})
                return _err("VALIDATION_ERROR", "assignee must be a valid workspace member id.", field="assignee")

    # create activity row
    new_activity_id = _gen_id("cu_act")
    # clickup_comment_id optional; generate a stable-looking one
    clickup_comment_id = _gen_id("cucmt")

    nowz = _utcnow_z()
    row = {
        "activity_id": new_activity_id,
        "workspace_id": workspace_id,
        "type": "TASK_COMMENT",
        "task_id": resolved.get("task_id"),
        "clickup_task_id": resolved.get("clickup_task_id"),
        "space_container_id": None,
        "clickup_comment_id": clickup_comment_id,
        "comment_text": commentText.strip(),
        "comment_assignee_clickup_user_id": assignee.strip() if assignee is not None else None,
        "notify_all": notifyAll if isinstance(notifyAll, bool) else None,
        "clickup_attachment_id": None,
        "filename": None,
        "source_type": None,
        "source_ref": None,
        "size_bytes": None,
        "tag_name": None,
        "tag_fg_color": None,
        "tag_bg_color": None,
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }

    # enforce unique clickup_comment_id per workspace when not null
    if any(isinstance(a, dict) and a.get("workspace_id") == workspace_id and a.get("clickup_comment_id") == clickup_comment_id for a in activity):
        clickup_comment_id = _gen_id("cucmt")
        row["clickup_comment_id"] = clickup_comment_id

    activity.append(row)
    _save("task_activity.json", activity)

    _log("OK", workspace_id=workspace_id, task_id=resolved.get("task_id"), activity_id=new_activity_id)
    return {"comment": row}

def attach_task_file(sourceType, taskId=None, taskName=None, listName=None, filename=None, base64=None, url=None, localPath=None, chunked=None, **_extra):
    import json, os, datetime, uuid, time, base64 as _b64, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "attach_task_file"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, task_id=None, activity_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "task_id": task_id,
            "activity_id": activity_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if sourceType not in ("base64", "url", "local_path", "chunked"):
        _log("VALIDATION_ERROR", detail={"field": "sourceType"})
        return _err("VALIDATION_ERROR", "sourceType must be one of: base64, url, local_path, chunked.", field="sourceType")

    if taskId is None and (taskName is None or not isinstance(taskName, str) or not taskName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["taskId", "taskName"]})
        return _err("VALIDATION_ERROR", "You must provide taskId or taskName.", fields=["taskId", "taskName"])
    if taskId is not None and not isinstance(taskId, str):
        _log("VALIDATION_ERROR", detail={"field": "taskId"})
        return _err("VALIDATION_ERROR", "taskId must be a string when provided.", field="taskId")
    if taskName is not None and not isinstance(taskName, str):
        _log("VALIDATION_ERROR", detail={"field": "taskName"})
        return _err("VALIDATION_ERROR", "taskName must be a string when provided.", field="taskName")
    if listName is not None and not isinstance(listName, str):
        _log("VALIDATION_ERROR", detail={"field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string when provided.", field="listName")
    if filename is not None and (not isinstance(filename, str) or not filename.strip()):
        _log("VALIDATION_ERROR", detail={"field": "filename"})
        return _err("VALIDATION_ERROR", "filename must be a non-empty string when provided.", field="filename")

    tasks_rows = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(containers, list): containers = []
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(activity, list): activity = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # Resolve task (taskName may be ambiguous without listName)
    resolved = None
    if taskId is not None:
        tid = taskId.strip()
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("task_id") == tid)]
        if len(candidates) == 0:
            candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("clickup_task_id") == tid or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == tid))]
        if len(candidates) != 1:
            _log("NOT_FOUND", detail={"field": "taskId"})
            return _err("NOT_FOUND", "Task not found.", field="taskId")
        resolved = candidates[0]
    else:
        tn = taskName.strip()
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("name") or "") == tn]
        if listName is not None and listName.strip():
            ln = listName.strip()
            list_ids_by_ws = {}
            for c in containers:
                if not isinstance(c, dict): 
                    continue
                if c.get("status") == "deleted" or c.get("type") != "LIST":
                    continue
                if (c.get("name") or "") == ln and c.get("workspace_id") in active_ws:
                    list_ids_by_ws.setdefault(c.get("workspace_id"), set()).add(c.get("container_id"))
            scoped = []
            for t in candidates:
                ws = t.get("workspace_id")
                if ws in list_ids_by_ws and t.get("list_container_id") in list_ids_by_ws[ws]:
                    scoped.append(t)
            candidates = scoped
        if len(candidates) == 0:
            _log("NOT_FOUND", detail={"field": "taskName"})
            return _err("NOT_FOUND", "Task not found.", field="taskName")
        if len(candidates) > 1:
            _log("CONFLICT", detail={"field": "taskName", "matches": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous; scope by listName or use taskId.", field="taskName", matches=len(candidates))
        resolved = candidates[0]

    workspace_id = resolved.get("workspace_id")

    # Validate source payload and compute metadata
    src_ref = None
    size_bytes = None
    fn = filename.strip() if isinstance(filename, str) else None

    if sourceType == "base64":
        if fn is None:
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "filename"})
            return _err("VALIDATION_ERROR", "filename is required for base64 attachments.", field="filename")
        if not isinstance(base64, str) or not base64.strip():
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "base64"})
            return _err("VALIDATION_ERROR", "base64 is required for sourceType=base64.", field="base64")
        b64s = base64.strip()
        # enforce <= 10MB decoded
        try:
            pad = (-len(b64s)) % 4
            b64p = b64s + ("=" * pad)
            decoded = _b64.b64decode(b64p, validate=False)
            size_bytes = len(decoded)
        except Exception:
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "base64"})
            return _err("VALIDATION_ERROR", "base64 is not valid base64 data.", field="base64")
        if size_bytes > 10 * 1024 * 1024:
            _log("QUOTA_EXCEEDED", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "base64", "size_bytes": size_bytes})
            return _err("QUOTA_EXCEEDED", "Base64 uploads must be <= 10MB.", field="base64", size_bytes=size_bytes)
        # never store base64 payload: store a synthetic ref
        src_ref = _gen_id("b64ref")

    elif sourceType == "url":
        if not isinstance(url, str) or not url.strip():
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "url"})
            return _err("VALIDATION_ERROR", "url is required for sourceType=url.", field="url")
        u = url.strip()
        p = urllib.parse.urlparse(u)
        if p.scheme not in ("http", "https"):
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "url"})
            return _err("VALIDATION_ERROR", "url must be http or https.", field="url")
        src_ref = u

    elif sourceType == "local_path":
        if not isinstance(localPath, str) or not localPath.strip():
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "localPath"})
            return _err("VALIDATION_ERROR", "localPath is required for sourceType=local_path.", field="localPath")
        lp = localPath.strip()
        if not lp.startswith("/"):
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "localPath"})
            return _err("VALIDATION_ERROR", "localPath must be an absolute path.", field="localPath")
        src_ref = lp
        # optional size if file exists
        try:
            if os.path.exists(lp) and os.path.isfile(lp):
                size_bytes = os.path.getsize(lp)
        except Exception:
            size_bytes = None

    elif sourceType == "chunked":
        if not isinstance(chunked, dict) or "uploadId" not in chunked or any(k not in ("uploadId", "partCount") for k in chunked.keys()):
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "chunked"})
            return _err("VALIDATION_ERROR", "chunked must be an object with required field uploadId (and optional partCount).", field="chunked")
        up = chunked.get("uploadId")
        if not isinstance(up, str) or not up.strip():
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "chunked.uploadId"})
            return _err("VALIDATION_ERROR", "chunked.uploadId must be a non-empty string.", field="chunked.uploadId")
        pc = chunked.get("partCount")
        if pc is not None and (not isinstance(pc, int) or pc < 1):
            _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "chunked.partCount"})
            return _err("VALIDATION_ERROR", "chunked.partCount must be an integer >= 1 when provided.", field="chunked.partCount")
        src_ref = up.strip()

    # enforce attachment size constraint when known
    if size_bytes is not None and (not isinstance(size_bytes, int) or size_bytes < 0 or size_bytes > 10737418240):
        _log("VALIDATION_ERROR", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "size_bytes"})
        return _err("VALIDATION_ERROR", "Attachment size_bytes must be between 0 and 10737418240.", field="size_bytes", size_bytes=size_bytes)

    # Create activity row
    new_activity_id = _gen_id("cu_act")
    new_attachment_id = _gen_id("att")
    nowz = _utcnow_z()

    row = {
        "activity_id": new_activity_id,
        "workspace_id": workspace_id,
        "type": "TASK_ATTACHMENT",
        "task_id": resolved.get("task_id"),
        "clickup_task_id": resolved.get("clickup_task_id"),
        "space_container_id": None,
        "clickup_comment_id": None,
        "comment_text": None,
        "comment_assignee_clickup_user_id": None,
        "notify_all": None,
        "clickup_attachment_id": new_attachment_id,
        "filename": fn,
        "source_type": sourceType,
        "source_ref": src_ref,
        "size_bytes": size_bytes,
        "tag_name": None,
        "tag_fg_color": None,
        "tag_bg_color": None,
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }

    activity.append(row)
    _save("task_activity.json", activity)

    _log("OK", workspace_id=workspace_id, task_id=resolved.get("task_id"), activity_id=new_activity_id)
    return {"attachment": row}

def create_bulk_tasks(tasks, listId=None, listName=None, options=None, **_extra):
    import json, os, datetime, time, uuid, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_bulk_tasks"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _gen_clickup_task_id(existing):
        for _ in range(100):
            cid = "CU-" + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(6))
            if cid not in existing:
                return cid
        return "CU-" + uuid.uuid4().hex[:8].upper()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.isoformat() + "Z", None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid ISO-8601 date-time.", field=field, value=s)

    def _log(status_code, workspace_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(tasks, list) or len(tasks) < 1:
        _log("VALIDATION_ERROR", detail={"field": "tasks"})
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array.", field="tasks")

    if listId is None and (listName is None or not isinstance(listName, str) or not listName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["listId", "listName"]})
        return _err("VALIDATION_ERROR", "You must provide listId or listName.", fields=["listId", "listName"])
    if listId is not None and not isinstance(listId, str):
        _log("VALIDATION_ERROR", detail={"field": "listId"})
        return _err("VALIDATION_ERROR", "listId must be a string when provided.", field="listId")
    if listName is not None and not isinstance(listName, str):
        _log("VALIDATION_ERROR", detail={"field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string when provided.", field="listName")

    if options is not None:
        if not isinstance(options, dict):
            _log("VALIDATION_ERROR", detail={"field": "options"})
            return _err("VALIDATION_ERROR", "options must be an object when provided.", field="options")
        bs = options.get("batchSize")
        cc = options.get("concurrency")
        if bs is not None and (not isinstance(bs, int) or bs < 1):
            _log("VALIDATION_ERROR", detail={"field": "options.batchSize"})
            return _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1.", field="options.batchSize")
        if cc is not None and (not isinstance(cc, int) or cc < 1):
            _log("VALIDATION_ERROR", detail={"field": "options.concurrency"})
            return _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1.", field="options.concurrency")

    # Validate each task item
    for i, it in enumerate(tasks):
        if not isinstance(it, dict):
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}]"})
            return _err("VALIDATION_ERROR", "Each tasks[] item must be an object.", field=f"tasks[{i}]")
        nm = it.get("name")
        if not isinstance(nm, str) or not nm.strip():
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].name"})
            return _err("VALIDATION_ERROR", "Each task requires a non-empty name.", field=f"tasks[{i}].name")
        if len(nm.strip()) > 1024:
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].name"})
            return _err("VALIDATION_ERROR", "Task name length must be <= 1024.", field=f"tasks[{i}].name")

        pr = it.get("priority")
        if pr is not None:
            if not isinstance(pr, int) or pr < 1 or pr > 4:
                _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].priority"})
                return _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4 when provided.", field=f"tasks[{i}].priority")

        au = it.get("assigneeUserIds")
        if au is not None:
            if not isinstance(au, list) or any(not isinstance(x, str) for x in au):
                _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].assigneeUserIds"})
                return _err("VALIDATION_ERROR", "assigneeUserIds must be an array of strings when provided.", field=f"tasks[{i}].assigneeUserIds")

        cfs = it.get("customFields")
        if cfs is not None:
            if not isinstance(cfs, list):
                _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].customFields"})
                return _err("VALIDATION_ERROR", "customFields must be an array when provided.", field=f"tasks[{i}].customFields")
            for j, cf in enumerate(cfs):
                if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or any(k not in ("id", "value") for k in cf.keys()):
                    _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].customFields[{j}]"})
                    return _err("VALIDATION_ERROR", "customFields items must be {id,value} objects only.", field=f"tasks[{i}].customFields[{j}]")
                if not isinstance(cf.get("id"), str) or not cf["id"].strip():
                    _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].customFields[{j}].id"})
                    return _err("VALIDATION_ERROR", "customFields[].id must be a non-empty string.", field=f"tasks[{i}].customFields[{j}].id")

        for df in ("dueDate", "startDate"):
            dtz, e = _parse_dt(it.get(df), f"tasks[{i}].{df}")
            if e:
                _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].{df}"})
                return e

    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")
    workspaces = _load("workspaces.json")
    if not isinstance(containers, list): containers = []
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # resolve destination list
    dest_list = None
    if listId is not None:
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == listId and c.get("type") == "LIST" and c.get("status") != "deleted":
                if c.get("workspace_id") in active_ws:
                    dest_list = c
                    break
        if dest_list is None:
            _log("NOT_FOUND", detail={"field": "listId"})
            return _err("NOT_FOUND", "Destination list not found.", field="listId")
    else:
        ln = listName.strip()
        matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "LIST" and c.get("status") != "deleted" and (c.get("name") or "") == ln and c.get("workspace_id") in active_ws]
        if len(matches) == 1:
            dest_list = matches[0]
        elif len(matches) == 0:
            _log("NOT_FOUND", detail={"field": "listName"})
            return _err("NOT_FOUND", "Destination list not found.", field="listName")
        else:
            _log("CONFLICT", detail={"field": "listName", "matches": len(matches)})
            return _err("CONFLICT", "listName is ambiguous; provide listId to disambiguate.", field="listName", matches=len(matches))

    workspace_id = dest_list.get("workspace_id")
    existing_vendor_ids = {t.get("clickup_task_id") for t in tasks_rows if isinstance(t, dict) and t.get("workspace_id") == workspace_id}
    nowz = _utcnow_z()

    created = []
    per_item = []
    for i, it in enumerate(tasks):
        # idempotency "where possible": if an identical vendor id was provided we'd reuse; but create has no id input.
        # So we always create, but each mutation is recorded individually via request_log by endpoint call already.
        nm = it.get("name").strip()

        due_z, _ = _parse_dt(it.get("dueDate"), f"tasks[{i}].dueDate")
        start_z, _ = _parse_dt(it.get("startDate"), f"tasks[{i}].startDate")

        new_task_id = _gen_id("cu_tsk")
        new_clickup_task_id = _gen_clickup_task_id(existing_vendor_ids)
        existing_vendor_ids.add(new_clickup_task_id)

        row = {
            "task_id": new_task_id,
            "workspace_id": workspace_id,
            "list_container_id": dest_list.get("container_id"),
            "clickup_task_id": new_clickup_task_id,
            "clickup_custom_id": None,
            "name": nm,
            "description": it.get("description") if isinstance(it.get("description"), str) else it.get("description"),
            "status_name": it.get("statusName") if isinstance(it.get("statusName"), str) else it.get("statusName"),
            "priority": it.get("priority"),
            "due_date": due_z,
            "start_date": start_z,
            "assignee_user_ids": it.get("assigneeUserIds")[:] if isinstance(it.get("assigneeUserIds"), list) else None,
            "parent_clickup_task_id": it.get("parentClickupTaskId") if isinstance(it.get("parentClickupTaskId"), str) else None,
            "custom_fields": it.get("customFields")[:] if isinstance(it.get("customFields"), list) else None,
            "tags": [t.strip() for t in it.get("tags") if isinstance(t, str) and t.strip()] if isinstance(it.get("tags"), list) else None,
            "status": "active",
            "created_at": nowz,
            "updated_at": nowz
        }
        tasks_rows.append(row)
        created.append(row)
        per_item.append({"index": i, "status": "created", "task_id": new_task_id, "clickup_task_id": new_clickup_task_id})

    _save("tasks.json", tasks_rows)
    _log("OK", workspace_id=workspace_id, detail={"created": len(created)})
    return {"tasks": created, "results": per_item}

def update_bulk_tasks(tasks, options=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "update_bulk_tasks"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, workspace_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": f"req_{uuid.uuid4().hex}",
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status,
            "detail": detail,
            "latency_ms": int((time.time() - _t0) * 1000),
            "ts": _now_iso()
        })
        _save("request_log.json", logs)

    def _pick_workspace():
        wss = _load("workspaces.json")
        if not isinstance(wss, list): wss = []
        for w in wss:
            if isinstance(w, dict) and w.get("status") == "active":
                return w
        return None

    def _parse_dt(s, field):
        if s is None:
            return (None, None, None)
        if not isinstance(s, str):
            return ("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string.", None)
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return (None, None, dt.astimezone(datetime.timezone.utc).isoformat())
        except ValueError:
            return ("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string.", None)

    def _resolve_list_by_name(workspace_id, name):
        ctrs = _load("containers.json")
        if not isinstance(ctrs, list): ctrs = []
        matches = []
        for c in ctrs:
            if not isinstance(c, dict): 
                continue
            if c.get("workspace_id") != workspace_id:
                continue
            if c.get("status") == "deleted":
                continue
            if c.get("type") != "LIST":
                continue
            if c.get("name") == name:
                matches.append(c)
        return matches

    def _resolve_task(workspace_id, op, trows):
        task_id = op.get("taskId")
        task_name = op.get("taskName")
        list_name = op.get("listName")

        if task_id is not None:
            if not isinstance(task_id, str) or not re.match(r"^cu_tsk_[0-9A-Z]{18}$", task_id):
                return ("VALIDATION_ERROR", "taskId must match ^cu_tsk_[0-9A-Z]{18}$.", None)
            for t in trows:
                if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("status") != "deleted" and t.get("task_id") == task_id:
                    return (None, None, t)
            return ("NOT_FOUND", "Task not found.", None)

        if task_name is None:
            return ("VALIDATION_ERROR", "Each task update must include taskId or taskName+listName.", None)
        if not isinstance(task_name, str) or not task_name.strip():
            return ("VALIDATION_ERROR", "taskName must be a non-empty string when provided.", None)
        if list_name is None:
            return ("VALIDATION_ERROR", "When using taskName, listName is required (taskName without listName will fail).", None)
        if not isinstance(list_name, str) or not list_name.strip():
            return ("VALIDATION_ERROR", "listName must be a non-empty string.", None)

        lists = _resolve_list_by_name(workspace_id, list_name)
        if len(lists) == 0:
            return ("NOT_FOUND", "List not found for provided listName.", None)
        if len(lists) > 1:
            return ("CONFLICT", "Multiple lists match listName; provide taskId.", None)
        list_id = lists[0].get("container_id")

        matches = []
        for t in trows:
            if not isinstance(t, dict):
                continue
            if t.get("workspace_id") != workspace_id:
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("list_container_id") != list_id:
                continue
            if t.get("name") == task_name:
                matches.append(t)
        if len(matches) == 0:
            return ("NOT_FOUND", "Task not found for provided taskName within listName.", None)
        if len(matches) > 1:
            return ("CONFLICT", "Multiple tasks match taskName within listName; use taskId.", None)
        return (None, None, matches[0])

    # Validate tasks
    if not isinstance(tasks, list) or len(tasks) < 1:
        _log("error", detail="tasks_empty")
        return _err("VALIDATION_ERROR", "tasks is required and must be a non-empty array.")
    if options is not None and not isinstance(options, dict):
        _log("error", detail="bad_options")
        return _err("VALIDATION_ERROR", "options must be an object when provided.")
    if isinstance(options, dict):
        bs = options.get("batchSize")
        cc = options.get("concurrency")
        if bs is not None and (not isinstance(bs, int) or bs < 1):
            _log("error", detail="bad_batchSize")
            return _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1 when provided.")
        if cc is not None and (not isinstance(cc, int) or cc < 1):
            _log("error", detail="bad_concurrency")
            return _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1 when provided.")

    workspace = _pick_workspace()
    if not workspace:
        _log("error", detail="no_active_workspace")
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")
    workspace_id = workspace.get("workspace_id")

    trows = _load("tasks.json")
    if not isinstance(trows, list): trows = []

    now = _now_iso()
    updated_any = False
    results = []

    for idx, op in enumerate(tasks):
        if not isinstance(op, dict):
            results.append({"index": idx, "error": _err("VALIDATION_ERROR", "Each tasks[] item must be an object.")["error"]})
            continue
        upd = op.get("update")
        if not isinstance(upd, dict) or len(upd) == 0:
            results.append({"index": idx, "error": _err("VALIDATION_ERROR", "update must be an object with at least one field.")["error"]})
            continue

        code, msg, task = _resolve_task(workspace_id, op, trows)
        if code:
            results.append({"index": idx, "error": _err(code, msg)["error"]})
            continue

        # Apply only provided fields; validate per schema/tool
        newvals = {}
        if "name" in upd:
            v = upd.get("name")
            if not isinstance(v, str) or not (1 <= len(v) <= 1024):
                results.append({"index": idx, "error": _err("VALIDATION_ERROR", "name length must be between 1 and 1024.")["error"]})
                continue
            newvals["name"] = v
        if "description" in upd:
            v = upd.get("description")
            if v is not None and not isinstance(v, str):
                results.append({"index": idx, "error": _err("VALIDATION_ERROR", "description must be a string when provided.")["error"]})
                continue
            newvals["description"] = v
        if "statusName" in upd:
            v = upd.get("statusName")
            if v is not None and not isinstance(v, str):
                results.append({"index": idx, "error": _err("VALIDATION_ERROR", "statusName must be a string when provided.")["error"]})
                continue
            newvals["status_name"] = v
        if "priority" in upd:
            v = upd.get("priority")
            if v is not None and (not isinstance(v, int) or v < 1 or v > 4):
                results.append({"index": idx, "error": _err("VALIDATION_ERROR", "priority must be an integer between 1 and 4 when provided.")["error"]})
                continue
            newvals["priority"] = v
        if "dueDate" in upd:
            c, m, iso = _parse_dt(upd.get("dueDate"), "dueDate")
            if c:
                results.append({"index": idx, "error": _err(c, m)["error"]})
                continue
            newvals["due_date"] = iso
        if "startDate" in upd:
            c, m, iso = _parse_dt(upd.get("startDate"), "startDate")
            if c:
                results.append({"index": idx, "error": _err(c, m)["error"]})
                continue
            newvals["start_date"] = iso
        if "assigneeUserIds" in upd:
            v = upd.get("assigneeUserIds")
            if v is not None:
                if not isinstance(v, list) or any((not isinstance(a, str)) for a in v):
                    results.append({"index": idx, "error": _err("VALIDATION_ERROR", "assigneeUserIds must be an array of strings when provided.")["error"]})
                    continue
            newvals["assignee_user_ids"] = v
        if "tags" in upd:
            v = upd.get("tags")
            if v is not None:
                if not isinstance(v, list) or any((not isinstance(a, str)) for a in v):
                    results.append({"index": idx, "error": _err("VALIDATION_ERROR", "tags must be an array of strings when provided.")["error"]})
                    continue
            newvals["tags"] = v
        if "parentClickupTaskId" in upd:
            v = upd.get("parentClickupTaskId")
            if v is not None and (not isinstance(v, str) or not v.strip()):
                results.append({"index": idx, "error": _err("VALIDATION_ERROR", "parentClickupTaskId must be a non-empty string when provided.")["error"]})
                continue
            # If provided non-null, must exist in workspace
            if v is not None:
                ok = False
                for t in trows:
                    if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("status") != "deleted" and t.get("clickup_task_id") == v:
                        ok = True
                        break
                if not ok:
                    results.append({"index": idx, "error": _err("NOT_FOUND", "parentClickupTaskId does not match an existing task in this workspace.")["error"]})
                    continue
            newvals["parent_clickup_task_id"] = v
        if "customFields" in upd:
            v = upd.get("customFields")
            if v is not None:
                if not isinstance(v, list):
                    results.append({"index": idx, "error": _err("VALIDATION_ERROR", "customFields must be an array of {id,value} objects when provided.")["error"]})
                    continue
                bad = False
                for cf in v:
                    if not isinstance(cf, dict) or "id" not in cf or "value" not in cf or len(cf.keys() - {"id", "value"}) != 0:
                        bad = True
                        break
                    if not isinstance(cf.get("id"), str) or not cf.get("id"):
                        bad = True
                        break
                if bad:
                    results.append({"index": idx, "error": _err("VALIDATION_ERROR", "customFields items must be objects with required keys ['id','value'] and no additional properties.")["error"]})
                    continue
            newvals["custom_fields"] = v

        if not newvals:
            results.append({"index": idx, "error": _err("VALIDATION_ERROR", "At least one mutable field must be provided in update.")["error"]})
            continue

        # Apply updates
        for k, v in newvals.items():
            task[k] = v
        task["updated_at"] = now
        updated_any = True
        results.append({"index": idx, "task": task})

    if updated_any:
        _save("tasks.json", trows)
        # Touch workspace updated_at
        wss = _load("workspaces.json")
        if not isinstance(wss, list): wss = []
        for w in wss:
            if isinstance(w, dict) and w.get("workspace_id") == workspace_id:
                w["updated_at"] = now
                break
        _save("workspaces.json", wss)

    _log("ok", workspace_id=workspace_id, detail=f"updated_any={updated_any}")
    return {
        "results": results,
        "requested_count": len(tasks),
        "updated_count": sum(1 for r in results if isinstance(r, dict) and "task" in r)
    }

def move_bulk_tasks(tasks, targetListId=None, targetListName=None, options=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "move_bulk_tasks"

    # --- request log / rate limit helpers ---
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, workspace_id=None, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        rec = {
            "request_id": f"req_{base64.urlsafe_b64encode(os.urandom(9)).decode('ascii').rstrip('=')}",
            "endpoint": endpoint,
            "status": status,
            "workspace_id": workspace_id,
            "latency_ms": latency_ms,
            "ts": _now_iso()
        }
        if detail is not None:
            rec["detail"] = detail
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(rec)
        _save("request_log.json", logs)

    def _rate_limit_check():
        # Simple fixed window: 600 req / 60s across server
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < window:
                break
            cnt += 1
        if cnt >= 600:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_check()
    if not ok_rl:
        _log("RATE_LIMIT")
        return rl_err

    # --- validation ---
    if not isinstance(tasks, list) or len(tasks) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array")

    if options is not None and not isinstance(options, dict):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "options must be an object when provided")
    batch_size = None
    concurrency = None
    if isinstance(options, dict):
        if "batchSize" in options:
            batch_size = options.get("batchSize")
            if not isinstance(batch_size, int) or batch_size < 1:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1")
        if "concurrency" in options:
            concurrency = options.get("concurrency")
            if not isinstance(concurrency, int) or concurrency < 1:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1")

    if targetListId is None and targetListName is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Exactly one target list must be specified via targetListId or targetListName")

    if targetListId is not None:
        if not isinstance(targetListId, str) or not re.match(r"^cu_ctr_[0-9A-Z]{18}$", targetListId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "targetListId must match ^cu_ctr_[0-9A-Z]{18}$")
    if targetListName is not None and (not isinstance(targetListName, str) or not targetListName.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "targetListName must be a non-empty string when provided")

    # validate each task ref minimal structure
    for i, it in enumerate(tasks):
        if not isinstance(it, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"tasks[{i}] must be an object")
        taskId = it.get("taskId")
        taskName = it.get("taskName")
        listName = it.get("listName")
        if taskId is None:
            if taskName is None or listName is None:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"tasks[{i}] must include taskId or (taskName + listName)")
            if not isinstance(taskName, str) or not taskName.strip():
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"tasks[{i}].taskName must be a non-empty string")
            if not isinstance(listName, str) or not listName.strip():
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"tasks[{i}].listName must be a non-empty string")
        else:
            if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]{18}$", taskId):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"tasks[{i}].taskId must match ^cu_tsk_[0-9A-Z]{{18}}$")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    task_rows = _load("tasks.json")

    if not isinstance(workspaces, list) or not isinstance(containers, list) or not isinstance(task_rows, list):
        _log("CONFLICT")
        return _err("CONFLICT", "Datastore is not in expected format")

    # --- resolve target list container (must be active, type LIST) ---
    target_list = None
    if targetListId is not None:
        target_list = next((c for c in containers if c.get("container_id") == targetListId and c.get("status") != "deleted"), None)
        if target_list is None or target_list.get("type") != "LIST":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Target list not found", targetListId=targetListId)
    else:
        # resolve by name; must be unique among active LISTs, else conflict/validation
        matches = [c for c in containers if c.get("status") != "deleted" and c.get("type") == "LIST" and isinstance(c.get("name"), str) and c.get("name") == targetListName]
        if len(matches) == 0:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Target list not found", targetListName=targetListName)
        if len(matches) > 1:
            _log("CONFLICT")
            return _err("CONFLICT", "Multiple target lists match targetListName; supply targetListId", matches=[m.get("container_id") for m in matches[:50]])
        target_list = matches[0]

    workspace_id = target_list.get("workspace_id")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id and w.get("status") == "active"), None)
    if wsp is None:
        _log("UNAUTHORIZED", workspace_id=workspace_id)
        return _err("UNAUTHORIZED", "No active workspace context available for this operation")

    # helper: resolve list by name within same workspace and active
    def _resolve_list_by_name_in_workspace(wid, lname):
        ms = [c for c in containers if c.get("workspace_id") == wid and c.get("status") != "deleted" and c.get("type") == "LIST" and c.get("name") == lname]
        if len(ms) == 0:
            return None, _err("NOT_FOUND", "List not found for listName", listName=lname)
        if len(ms) > 1:
            return None, _err("CONFLICT", "Multiple lists match listName within workspace; disambiguate by id", listName=lname, matches=[m.get("container_id") for m in ms[:50]])
        return ms[0], None

    # helper: resolve task by id or by (name within list)
    def _resolve_task(ref):
        if ref.get("taskId") is not None:
            t = next((x for x in task_rows if x.get("task_id") == ref.get("taskId") and x.get("status") != "deleted"), None)
            if t is None:
                return None, _err("NOT_FOUND", "Task not found", taskId=ref.get("taskId"))
            return t, None
        lname = ref.get("listName")
        lst, e = _resolve_list_by_name_in_workspace(workspace_id, lname)
        if e:
            return None, e
        tname = ref.get("taskName")
        ms = [x for x in task_rows if x.get("workspace_id") == workspace_id and x.get("status") != "deleted" and x.get("list_container_id") == lst.get("container_id") and x.get("name") == tname]
        if len(ms) == 0:
            return None, _err("NOT_FOUND", "Task not found in list", taskName=tname, listName=lname)
        if len(ms) > 1:
            return None, _err("CONFLICT", "Multiple tasks match taskName within list; use taskId", taskName=tname, listName=lname, matches=[m.get("task_id") for m in ms[:50]])
        return ms[0], None

    # resolve all first; fail fast if any invalid/missing (per tool description expectations)
    resolved = []
    for i, ref in enumerate(tasks):
        t, e = _resolve_task(ref)
        if e:
            _log(e["error"]["code"], workspace_id=workspace_id, detail={"index": i, "ref": ref})
            return e
        # must be same workspace as target
        if t.get("workspace_id") != workspace_id:
            _log("CONFLICT", workspace_id=workspace_id, detail={"index": i, "task_id": t.get("task_id")})
            return _err("CONFLICT", "Task workspace does not match target list workspace", taskId=t.get("task_id"))
        resolved.append(t)

    # perform idempotent moves; update list_container_id if needed; refresh updated_at
    now = _now_iso()
    updated = []
    moved_count = 0
    for t in resolved:
        if t.get("status") == "deleted":
            # should not happen due to resolver, but keep rule
            _log("NOT_FOUND", workspace_id=workspace_id)
            return _err("NOT_FOUND", "Cannot move a deleted task", taskId=t.get("task_id"))
        if t.get("list_container_id") != target_list.get("container_id"):
            t["list_container_id"] = target_list.get("container_id")
            # vendor move can change/reset status_name; mark unknown/None to signal refresh needed
            t["status_name"] = None
            t["updated_at"] = now
            moved_count += 1
        updated.append(t)

    if moved_count == 0:
        # No success without effect: but operation is idempotent; return current task records with metadata.
        _log("OK", workspace_id=workspace_id, detail={"moved": 0, "idempotent": True})
        return {
            "workspace_id": workspace_id,
            "target_list_id": target_list.get("container_id"),
            "moved": 0,
            "tasks": updated
        }

    _save("tasks.json", task_rows)
    _log("OK", workspace_id=workspace_id, detail={"moved": moved_count})
    return {
        "workspace_id": workspace_id,
        "target_list_id": target_list.get("container_id"),
        "moved": moved_count,
        "tasks": updated
    }

def delete_bulk_tasks(tasks, options=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_bulk_tasks"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(tasks, list) or len(tasks) < 1:
        _log("VALIDATION_ERROR", detail={"field": "tasks"})
        return _err("VALIDATION_ERROR", "tasks must be a non-empty array.", field="tasks")

    if options is not None:
        if not isinstance(options, dict):
            _log("VALIDATION_ERROR", detail={"field": "options"})
            return _err("VALIDATION_ERROR", "options must be an object when provided.", field="options")
        bs = options.get("batchSize")
        cc = options.get("concurrency")
        if bs is not None and (not isinstance(bs, int) or bs < 1):
            _log("VALIDATION_ERROR", detail={"field": "options.batchSize"})
            return _err("VALIDATION_ERROR", "options.batchSize must be an integer >= 1.", field="options.batchSize")
        if cc is not None and (not isinstance(cc, int) or cc < 1):
            _log("VALIDATION_ERROR", detail={"field": "options.concurrency"})
            return _err("VALIDATION_ERROR", "options.concurrency must be an integer >= 1.", field="options.concurrency")

    # validate items
    for i, it in enumerate(tasks):
        if not isinstance(it, dict):
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}]"})
            return _err("VALIDATION_ERROR", "Each tasks[] item must be an object.", field=f"tasks[{i}]")
        tid = it.get("taskId")
        tn = it.get("taskName")
        ln = it.get("listName")
        if tid is None and (tn is None or not isinstance(tn, str) or not tn.strip()):
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}]"})
            return _err("VALIDATION_ERROR", "Each task item must include taskId or taskName.", field=f"tasks[{i}]")
        if tid is not None and not isinstance(tid, str):
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].taskId"})
            return _err("VALIDATION_ERROR", "taskId must be a string when provided.", field=f"tasks[{i}].taskId")
        if tn is not None and not isinstance(tn, str):
            _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].taskName"})
            return _err("VALIDATION_ERROR", "taskName must be a string when provided.", field=f"tasks[{i}].taskName")
        if tid is None:
            if ln is None or not isinstance(ln, str) or not ln.strip():
                _log("VALIDATION_ERROR", detail={"field": f"tasks[{i}].listName"})
                return _err("VALIDATION_ERROR", "listName is required when deleting by taskName.", field=f"tasks[{i}].listName")

    tasks_rows = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(containers, list): containers = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # index lists by name per workspace
    lists_by_ws_name = {}
    for c in containers:
        if not isinstance(c, dict): 
            continue
        if c.get("status") == "deleted" or c.get("type") != "LIST":
            continue
        ws = c.get("workspace_id")
        if ws in active_ws:
            lists_by_ws_name.setdefault(ws, {}).setdefault(c.get("name") or "", []).append(c.get("container_id"))

    def _resolve_task(item):
        tid = item.get("taskId")
        if tid is not None:
            x = tid.strip()
            matches = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("task_id") == x or t.get("clickup_task_id") == x or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == x))]
            if len(matches) == 1:
                return matches[0], None
            if len(matches) == 0:
                return None, _err("NOT_FOUND", "Task not found.", field="taskId", value=tid)
            return None, _err("CONFLICT", "taskId matched multiple tasks.", field="taskId", matches=len(matches))
        tn = item.get("taskName").strip()
        ln = item.get("listName").strip()
        candidates = []
        for t in tasks_rows:
            if not isinstance(t, dict): 
                continue
            if t.get("status") == "deleted":
                continue
            ws = t.get("workspace_id")
            if ws not in active_ws:
                continue
            if (t.get("name") or "") != tn:
                continue
            list_ids = lists_by_ws_name.get(ws, {}).get(ln, [])
            if list_ids and t.get("list_container_id") in set(list_ids):
                candidates.append(t)
        if len(candidates) == 1:
            return candidates[0], None
        if len(candidates) == 0:
            return None, _err("NOT_FOUND", "Task not found.", field="taskName", value=item.get("taskName"))
        return None, _err("CONFLICT", "taskName is ambiguous within the provided listName scope.", field="taskName", matches=len(candidates))

    nowz = _utcnow_z()
    results = []
    any_deleted = False

    for i, item in enumerate(tasks):
        task, e = _resolve_task(item)
        if e:
            results.append({"index": i, "deleted": False, "error": e["error"]})
            continue

        # delete (idempotent-ish: if already deleted, report not found style for this item)
        mutated = False
        for t in tasks_rows:
            if isinstance(t, dict) and t.get("task_id") == task.get("task_id"):
                if t.get("status") == "deleted":
                    results.append({"index": i, "deleted": False, "error": {"code": "NOT_FOUND", "message": "Task not found (already deleted)."}})
                    mutated = False
                else:
                    t["status"] = "deleted"
                    t["updated_at"] = nowz
                    mutated = True
                    any_deleted = True
                    results.append({"index": i, "deleted": True, "task_id": t.get("task_id"), "clickup_task_id": t.get("clickup_task_id")})
                break
        else:
            results.append({"index": i, "deleted": False, "error": {"code": "NOT_FOUND", "message": "Task not found."}})

    if any_deleted:
        _save("tasks.json", tasks_rows)
        _log("OK", detail={"deleted": sum(1 for r in results if r.get("deleted"))})
    else:
        # No success without effect: if nothing deleted and all failed, keep OK? Real bulk APIs return per-item errors.
        # But endpoint call itself "succeeds" with results; still log accordingly.
        _log("OK", detail={"deleted": 0})

    return {"results": results}

def get_workspace_tasks(workspaceId, tags=None, listIds=None, folderIds=None, spaceIds=None, statuses=None, assignees=None, dueFrom=None, dueTo=None, startFrom=None, startTo=None, updatedFrom=None, updatedTo=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_workspace_tasks"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, workspace_id=None, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        rec = {
            "request_id": f"req_{base64.urlsafe_b64encode(os.urandom(9)).decode('ascii').rstrip('=')}",
            "endpoint": endpoint,
            "status": status,
            "workspace_id": workspace_id,
            "latency_ms": latency_ms,
            "ts": _now_iso()
        }
        if detail is not None:
            rec["detail"] = detail
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(rec)
        _save("request_log.json", logs)

    def _rate_limit_check():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < window:
                break
            cnt += 1
        if cnt >= 1200:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_check()
    if not ok_rl:
        _log("RATE_LIMIT", workspace_id=workspaceId)
        return rl_err

    if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18}$", workspaceId):
        _log("VALIDATION_ERROR", workspace_id=workspaceId)
        return _err("VALIDATION_ERROR", "workspaceId must match ^cu_wsp_[0-9A-Z]{18}$")

    # must have at least one filter
    has_filter = any([
        tags is not None, listIds is not None, folderIds is not None, spaceIds is not None,
        statuses is not None, assignees is not None,
        dueFrom is not None, dueTo is not None, startFrom is not None, startTo is not None, updatedFrom is not None, updatedTo is not None
    ])
    if not has_filter:
        _log("VALIDATION_ERROR", workspace_id=workspaceId)
        return _err("VALIDATION_ERROR", "At least one filter parameter is required")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")

    due_from, e = _parse_dt(dueFrom, "dueFrom")
    if e: _log(e["error"]["code"], workspace_id=workspaceId); return e
    due_to, e = _parse_dt(dueTo, "dueTo")
    if e: _log(e["error"]["code"], workspace_id=workspaceId); return e
    start_from, e = _parse_dt(startFrom, "startFrom")
    if e: _log(e["error"]["code"], workspace_id=workspaceId); return e
    start_to, e = _parse_dt(startTo, "startTo")
    if e: _log(e["error"]["code"], workspace_id=workspaceId); return e
    upd_from, e = _parse_dt(updatedFrom, "updatedFrom")
    if e: _log(e["error"]["code"], workspace_id=workspaceId); return e
    upd_to, e = _parse_dt(updatedTo, "updatedTo")
    if e: _log(e["error"]["code"], workspace_id=workspaceId); return e

    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log("VALIDATION_ERROR", workspace_id=workspaceId)
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1 when provided")

    if sortBy is not None and sortBy not in ["created_at", "updated_at", "due_date", "start_date", "priority", "name"]:
        _log("VALIDATION_ERROR", workspace_id=workspaceId)
        return _err("VALIDATION_ERROR", "Invalid sortBy")
    if sortOrder is not None and sortOrder not in ["asc", "desc"]:
        _log("VALIDATION_ERROR", workspace_id=workspaceId)
        return _err("VALIDATION_ERROR", "Invalid sortOrder")
    if sortOrder is None:
        sortOrder = "desc"

    # array validations
    def _val_arr(a, name, item_pat=None):
        if a is None:
            return None
        if not isinstance(a, list):
            raise ValueError(name)
        out = []
        for v in a:
            if not isinstance(v, str):
                raise ValueError(name)
            if item_pat is not None and not re.match(item_pat, v):
                raise ValueError(name)
            out.append(v)
        return out

    try:
        tags = _val_arr(tags, "tags")
        listIds = _val_arr(listIds, "listIds", r"^cu_ctr_[0-9A-Z]{18}$")
        folderIds = _val_arr(folderIds, "folderIds", r"^cu_ctr_[0-9A-Z]{18}$")
        spaceIds = _val_arr(spaceIds, "spaceIds", r"^cu_ctr_[0-9A-Z]{18}$")
        statuses = _val_arr(statuses, "statuses")
        assignees = _val_arr(assignees, "assignees")
    except ValueError as ve:
        _log("VALIDATION_ERROR", workspace_id=workspaceId)
        return _err("VALIDATION_ERROR", f"{str(ve)} must be an array of strings with valid values")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks = _load("tasks.json")
    if not isinstance(workspaces, list) or not isinstance(containers, list) or not isinstance(tasks, list):
        _log("CONFLICT", workspace_id=workspaceId)
        return _err("CONFLICT", "Datastore is not in expected format")

    wsp = next((w for w in workspaces if w.get("workspace_id") == workspaceId and w.get("status") == "active"), None)
    if wsp is None:
        _log("UNAUTHORIZED", workspace_id=workspaceId)
        return _err("UNAUTHORIZED", "No active workspace context available for this operation")

    # build container ancestry maps for list->folder/space
    by_id = {c.get("container_id"): c for c in containers if isinstance(c, dict)}
    def _space_for_list(list_container_id):
        cur = by_id.get(list_container_id)
        seen = set()
        while cur and cur.get("container_id") not in seen:
            seen.add(cur.get("container_id"))
            if cur.get("type") == "SPACE":
                return cur.get("container_id")
            pid = cur.get("parent_container_id")
            if not pid:
                break
            cur = by_id.get(pid)
        return None

    def _folder_for_list(list_container_id):
        cur = by_id.get(list_container_id)
        seen = set()
        while cur and cur.get("container_id") not in seen:
            seen.add(cur.get("container_id"))
            if cur.get("type") == "FOLDER":
                return cur.get("container_id")
            pid = cur.get("parent_container_id")
            if not pid:
                break
            cur = by_id.get(pid)
        return None

    # cursor: base64url(JSON {"offset": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("VALIDATION_ERROR", workspace_id=workspaceId)
            return _err("VALIDATION_ERROR", "cursor must be a string when provided")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
            offset = int(obj.get("offset", 0))
            if offset < 0:
                offset = 0
        except Exception:
            _log("VALIDATION_ERROR", workspace_id=workspaceId)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # filtering
    out = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("workspace_id") != workspaceId:
            continue
        if t.get("status") == "deleted":
            continue

        # list/folder/space
        lid = t.get("list_container_id")
        if listIds is not None and lid not in listIds:
            continue
        if folderIds is not None:
            fid = _folder_for_list(lid)
            if fid not in folderIds:
                continue
        if spaceIds is not None:
            sid = _space_for_list(lid)
            if sid not in spaceIds:
                continue

        # tags: any match
        if tags is not None:
            ttags = t.get("tags") or []
            if not isinstance(ttags, list):
                ttags = []
            if not any(isinstance(x, str) and x in tags for x in ttags):
                continue

        # statuses by status_name
        if statuses is not None:
            if t.get("status_name") not in statuses:
                continue

        # assignees: any overlap
        if assignees is not None:
            aids = t.get("assignee_user_ids") or []
            if not isinstance(aids, list):
                aids = []
            if not any(isinstance(x, str) and x in assignees for x in aids):
                continue

        # date filters
        def _dt_from_field(val):
            if val is None:
                return None
            if isinstance(val, str):
                try:
                    return datetime.datetime.fromisoformat(val.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    return None
            return None

        dd = _dt_from_field(t.get("due_date"))
        sd = _dt_from_field(t.get("start_date"))
        ud = _dt_from_field(t.get("updated_at"))

        if due_from is not None and (dd is None or dd < due_from):
            continue
        if due_to is not None and (dd is None or dd > due_to):
            continue
        if start_from is not None and (sd is None or sd < start_from):
            continue
        if start_to is not None and (sd is None or sd > start_to):
            continue
        if upd_from is not None and (ud is None or ud < upd_from):
            continue
        if upd_to is not None and (ud is None or ud > upd_to):
            continue

        out.append(t)

    total = len(out)

    # sorting
    def _key(t):
        if sortBy is None:
            # default updated_at desc then created_at desc
            def _dt(v):
                if not isinstance(v, str):
                    return datetime.datetime.min
                try:
                    return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    return datetime.datetime.min
            return (_dt(t.get("updated_at")), _dt(t.get("created_at")), t.get("task_id") or "")
        if sortBy in ["created_at", "updated_at", "due_date", "start_date"]:
            v = t.get(sortBy)
            if not isinstance(v, str):
                return datetime.datetime.min
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return datetime.datetime.min
        if sortBy == "priority":
            v = t.get("priority")
            return v if isinstance(v, int) else -1
        if sortBy == "name":
            v = t.get("name")
            return v if isinstance(v, str) else ""
        return ""

    reverse = (sortOrder == "desc")
    if sortBy is None:
        out.sort(key=_key, reverse=True)
    else:
        out.sort(key=_key, reverse=reverse)

    lim = limit if isinstance(limit, int) else 50
    page = out[offset: offset + lim]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    _log("OK", workspace_id=workspaceId, detail={"returned": len(page), "total": total})
    return {
        "workspace_id": workspaceId,
        "tasks": page,
        "total": total,
        "limit": lim,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def get_task_time_entries(taskId=None, taskName=None, listName=None, userId=None, startFrom=None, startTo=None, billable=None, tags=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_task_time_entries"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, workspace_id=None, detail=None):
        latency_ms = int((time.time() - t0) * 1000)
        rec = {
            "request_id": f"req_{base64.urlsafe_b64encode(os.urandom(9)).decode('ascii').rstrip('=')}",
            "endpoint": endpoint,
            "status": status,
            "workspace_id": workspace_id,
            "latency_ms": latency_ms,
            "ts": _now_iso()
        }
        if detail is not None:
            rec["detail"] = detail
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(rec)
        _save("request_log.json", logs)

    def _rate_limit_check():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return True, None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-5000:]):
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt < window:
                break
            cnt += 1
        if cnt >= 1200:
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    ok_rl, rl_err = _rate_limit_check()
    if not ok_rl:
        _log("RATE_LIMIT")
        return rl_err

    # validation
    if taskId is None and taskName is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either taskId or taskName must be provided")
    if taskId is not None:
        if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[0-9A-Z]{18}$", taskId):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "taskId must match ^cu_tsk_[0-9A-Z]{18}$")
    if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "taskName must be a non-empty string when provided")
    if listName is not None and (not isinstance(listName, str) or not listName.strip()):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")

    sf, e = _parse_dt(startFrom, "startFrom")
    if e: _log(e["error"]["code"]); return e
    st, e = _parse_dt(startTo, "startTo")
    if e: _log(e["error"]["code"]); return e
    if sf is not None and st is not None and sf > st:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid date range: startFrom must be <= startTo")

    if billable is not None and not isinstance(billable, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "billable must be a boolean when provided")

    if tags is not None:
        if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of strings when provided")

    if limit is not None and (not isinstance(limit, int) or limit < 1):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1 when provided")

    # cursor: base64url(JSON {"offset": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string when provided")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
            offset = int(obj.get("offset", 0))
            if offset < 0:
                offset = 0
        except Exception:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    tasks = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    time_docs = _load("time_and_docs.json")

    if not isinstance(tasks, list) or not isinstance(containers, list) or not isinstance(workspaces, list) or not isinstance(time_docs, list):
        _log("CONFLICT")
        return _err("CONFLICT", "Datastore is not in expected format")

    # resolve task
    task = None
    if taskId is not None:
        task = next((t for t in tasks if t.get("task_id") == taskId and t.get("status") != "deleted"), None)
        if task is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Task not found", taskId=taskId)
    else:
        # if listName is not provided, require uniqueness within workspace not possible => fail on multiple matches
        # infer workspace only if taskName unique across single active workspace; otherwise require listName
        if listName is None:
            # try match across all active workspaces
            active_wids = {w.get("workspace_id") for w in workspaces if w.get("status") == "active"}
            ms = [t for t in tasks if t.get("status") != "deleted" and t.get("workspace_id") in active_wids and t.get("name") == taskName]
            if len(ms) == 0:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Task not found", taskName=taskName)
            if len(ms) > 1:
                _log("CONFLICT")
                return _err("CONFLICT", "Multiple tasks match taskName; provide listName or taskId", taskName=taskName, matches=[m.get("task_id") for m in ms[:50]])
            task = ms[0]
        else:
            # listName scope requires uniqueness of listName within task's workspace; infer workspace from listName uniqueness across active workspaces
            list_matches = [c for c in containers if c.get("status") != "deleted" and c.get("type") == "LIST" and c.get("name") == listName]
            list_matches = [c for c in list_matches if any(w.get("workspace_id") == c.get("workspace_id") and w.get("status") == "active" for w in workspaces)]
            if len(list_matches) == 0:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "List not found", listName=listName)
            wids = list({c.get("workspace_id") for c in list_matches})
            if len(wids) > 1:
                _log("CONFLICT")
                return _err("CONFLICT", "listName exists in multiple workspaces; provide taskId", listName=listName, workspaceIds=wids[:50])
            wid = wids[0]
            list_ms = [c for c in list_matches if c.get("workspace_id") == wid]
            if len(list_ms) > 1:
                _log("CONFLICT")
                return _err("CONFLICT", "Multiple lists match listName within workspace; disambiguate", listName=listName, matches=[m.get("container_id") for m in list_ms[:50]])
            lst = list_ms[0]
            ms = [t for t in tasks if t.get("workspace_id") == wid and t.get("status") != "deleted" and t.get("list_container_id") == lst.get("container_id") and t.get("name") == taskName]
            if len(ms) == 0:
                _log("NOT_FOUND", workspace_id=wid)
                return _err("NOT_FOUND", "Task not found in list", taskName=taskName, listName=listName)
            if len(ms) > 1:
                _log("CONFLICT", workspace_id=wid)
                return _err("CONFLICT", "Multiple tasks match taskName within list; use taskId", taskName=taskName, listName=listName, matches=[m.get("task_id") for m in ms[:50]])
            task = ms[0]

    workspace_id = task.get("workspace_id")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id and w.get("status") == "active"), None)
    if wsp is None:
        _log("UNAUTHORIZED", workspace_id=workspace_id)
        return _err("UNAUTHORIZED", "No active workspace context available for this operation")

    # filter time entries for task
    def _dt(val):
        if not isinstance(val, str):
            return None
        try:
            return datetime.datetime.fromisoformat(val.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    entries = []
    for e in time_docs:
        if not isinstance(e, dict):
            continue
        if e.get("workspace_id") != workspace_id:
            continue
        if e.get("type") != "TIME_ENTRY":
            continue
        if e.get("status") == "deleted":
            continue
        if e.get("task_id") != task.get("task_id"):
            continue

        if userId is not None:
            if not isinstance(userId, str):
                _log("VALIDATION_ERROR", workspace_id=workspace_id)
                return _err("VALIDATION_ERROR", "userId must be a string when provided")
            if e.get("clickup_user_id") != userId:
                continue

        if billable is not None:
            if e.get("billable") is None:
                continue
            if e.get("billable") != billable:
                continue

        stt = _dt(e.get("start_time"))
        if sf is not None and (stt is None or stt < sf):
            continue
        if st is not None and (stt is None or stt > st):
            continue

        if tags is not None:
            etags = e.get("tags") or []
            # ClickUp tags can be strings or objects; match by string equality or object.name
            found = False
            if isinstance(etags, list):
                for tg in etags:
                    if isinstance(tg, str) and tg in tags:
                        found = True
                        break
                    if isinstance(tg, dict):
                        nm = tg.get("name")
                        if isinstance(nm, str) and nm in tags:
                            found = True
                            break
            if not found:
                continue

        entries.append(e)

    # order by start_time desc, include running if present (it will naturally sort by start_time)
    def _sort_key(e):
        dtv = _dt(e.get("start_time"))
        if dtv is None:
            dtv = datetime.datetime.min
        return (dtv, e.get("entity_id") or "")

    entries.sort(key=_sort_key, reverse=True)

    total = len(entries)
    lim = limit if isinstance(limit, int) else 50
    page = entries[offset: offset + lim]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    _log("OK", workspace_id=workspace_id, detail={"task_id": task.get("task_id"), "returned": len(page), "total": total})
    return {
        "workspace_id": workspace_id,
        "task": {"task_id": task.get("task_id"), "clickup_task_id": task.get("clickup_task_id"), "name": task.get("name")},
        "time_entries": page,
        "total": total,
        "limit": lim,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def stop_time_tracking(description=None, tags=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "stop_time_tracking"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, rows, key):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        def _rand(n):
            seed = int(time.time() * 1000000)
            out = []
            for i in range(n):
                seed = (1103515245 * seed + 12345) & 0x7fffffff
                out.append(alphabet[seed % len(alphabet)])
            return "".join(out)
        while True:
            cand = f"{prefix}{_rand(20)}"
            if all(r.get(key) != cand for r in rows):
                return cand

    def _rate_limit_check():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=120, window_seconds=60)
        return None

    def _log(status, workspace_id=None, entity_id=None, extra=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "request_id": _gen_id("req_", logs, "request_id"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id,
            "entity_id": entity_id
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    rl = _rate_limit_check()
    if rl:
        _log("error", extra={"error_code": rl["error"]["code"]})
        return rl

    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string when provided.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(x, str) or not x.strip()) for x in tags):
            e = _err("VALIDATION_ERROR", "tags must be an array of non-empty strings when provided.")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e

    workspaces = _load("workspaces.json")
    entities = _load("time_and_docs.json")
    if not isinstance(workspaces, list) or not isinstance(entities, list):
        e = _err("CONFLICT", "Datastore is not initialized correctly.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    active_ws_ids = [w.get("workspace_id") for w in workspaces if w.get("status") == "active" and w.get("workspace_id")]
    if not active_ws_ids:
        e = _err("UNAUTHORIZED", "No active workspace is available to serve this request.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    # Determine user via pointer if present; else server
    # If multiple workspaces exist, stop in the one that has a running timer for the current user.
    clickup_user_id = None
    for e in entities:
        if e.get("type") == "RUNNING_TIMER_POINTER" and e.get("status") != "deleted" and e.get("workspace_id") in active_ws_ids and e.get("clickup_user_id"):
            clickup_user_id = e.get("clickup_user_id")
            break
    if not clickup_user_id:
        clickup_user_id = "server"

    running = None
    for e in entities:
        if e.get("type") == "TIME_ENTRY" and e.get("status") == "running" and e.get("workspace_id") in active_ws_ids and e.get("clickup_user_id") == clickup_user_id:
            running = e
            break

    if not running:
        e = _err("NOT_FOUND", "No running time entry found to stop.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    wsid = running.get("workspace_id")
    start = _parse_dt(running.get("start_time"))
    if not start:
        e = _err("CONFLICT", "Running time entry has invalid start_time.")
        _log("error", workspace_id=wsid, entity_id=running.get("entity_id"), extra={"error_code": e["error"]["code"]})
        return e

    now = datetime.datetime.now(datetime.timezone.utc)
    duration = int(max(0, (now - start).total_seconds()))

    # Lifecycle transition running -> stopped
    if running.get("status") != "running":
        e = _err("INVALID_TRANSITION", "Time entry is not in a running state.", current_status=running.get("status"))
        _log("error", workspace_id=wsid, entity_id=running.get("entity_id"), extra={"error_code": e["error"]["code"]})
        return e

    running["end_time"] = now.isoformat()
    running["duration_seconds"] = duration
    running["status"] = "stopped"
    if description is not None:
        running["description"] = description
    if tags is not None:
        running["tags"] = list(tags)
    running["updated_at"] = _now_iso()

    _save("time_and_docs.json", entities)
    _log("ok", workspace_id=wsid, entity_id=running.get("entity_id"))

    return {"time_entry": running, "meta": {"workspace_id": wsid}}

def add_time_entry(task_id=None, task_name=None, list_name=None, start_time=None, duration_seconds=None, description=None, billable=None, tags=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
