            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_time_entry"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, rows, key):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        def _rand(n):
            seed = int(time.time() * 1000000)
            out = []
            for i in range(n):
                seed = (1103515245 * seed + 12345) & 0x7fffffff
                out.append(alphabet[seed % len(alphabet)])
            return "".join(out)
        while True:
            cand = f"{prefix}{_rand(20)}"
            if all(r.get(key) != cand for r in rows):
                return cand

    def _rate_limit_check():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=120, window_seconds=60)
        return None

    def _log(status, workspace_id=None, entity_id=None, extra=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "request_id": _gen_id("req_", logs, "request_id"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id,
            "entity_id": entity_id
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    rl = _rate_limit_check()
    if rl:
        _log("error", extra={"error_code": rl["error"]["code"]})
        return rl

    # Validate inputs
    if start_time is None or not isinstance(start_time, str) or not _parse_dt(start_time):
        e = _err("VALIDATION_ERROR", "start_time is required and must be a valid ISO 8601 date-time string.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if duration_seconds is None or not isinstance(duration_seconds, int) or duration_seconds < 1:
        e = _err("VALIDATION_ERROR", "duration_seconds is required and must be an integer >= 1.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if task_id is None and (task_name is None or not isinstance(task_name, str) or not task_name.strip()):
        e = _err("VALIDATION_ERROR", "Either task_id or a resolvable task_name must be provided.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if task_id is not None:
        if not isinstance(task_id, str) or not re.match(r"^cu_tsk_[0-9A-Z]{18,}$", task_id):
            e = _err("VALIDATION_ERROR", "task_id must match pattern ^cu_tsk_[0-9A-Z]{18,}$.")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
    if task_name is not None and (not isinstance(task_name, str) or not task_name.strip()):
        e = _err("VALIDATION_ERROR", "task_name must be a non-empty string when provided.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if list_name is not None and (not isinstance(list_name, str) or not list_name.strip()):
        e = _err("VALIDATION_ERROR", "list_name must be a non-empty string when provided.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string when provided.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if billable is not None and not isinstance(billable, bool):
        e = _err("VALIDATION_ERROR", "billable must be a boolean when provided.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e
    if tags is not None:
        if not isinstance(tags, list) or any((not isinstance(x, str) or not x.strip()) for x in tags):
            e = _err("VALIDATION_ERROR", "tags must be an array of non-empty strings when provided.")
            _log("error", extra={"error_code": e["error"]["code"]})
            return e

    workspaces = _load("workspaces.json")
    tasks = _load("tasks.json")
    containers = _load("containers.json")
    entities = _load("time_and_docs.json")
    if not isinstance(workspaces, list) or not isinstance(tasks, list) or not isinstance(containers, list) or not isinstance(entities, list):
        e = _err("CONFLICT", "Datastore is not initialized correctly.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    active_ws_ids = {w.get("workspace_id") for w in workspaces if w.get("status") == "active" and w.get("workspace_id")}
    if not active_ws_ids:
        e = _err("UNAUTHORIZED", "No active workspace is available to serve this request.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    # Resolve task
    resolved_task = None
    if task_id is not None:
        for t in tasks:
            if t.get("task_id") == task_id and t.get("status") != "deleted" and t.get("workspace_id") in active_ws_ids:
                resolved_task = t
                break
        if not resolved_task:
            e = _err("NOT_FOUND", "Task not found.", task_id=task_id)
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
    else:
        name = task_name.strip()
        candidates = [t for t in tasks if t.get("status") != "deleted" and t.get("workspace_id") in active_ws_ids and t.get("name") == name]
        if list_name is not None:
            ln = list_name.strip()
            list_ids_by_ws = {}
            for c in containers:
                if c.get("status") != "deleted" and c.get("type") == "LIST" and c.get("name") == ln and c.get("workspace_id") in active_ws_ids:
                    list_ids_by_ws.setdefault(c.get("workspace_id"), set()).add(c.get("container_id"))
            scoped = []
            for t in candidates:
                wsid = t.get("workspace_id")
                if wsid in list_ids_by_ws and t.get("list_container_id") in list_ids_by_ws[wsid]:
                    scoped.append(t)
            candidates = scoped
        else:
            if len(candidates) > 1:
                e = _err("CONFLICT", "Multiple tasks match task_name. Provide list_name to disambiguate.", matches=len(candidates))
                _log("error", extra={"error_code": e["error"]["code"]})
                return e

        if not candidates:
            e = _err("NOT_FOUND", "Task not found for given name/scope.", task_name=task_name, list_name=list_name)
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        if len(candidates) > 1:
            e = _err("CONFLICT", "Multiple tasks match task_name within the provided scope.", matches=len(candidates))
            _log("error", extra={"error_code": e["error"]["code"]})
            return e
        resolved_task = candidates[0]

    workspace_id = resolved_task.get("workspace_id")

    # Use pointer user if present; else server
    clickup_user_id = None
    for e in entities:
        if e.get("type") == "RUNNING_TIMER_POINTER" and e.get("status") != "deleted" and e.get("workspace_id") == workspace_id and e.get("clickup_user_id"):
            clickup_user_id = e.get("clickup_user_id")
            break
    if not clickup_user_id:
        clickup_user_id = "server"

    # Create stopped time entry
    st = _parse_dt(start_time)
    if st.tzinfo is None:
        st = st.replace(tzinfo=datetime.timezone.utc)
    st = st.astimezone(datetime.timezone.utc)
    end = st + datetime.timedelta(seconds=int(duration_seconds))

    entity_id = _gen_id("cu_ent_", entities, "entity_id")
    new_row = {
        "entity_id": entity_id,
        "workspace_id": workspace_id,
        "type": "TIME_ENTRY",
        "task_id": resolved_task.get("task_id"),
        "clickup_task_id": resolved_task.get("clickup_task_id"),
        "clickup_time_entry_id": None,
        "start_time": st.isoformat(),
        "end_time": end.isoformat(),
        "duration_seconds": int(duration_seconds),
        "billable": billable if billable is not None else None,
        "description": description if description is not None else None,
        "tags": list(tags) if isinstance(tags, list) else None,
        "clickup_user_id": clickup_user_id,
        "document_id": None,
        "clickup_document_id": None,
        "clickup_page_id": None,
        "title": None,
        "content": None,
        "content_format": None,
        "parent_container_id": None,
        "parent_type_code": None,
        "visibility": None,
        "create_page": None,
        "depth": None,
        "status": "stopped",
        "created_at": _now_iso(),
        "updated_at": _now_iso()
    }

    # Constraint: duration_seconds >=0 already, and stopped is ok with end_time present
    entities.append(new_row)
    _save("time_and_docs.json", entities)
    _log("ok", workspace_id=workspace_id, entity_id=entity_id)

    return {
        "time_entry": new_row,
        "task": {"task_id": resolved_task.get("task_id"), "clickup_task_id": resolved_task.get("clickup_task_id"), "name": resolved_task.get("name")},
        "meta": {"workspace_id": workspace_id}
    }

def delete_time_entry(time_entry_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_time_entry"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, rows, key):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        def _rand(n):
            seed = int(time.time() * 1000000)
            out = []
            for i in range(n):
                seed = (1103515245 * seed + 12345) & 0x7fffffff
                out.append(alphabet[seed % len(alphabet)])
            return "".join(out)
        while True:
            cand = f"{prefix}{_rand(20)}"
            if all(r.get(key) != cand for r in rows):
                return cand

    def _rate_limit_check():
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=120, window_seconds=60)
        return None

    def _log(status, workspace_id=None, entity_id=None, extra=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "request_id": _gen_id("req_", logs, "request_id"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "workspace_id": workspace_id,
            "entity_id": entity_id
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_log.json", logs)

    rl = _rate_limit_check()
    if rl:
        _log("error", extra={"error_code": rl["error"]["code"]})
        return rl

    if not isinstance(time_entry_id, str) or not re.match(r"^cu_ent_[0-9A-Z]{18,}$", time_entry_id):
        e = _err("VALIDATION_ERROR", "time_entry_id must match pattern ^cu_ent_[0-9A-Z]{18,}$.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    workspaces = _load("workspaces.json")
    entities = _load("time_and_docs.json")
    if not isinstance(workspaces, list) or not isinstance(entities, list):
        e = _err("CONFLICT", "Datastore is not initialized correctly.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    active_ws_ids = {w.get("workspace_id") for w in workspaces if w.get("status") == "active" and w.get("workspace_id")}
    if not active_ws_ids:
        e = _err("UNAUTHORIZED", "No active workspace is available to serve this request.")
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    target = None
    for e in entities:
        if e.get("entity_id") == time_entry_id and e.get("type") == "TIME_ENTRY" and e.get("workspace_id") in active_ws_ids:
            target = e
            break

    if not target or target.get("status") == "deleted":
        e = _err("NOT_FOUND", "Time entry not found.", time_entry_id=time_entry_id)
        _log("error", extra={"error_code": e["error"]["code"]})
        return e

    # Lifecycle transitions for time_and_docs: active/running/stopped -> deleted
    if target.get("status") not in ("active", "running", "stopped"):
        e = _err("INVALID_TRANSITION", "Time entry cannot be deleted from its current status.", current_status=target.get("status"))
        _log("error", workspace_id=target.get("workspace_id"), entity_id=time_entry_id, extra={"error_code": e["error"]["code"]})
        return e

    target["status"] = "deleted"
    target["updated_at"] = _now_iso()

    _save("time_and_docs.json", entities)
    _log("ok", workspace_id=target.get("workspace_id"), entity_id=time_entry_id)

    return {"time_entry": target, "meta": {"workspace_id": target.get("workspace_id")}}

def get_current_time_entry(**_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(20))}"

    def _log(endpoint, status, workspace_id=None, credential_id=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "request_id": _gen_id("req"),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_log.json", logs)

    def _enforce_limits(endpoint, workspace_id=None, credential_id=None):
        # If the service has a limits.json config, enforce it; otherwise no limits.
        cfg = _load("limits.json")
        if not isinstance(cfg, dict):
            return None
        now = datetime.datetime.utcnow()
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []

        # window rate limit
        rl = cfg.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                try:
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    if dt < cutoff:
                        continue
                    if endpoint is not None and r.get("endpoint") != endpoint:
                        continue
                    if credential_id is not None and r.get("credential_id") != credential_id:
                        continue
                    if workspace_id is not None and r.get("workspace_id") != workspace_id:
                        continue
                    if r.get("status") == 200:
                        c += 1
                except Exception:
                    continue
            if c >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded")

        quota = cfg.get("quota_per_day")
        if isinstance(quota, int) and quota >= 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                try:
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    if dt < cutoff:
                        continue
                    if credential_id is not None and r.get("credential_id") != credential_id:
                        continue
                    if workspace_id is not None and r.get("workspace_id") != workspace_id:
                        continue
                    if r.get("status") == 200:
                        c += 1
                except Exception:
                    continue
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

        return None

    # Ambient auth: pick any workspace that can serve call; for this endpoint, any active workspace qualifies.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    active_ws = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
    if not active_ws:
        _log("get_current_time_entry", 401, None, None, {"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace available for this request")

    # Choose the workspace with a running entry if possible.
    entities = _load("time_and_docs.json")
    if not isinstance(entities, list):
        entities = []
    running = [e for e in entities if isinstance(e, dict) and e.get("type") == "TIME_ENTRY" and e.get("status") == "running"]
    ws_by_id = {w.get("workspace_id"): w for w in active_ws if isinstance(w, dict) and isinstance(w.get("workspace_id"), str)}

    chosen_ws_id = None
    chosen_entry = None
    for e in running:
        wsid = e.get("workspace_id")
        if isinstance(wsid, str) and wsid in ws_by_id:
            chosen_ws_id = wsid
            chosen_entry = e
            break
    if chosen_ws_id is None:
        # No running entry; return null with any active workspace context.
        chosen_ws_id = active_ws[0].get("workspace_id")

    lim = _enforce_limits("get_current_time_entry", workspace_id=chosen_ws_id, credential_id=None)
    if lim:
        _log("get_current_time_entry", 429 if lim["error"]["code"] == "RATE_LIMIT" else 403, chosen_ws_id, None, {})
        return lim

    # Return running entry or null.
    resp = {
        "workspace_id": chosen_ws_id,
        "time_entry": chosen_entry if chosen_entry is not None else None
    }
    _log("get_current_time_entry", 200, chosen_ws_id, None, {"has_running": chosen_entry is not None})
    return resp

def create_list(name, space_id=None, space_name=None, content=None, due_date=None, priority=None, assignee_user_id=None, status=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_list"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt.isoformat() + "Z", None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} is not a valid ISO-8601 date-time.", field=field, value=s)

    def _log(status_code, workspace_id=None, container_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "container_id": container_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", detail={"field": "name"})
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if space_id is None and (space_name is None or not isinstance(space_name, str) or not space_name.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["space_id", "space_name"]})
        return _err("VALIDATION_ERROR", "Either space_id or space_name must be provided.", fields=["space_id", "space_name"])
    if space_id is not None and not isinstance(space_id, str):
        _log("VALIDATION_ERROR", detail={"field": "space_id"})
        return _err("VALIDATION_ERROR", "space_id must be a string when provided.", field="space_id")
    if space_name is not None and not isinstance(space_name, str):
        _log("VALIDATION_ERROR", detail={"field": "space_name"})
        return _err("VALIDATION_ERROR", "space_name must be a string when provided.", field="space_name")
    if content is not None and not isinstance(content, str):
        _log("VALIDATION_ERROR", detail={"field": "content"})
        return _err("VALIDATION_ERROR", "content must be a string when provided.", field="content")
    if priority is not None and not isinstance(priority, int):
        _log("VALIDATION_ERROR", detail={"field": "priority"})
        return _err("VALIDATION_ERROR", "priority must be an integer when provided.", field="priority")
    if assignee_user_id is not None and (not isinstance(assignee_user_id, str) or not assignee_user_id.strip()):
        _log("VALIDATION_ERROR", detail={"field": "assignee_user_id"})
        return _err("VALIDATION_ERROR", "assignee_user_id must be a non-empty string when provided.", field="assignee_user_id")
    if status is not None and (not isinstance(status, str) or not status.strip()):
        _log("VALIDATION_ERROR", detail={"field": "status"})
        return _err("VALIDATION_ERROR", "status must be a non-empty string when provided.", field="status")
    due_iso, e = _parse_dt(due_date, "due_date")
    if e:
        _log("VALIDATION_ERROR", detail=e.get("error"))
        return e

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(containers, list): containers = []

    # resolve SPACE
    space_ctr = None
    if space_id is not None:
        m = [c for c in containers if isinstance(c, dict) and c.get("status") != "deleted" and c.get("type") == "SPACE" and (c.get("container_id") == space_id or c.get("clickup_container_id") == space_id)]
        if len(m) == 1:
            space_ctr = m[0]
        elif len(m) == 0 and space_name is None:
            _log("NOT_FOUND", detail={"field": "space_id"})
            return _err("NOT_FOUND", "Space not found.", field="space_id")
        elif len(m) > 1:
            _log("CONFLICT", detail={"field": "space_id"})
            return _err("CONFLICT", "space_id matched multiple spaces.", field="space_id")
    if space_ctr is None:
        sn = space_name.strip()
        m = [c for c in containers if isinstance(c, dict) and c.get("status") != "deleted" and c.get("type") == "SPACE" and c.get("name") == sn]
        if len(m) == 1:
            space_ctr = m[0]
        elif len(m) == 0:
            _log("NOT_FOUND", detail={"field": "space_name"})
            return _err("NOT_FOUND", "Space not found.", field="space_name")
        else:
            _log("CONFLICT", detail={"field": "space_name"})
            return _err("CONFLICT", "space_name matched multiple spaces; provide space_id.", field="space_name")

    wsid = space_ctr.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("workspace_id") == wsid), None)
    if not ws or ws.get("status") != "active":
        _log("UNAUTHORIZED", workspace_id=wsid, detail={"rule": "workspace must be active"})
        return _err("UNAUTHORIZED", "Workspace is not active or not accessible.", workspaceId=wsid)

    # unique(workspace_id, type, clickup_container_id) where clickup_container_id not null
    # We'll create synthetic clickup_container_id for list.
    clickup_container_id = _gen_id("clk_lst")
    existing_vendor = {(c.get("workspace_id"), c.get("type"), c.get("clickup_container_id")) for c in containers if isinstance(c, dict) and c.get("clickup_container_id") is not None}
    if (wsid, "LIST", clickup_container_id) in existing_vendor:
        _log("CONFLICT", workspace_id=wsid, detail={"field": "clickup_container_id"})
        return _err("CONFLICT", "Generated clickup_container_id conflicted; retry.", field="clickup_container_id")

    now = _utcnow_z()
    row = {
        "container_id": _gen_id("cu_ctr"),
        "workspace_id": wsid,
        "clickup_container_id": clickup_container_id,
        "type": "LIST",
        "parent_container_id": space_ctr.get("container_id"),
        "name": name.strip(),
        "content": content if content is not None else None,
        "override_statuses": None,
        "archived": False,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    containers.append(row)
    _save("containers.json", containers)
    _log("OK", workspace_id=wsid, container_id=row["container_id"])
    return {"list": row, "space": {"container_id": space_ctr.get("container_id"), "name": space_ctr.get("name")}}

def create_list_in_folder(name, folder_id=None, folder_name=None, space_id=None, space_name=None, content=None, status=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_list_in_folder"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, container_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "container_id": container_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", detail={"field": "name"})
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if content is not None and not isinstance(content, str):
        _log("VALIDATION_ERROR", detail={"field": "content"})
        return _err("VALIDATION_ERROR", "content must be a string when provided.", field="content")
    if status is not None and not isinstance(status, str):
        _log("VALIDATION_ERROR", detail={"field": "status"})
        return _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")

    if folder_id is None and (folder_name is None or not isinstance(folder_name, str) or not folder_name.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["folder_id", "folder_name"]})
        return _err("VALIDATION_ERROR", "You must provide folder_id or folder_name.", fields=["folder_id", "folder_name"])
    if folder_id is not None and not isinstance(folder_id, str):
        _log("VALIDATION_ERROR", detail={"field": "folder_id"})
        return _err("VALIDATION_ERROR", "folder_id must be a string when provided.", field="folder_id")
    if folder_name is not None and not isinstance(folder_name, str):
        _log("VALIDATION_ERROR", detail={"field": "folder_name"})
        return _err("VALIDATION_ERROR", "folder_name must be a string when provided.", field="folder_name")

    # if resolving by name, require space scope
    if folder_id is None:
        if (space_id is None or not isinstance(space_id, str) or not space_id.strip()) and (space_name is None or not isinstance(space_name, str) or not space_name.strip()):
            _log("VALIDATION_ERROR", detail={"fields": ["space_id", "space_name"]})
            return _err("VALIDATION_ERROR", "When using folder_name, you must also provide space_id or space_name to disambiguate.", fields=["space_id", "space_name"])
        if space_id is not None and not isinstance(space_id, str):
            _log("VALIDATION_ERROR", detail={"field": "space_id"})
            return _err("VALIDATION_ERROR", "space_id must be a string when provided.", field="space_id")
        if space_name is not None and not isinstance(space_name, str):
            _log("VALIDATION_ERROR", detail={"field": "space_name"})
            return _err("VALIDATION_ERROR", "space_name must be a string when provided.", field="space_name")

    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    if not isinstance(containers, list): containers = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # resolve target folder
    folder = None
    space = None

    if folder_id is not None:
        candidates = [c for c in containers if isinstance(c, dict) and c.get("container_id") == folder_id and c.get("type") == "FOLDER" and c.get("status") != "deleted" and c.get("workspace_id") in active_ws]
        if len(candidates) != 1:
            _log("NOT_FOUND", detail={"field": "folder_id"})
            return _err("NOT_FOUND", "Folder not found.", field="folder_id")
        folder = candidates[0]
        # resolve its space parent
        pid = folder.get("parent_container_id")
        space = next((c for c in containers if isinstance(c, dict) and c.get("container_id") == pid and c.get("type") == "SPACE" and c.get("status") != "deleted"), None)
    else:
        fn = folder_name.strip()
        # resolve space scope by id or name
        if space_id is not None:
            space_candidates = [c for c in containers if isinstance(c, dict) and c.get("container_id") == space_id and c.get("type") == "SPACE" and c.get("status") != "deleted" and c.get("workspace_id") in active_ws]
            if len(space_candidates) != 1:
                _log("NOT_FOUND", detail={"field": "space_id"})
                return _err("NOT_FOUND", "Space not found.", field="space_id")
            space = space_candidates[0]
        else:
            sn = space_name.strip()
            space_candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "SPACE" and c.get("status") != "deleted" and (c.get("name") or "") == sn and c.get("workspace_id") in active_ws]
            if len(space_candidates) == 0:
                _log("NOT_FOUND", detail={"field": "space_name"})
                return _err("NOT_FOUND", "Space not found.", field="space_name")
            if len(space_candidates) > 1:
                _log("CONFLICT", detail={"field": "space_name", "matches": len(space_candidates)})
                return _err("CONFLICT", "space_name is ambiguous; provide space_id.", field="space_name", matches=len(space_candidates))
            space = space_candidates[0]

        folder_candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "FOLDER" and c.get("status") != "deleted" and c.get("parent_container_id") == space.get("container_id") and (c.get("name") or "") == fn and c.get("workspace_id") == space.get("workspace_id")]
        if len(folder_candidates) == 0:
            _log("NOT_FOUND", detail={"field": "folder_name"})
            return _err("NOT_FOUND", "Folder not found in the provided space scope.", field="folder_name")
        if len(folder_candidates) > 1:
            _log("CONFLICT", detail={"field": "folder_name", "matches": len(folder_candidates)})
            return _err("CONFLICT", "folder_name is ambiguous within the provided space scope; provide folder_id.", field="folder_name", matches=len(folder_candidates))
        folder = folder_candidates[0]

    workspace_id = folder.get("workspace_id")
    nowz = _utcnow_z()

    # enforce unique(workspace_id, type, clickup_container_id) where clickup_container_id not null
    # for created list, we will generate a vendor id to satisfy uniqueness
    existing_vendor_ids = {c.get("clickup_container_id") for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspace_id and c.get("type") == "LIST" and c.get("clickup_container_id") is not None}
    clickup_container_id = None
    for _ in range(100):
        candidate = "lst_" + uuid.uuid4().hex[:12]
        if candidate not in existing_vendor_ids:
            clickup_container_id = candidate
            break
    if clickup_container_id is None:
        clickup_container_id = "lst_" + uuid.uuid4().hex

    new_container_id = _gen_id("cu_ctr")
    row = {
        "container_id": new_container_id,
        "workspace_id": workspace_id,
        "clickup_container_id": clickup_container_id,
        "type": "LIST",
        "parent_container_id": folder.get("container_id"),
        "name": name.strip(),
        "content": content,
        "override_statuses": None,
        "archived": False,
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }

    containers.append(row)
    _save("containers.json", containers)
    _log("OK", workspace_id=workspace_id, container_id=new_container_id)
    return {"list": row, "folder": {"container_id": folder.get("container_id"), "name": folder.get("name")}, "space": {"container_id": space.get("container_id") if isinstance(space, dict) else None, "name": space.get("name") if isinstance(space, dict) else None}}

def get_list(list_id=None, list_name=None, **_extra):
    import json, os, datetime, time, random, string, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = string.ascii_uppercase + string.digits
        return f"{prefix}_{''.join(random.choice(alphabet) for _ in range(20))}"

    def _log(endpoint, status_code, workspace_id=None, meta=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "timestamp": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_id": None,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_log.json", logs)

    def _enforce_limits(endpoint, workspace_id=None):
        cfg = _load("limits.json")
        if not isinstance(cfg, dict):
            return None
        now = datetime.datetime.utcnow()
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        rl = cfg.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl >= 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                try:
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    if dt < cutoff:
                        continue
                    if r.get("endpoint") != endpoint:
                        continue
                    if workspace_id is not None and r.get("workspace_id") != workspace_id:
                        continue
                    if r.get("status") == 200:
                        c += 1
                except Exception:
                    continue
            if c >= rl:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        quota = cfg.get("quota_per_day")
        if isinstance(quota, int) and quota >= 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                try:
                    ts = r.get("timestamp")
                    if not isinstance(ts, str):
                        continue
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    if dt < cutoff:
                        continue
                    if workspace_id is not None and r.get("workspace_id") != workspace_id:
                        continue
                    if r.get("status") == 200:
                        c += 1
                except Exception:
                    continue
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    if list_id is None and list_name is None:
        _log("get_list", 400, None, {"field": "list_id/list_name"})
        return _err("VALIDATION_ERROR", "Either list_id or list_name must be provided", field="list_id")

    if list_id is not None:
        if not isinstance(list_id, str) or re.match(r"^cu_ctr_[0-9A-Z]{18,}$", list_id) is None:
            _log("get_list", 400, None, {"field": "list_id"})
            return _err("VALIDATION_ERROR", "list_id must match pattern ^cu_ctr_[0-9A-Z]{18,}$", field="list_id")
    if list_name is not None and (not isinstance(list_name, str) or not list_name.strip()):
        _log("get_list", 400, None, {"field": "list_name"})
        return _err("VALIDATION_ERROR", "list_name must be a non-empty string when provided", field="list_name")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    containers = _load("containers.json")
    if not isinstance(containers, list):
        containers = []

    active_ws_ids = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("workspace_id"), str)}
    if not active_ws_ids:
        _log("get_list", 401, None, {"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace available for this request")

    target = None
    if list_id is not None:
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == list_id and c.get("type") == "LIST" and c.get("status") != "deleted":
                if c.get("workspace_id") in active_ws_ids:
                    target = c
                    break
        if target is None:
            _log("get_list", 404, None, {"field": "list_id"})
            return _err("NOT_FOUND", "List not found", field="list_id")
    else:
        matches = []
        for c in containers:
            if not isinstance(c, dict):
                continue
            if c.get("type") != "LIST" or c.get("status") == "deleted":
                continue
            if c.get("workspace_id") not in active_ws_ids:
                continue
            if c.get("name") == list_name:
                matches.append(c)
        if len(matches) == 0:
            _log("get_list", 404, None, {"field": "list_name"})
            return _err("NOT_FOUND", "List not found", field="list_name")
        if len(matches) > 1:
            _log("get_list", 409, None, {"field": "list_name", "count": len(matches)})
            return _err("CONFLICT", "Multiple lists match list_name; please specify list_id (or narrow scope in the calling tool)", field="list_name", matches=len(matches))
        target = matches[0]

    workspace_id = target.get("workspace_id")
    lim = _enforce_limits("get_list", workspace_id=workspace_id)
    if lim:
        _log("get_list", 429 if lim["error"]["code"] == "RATE_LIMIT" else 403, workspace_id, {})
        return lim

    # Gather metadata: parent folder/space if possible
    by_id = {c.get("container_id"): c for c in containers if isinstance(c, dict) and isinstance(c.get("container_id"), str) and c.get("status") != "deleted"}

    parent = by_id.get(target.get("parent_container_id")) if isinstance(target.get("parent_container_id"), str) else None
    space = None
    folder = None
    if parent is not None and parent.get("type") == "SPACE":
        space = parent
    elif parent is not None and parent.get("type") == "FOLDER":
        folder = parent
        sp = by_id.get(parent.get("parent_container_id")) if isinstance(parent.get("parent_container_id"), str) else None
        if sp is not None and sp.get("type") == "SPACE":
            space = sp

    resp = {
        "list": target,
        "folder": {"container_id": folder.get("container_id"), "name": folder.get("name")} if folder else None,
        "space": {"container_id": space.get("container_id"), "name": space.get("name")} if space else None,
        "workspace_id": workspace_id
    }
    _log("get_list", 200, workspace_id, {"list_id": target.get("container_id")})
    return resp

def update_list(listId=None, listName=None, folderId=None, folderName=None, spaceId=None, spaceName=None, name=None, content=None, status=None, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_list"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, workspace_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "request_id": "req_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(24)),
            "ts": _now(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    # ---- validation helpers ----
    _id_re = re.compile(r"^cu_ctr_[0-9A-Z]{18,}$")
    def _is_str(x): return isinstance(x, str)
    def _validate_optional_id(val, field):
        if val is None: return None
        if not _is_str(val) or not _id_re.match(val):
            return _err("VALIDATION_ERROR", f"Invalid {field} format.", field=field)
        return None

    # validate ids
    for v, f in [(listId, "listId"), (folderId, "folderId"), (spaceId, "spaceId")]:
        e = _validate_optional_id(v, f)
        if e:
            _log("VALIDATION_ERROR", detail={"field": f})
            return e

    # validate strings
    for v, f in [(listName, "listName"), (folderName, "folderName"), (spaceName, "spaceName"), (name, "name"), (content, "content")]:
        if v is not None and not _is_str(v):
            _log("VALIDATION_ERROR", detail={"field": f})
            return _err("VALIDATION_ERROR", f"{f} must be a string.", field=f)

    if status is not None and status not in ("active", "deleted"):
        _log("VALIDATION_ERROR", detail={"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of ['active','deleted'].", field="status")

    # require at least one updatable field
    if name is None and content is None and status is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one updatable field must be provided: name, content, or status.")

    # resolve a working workspace context (ambient auth)
    workspaces = _load("workspaces.json")
    containers = _load("containers.json")

    active_ws = [w for w in workspaces if isinstance(w, dict) and w.get("status") == "active"]
    if not active_ws:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    def _find_container_by_id(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == cid:
                return c
        return None

    def _container_is_mutable(c):
        return isinstance(c, dict) and c.get("status") != "deleted"

    # resolve list container
    target = None
    workspace_id = None

    if listId:
        c = _find_container_by_id(listId)
        if not c or c.get("type") != "LIST" or c.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "List not found.", listId=listId)
        ws = next((w for w in active_ws if w.get("workspace_id") == c.get("workspace_id")), None)
        if not ws:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active workspace is available to serve this request for the specified list.")
        target = c
        workspace_id = c.get("workspace_id")
    else:
        if not listName:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Either listId or listName must be provided.")
        # when using listName, require disambiguating scope
        # Accept either folder scope (id/name) or space scope (id/name)
        if not (folderId or folderName or spaceId or spaceName):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "When using listName, you must provide folderId/folderName or spaceId/spaceName to resolve it unambiguously.")

        # resolve space/folder scope to ids (may be used to filter lists)
        scope_space_ids = set()
        scope_folder_ids = set()

        # resolve space
        if spaceId:
            sc = _find_container_by_id(spaceId)
            if not sc or sc.get("type") != "SPACE" or sc.get("status") == "deleted":
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)
            ws = next((w for w in active_ws if w.get("workspace_id") == sc.get("workspace_id")), None)
            if not ws:
                _log("UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No active workspace is available to serve this request for the specified space.")
            scope_space_ids.add(spaceId)
        elif spaceName:
            matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "SPACE" and c.get("status") != "deleted" and c.get("name") == spaceName and any(w.get("workspace_id") == c.get("workspace_id") for w in active_ws)]
            if not matches:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Space not found.", spaceName=spaceName)
            # if multiple spaces with same name across workspaces, ambiguous
            space_ids = {m.get("container_id") for m in matches}
            if len(space_ids) != 1:
                _log("CONFLICT")
                return _err("CONFLICT", "Multiple spaces match spaceName; provide spaceId.", spaceName=spaceName)
            scope_space_ids.add(matches[0].get("container_id"))

        # resolve folder
        if folderId:
            fc = _find_container_by_id(folderId)
            if not fc or fc.get("type") != "FOLDER" or fc.get("status") == "deleted":
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Folder not found.", folderId=folderId)
            ws = next((w for w in active_ws if w.get("workspace_id") == fc.get("workspace_id")), None)
            if not ws:
                _log("UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No active workspace is available to serve this request for the specified folder.")
            scope_folder_ids.add(folderId)
            # infer space from folder parent
            if fc.get("parent_container_id"):
                scope_space_ids.add(fc.get("parent_container_id"))
        elif folderName:
            # folderName requires space scope per business rules
            if not (scope_space_ids or spaceId or spaceName):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "folderName resolution requires a space scope (spaceId or spaceName).")
            # match folders under the scoped spaces
            candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "FOLDER" and c.get("status") != "deleted" and c.get("name") == folderName]
            if scope_space_ids:
                candidates = [c for c in candidates if c.get("parent_container_id") in scope_space_ids]
            # enforce active workspace availability
            candidates = [c for c in candidates if any(w.get("workspace_id") == c.get("workspace_id") for w in active_ws)]
            if not candidates:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Folder not found.", folderName=folderName)
            folder_ids = {c.get("container_id") for c in candidates}
            if len(folder_ids) != 1:
                _log("CONFLICT")
                return _err("CONFLICT", "Multiple folders match folderName in the provided scope; provide folderId.", folderName=folderName)
            scope_folder_ids.add(candidates[0].get("container_id"))
            if candidates[0].get("parent_container_id"):
                scope_space_ids.add(candidates[0].get("parent_container_id"))

        # now resolve listName within scope
        lists = [c for c in containers if isinstance(c, dict) and c.get("type") == "LIST" and c.get("status") != "deleted" and c.get("name") == listName]
        # restrict to active workspaces
        lists = [c for c in lists if any(w.get("workspace_id") == c.get("workspace_id") for w in active_ws)]

        if scope_folder_ids:
            lists = [c for c in lists if c.get("parent_container_id") in scope_folder_ids]
        elif scope_space_ids:
            # list parent can be SPACE or FOLDER; include those under space
            def _is_under_space(list_row):
                pid = list_row.get("parent_container_id")
                if pid in scope_space_ids:
                    return True
                p = _find_container_by_id(pid) if pid else None
                return bool(p and p.get("type") == "FOLDER" and p.get("parent_container_id") in scope_space_ids)
            lists = [c for c in lists if _is_under_space(c)]

        if not lists:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "List not found.", listName=listName)
        if len({c.get("container_id") for c in lists}) != 1:
            _log("CONFLICT")
            return _err("CONFLICT", "Multiple lists match listName in the provided scope; provide listId or add more scope.", listName=listName)
        target = lists[0]
        workspace_id = target.get("workspace_id")

    # enforce not mutating deleted entities (already ensured), and validate transition if status provided
    if not _container_is_mutable(target):
        _log("NOT_FOUND", workspace_id=workspace_id)
        return _err("NOT_FOUND", "List not found (deleted).")

    if status is not None:
        cur = target.get("status")
        if cur == "deleted":
            _log("NOT_FOUND", workspace_id=workspace_id)
            return _err("NOT_FOUND", "List not found (deleted).")
        if cur == "active" and status == "deleted":
            pass
        elif cur == status:
            # idempotent no-op allowed only if there are other field changes; otherwise would be no effect
            pass
        else:
            _log("INVALID_TRANSITION", workspace_id=workspace_id, detail={"from": cur, "to": status})
            return _err("INVALID_TRANSITION", f"Cannot transition list status from '{cur}' to '{status}'.", from_status=cur, to_status=status)

    # apply updates only for provided fields; ensure at least one results in change
    changed = False
    before = dict(target)

    if name is not None and name != target.get("name"):
        if not (1 <= len(name) <= 1024):
            _log("VALIDATION_ERROR", workspace_id=workspace_id, detail={"field": "name"})
            return _err("VALIDATION_ERROR", "name length must be between 1 and 1024.", field="name")
        target["name"] = name
        changed = True
    if content is not None and content != target.get("content"):
        target["content"] = content
        changed = True
    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True

    if not changed:
        _log("CONFLICT", workspace_id=workspace_id)
        return _err("CONFLICT", "No changes detected; update would have no effect.", current=before)

    target["updated_at"] = _now()

    # persist containers
    _save("containers.json", containers)

    _log("OK", workspace_id=workspace_id)
    return {
        "ok": True,
        "list": target
    }

def delete_list(listId=None, listName=None, folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_list"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, container_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "container_id": container_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    # validate presence
    if listId is None and (listName is None or not isinstance(listName, str) or not listName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["listId", "listName"]})
        return _err("VALIDATION_ERROR", "Either listId or listName must be provided.", fields=["listId", "listName"])
    for v, f in [(listId, "listId"), (folderId, "folderId"), (spaceId, "spaceId")]:
        if v is not None and not isinstance(v, str):
            _log("VALIDATION_ERROR", detail={"field": f})
            return _err("VALIDATION_ERROR", f"{f} must be a string when provided.", field=f)
    for v, f in [(listName, "listName"), (folderName, "folderName"), (spaceName, "spaceName")]:
        if v is not None and not isinstance(v, str):
            _log("VALIDATION_ERROR", detail={"field": f})
            return _err("VALIDATION_ERROR", f"{f} must be a string when provided.", field=f)

    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")
    workspaces = _load("workspaces.json")
    if not isinstance(containers, list): containers = []
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # resolve list container
    resolved = None
    if listId is not None:
        lid = listId.strip()
        matches = [c for c in containers if isinstance(c, dict) and c.get("container_id") == lid and c.get("type") == "LIST" and c.get("status") != "deleted" and c.get("workspace_id") in active_ws]
        if len(matches) != 1:
            _log("NOT_FOUND", detail={"field": "listId"})
            return _err("NOT_FOUND", "List not found.", field="listId")
        resolved = matches[0]
    else:
        ln = listName.strip()
        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "LIST" and c.get("status") != "deleted" and (c.get("name") or "") == ln and c.get("workspace_id") in active_ws]

        # optional folder/space scoping
        if folderId is not None:
            fid = folderId.strip()
            candidates = [c for c in candidates if c.get("parent_container_id") == fid]
        elif folderName is not None and folderName.strip():
            fn = folderName.strip()
            folder_candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "FOLDER" and c.get("status") != "deleted" and (c.get("name") or "") == fn and c.get("workspace_id") in active_ws]
            folder_ids = {c.get("container_id") for c in folder_candidates}
            candidates = [c for c in candidates if c.get("parent_container_id") in folder_ids]

        if spaceId is not None:
            sid = spaceId.strip()
            # list parent can be SPACE or FOLDER; if folder used, that folder's parent is space
            def _is_in_space(list_ctr):
                pid = list_ctr.get("parent_container_id")
                parent = next((c for c in containers if isinstance(c, dict) and c.get("container_id") == pid), None)
                if not parent:
                    return False
                if parent.get("type") == "SPACE":
                    return parent.get("container_id") == sid
                if parent.get("type") == "FOLDER":
                    return parent.get("parent_container_id") == sid
                return False
            candidates = [c for c in candidates if _is_in_space(c)]
        elif spaceName is not None and spaceName.strip():
            sn = spaceName.strip()
            space_candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "SPACE" and c.get("status") != "deleted" and (c.get("name") or "") == sn and c.get("workspace_id") in active_ws]
            space_ids = {c.get("container_id") for c in space_candidates}
            def _is_in_spaces(list_ctr):
                pid = list_ctr.get("parent_container_id")
                parent = next((c for c in containers if isinstance(c, dict) and c.get("container_id") == pid), None)
                if not parent:
                    return False
                if parent.get("type") == "SPACE":
                    return parent.get("container_id") in space_ids
                if parent.get("type") == "FOLDER":
                    return parent.get("parent_container_id") in space_ids
                return False
            candidates = [c for c in candidates if _is_in_spaces(c)]

        if len(candidates) == 0:
            _log("NOT_FOUND", detail={"field": "listName"})
            return _err("NOT_FOUND", "List not found.", field="listName")
        if len(candidates) > 1:
            _log("CONFLICT", detail={"field": "listName", "matches": len(candidates)})
            return _err("CONFLICT", "listName is ambiguous with the provided scope; provide listId or more scope.", field="listName", matches=len(candidates))
        resolved = candidates[0]

    # cascade delete tasks in list
    nowz = _utcnow_z()
    list_container_id = resolved.get("container_id")
    workspace_id = resolved.get("workspace_id")

    any_task_mutated = False
    for t in tasks_rows:
        if not isinstance(t, dict):
            continue
        if t.get("status") == "deleted":
            continue
        if t.get("workspace_id") == workspace_id and t.get("list_container_id") == list_container_id:
            t["status"] = "deleted"
            t["updated_at"] = nowz
            any_task_mutated = True

    # delete list (irreversible)
    list_mutated = False
    for c in containers:
        if isinstance(c, dict) and c.get("container_id") == list_container_id:
            if c.get("status") == "deleted":
                _log("NOT_FOUND", workspace_id=workspace_id, container_id=list_container_id, detail={"reason": "already_deleted"})
                return _err("NOT_FOUND", "List not found.", field="listId")
            c["status"] = "deleted"
            c["updated_at"] = nowz
            list_mutated = True
            break

    if not list_mutated:
        _log("NOT_FOUND", detail={"reason": "no_row_matched"})
        return _err("NOT_FOUND", "List not found.")

    _save("tasks.json", tasks_rows)
    _save("containers.json", containers)
    _log("OK", workspace_id=workspace_id, container_id=list_container_id, detail={"tasks_deleted": sum(1 for t in tasks_rows if isinstance(t, dict) and t.get("workspace_id") == workspace_id and t.get("list_container_id") == list_container_id and t.get("status") == "deleted")})
    return {"deleted": True, "list_id": list_container_id}

def create_folder(spaceId=None, spaceName=None, name=None, override_statuses=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_folder"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, container_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "container_id": container_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if name is None or not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", detail={"field": "name"})
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.", field="name")
    if spaceId is None and (spaceName is None or not isinstance(spaceName, str) or not spaceName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["spaceId", "spaceName"]})
        return _err("VALIDATION_ERROR", "Either spaceId or spaceName must be provided.", fields=["spaceId", "spaceName"])
    if spaceId is not None and not isinstance(spaceId, str):
        _log("VALIDATION_ERROR", detail={"field": "spaceId"})
        return _err("VALIDATION_ERROR", "spaceId must be a string when provided.", field="spaceId")
    if spaceName is not None and not isinstance(spaceName, str):
        _log("VALIDATION_ERROR", detail={"field": "spaceName"})
        return _err("VALIDATION_ERROR", "spaceName must be a string when provided.", field="spaceName")
    if override_statuses is not None and not isinstance(override_statuses, list):
        _log("VALIDATION_ERROR", detail={"field": "override_statuses"})
        return _err("VALIDATION_ERROR", "override_statuses must be an array when provided.", field="override_statuses")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(containers, list): containers = []

    # resolve space
    space_ctr = None
    if spaceId is not None:
        m = [c for c in containers if isinstance(c, dict) and c.get("status") != "deleted" and c.get("type") == "SPACE" and (c.get("container_id") == spaceId or c.get("clickup_container_id") == spaceId)]
        if len(m) == 1:
            space_ctr = m[0]
        elif len(m) == 0 and spaceName is None:
            _log("NOT_FOUND", detail={"field": "spaceId"})
            return _err("NOT_FOUND", "Space not found.", field="spaceId")
        elif len(m) > 1:
            _log("CONFLICT", detail={"field": "spaceId"})
            return _err("CONFLICT", "spaceId matched multiple spaces.", field="spaceId")
    if space_ctr is None:
        sn = spaceName.strip()
        m = [c for c in containers if isinstance(c, dict) and c.get("status") != "deleted" and c.get("type") == "SPACE" and c.get("name") == sn]
        if len(m) == 1:
            space_ctr = m[0]
        elif len(m) == 0:
            _log("NOT_FOUND", detail={"field": "spaceName"})
            return _err("NOT_FOUND", "Space not found.", field="spaceName")
        else:
            _log("CONFLICT", detail={"field": "spaceName"})
            return _err("CONFLICT", "spaceName matched multiple spaces; provide spaceId.", field="spaceName")

    wsid = space_ctr.get("workspace_id")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("workspace_id") == wsid), None)
    if not ws or ws.get("status") != "active":
        _log("UNAUTHORIZED", workspace_id=wsid, detail={"rule": "workspace must be active"})
        return _err("UNAUTHORIZED", "Workspace is not active or not accessible.", workspaceId=wsid)

    now = _utcnow_z()
    row = {
        "container_id": _gen_id("cu_ctr"),
        "workspace_id": wsid,
        "clickup_container_id": _gen_id("clk_fld"),
        "type": "FOLDER",
        "parent_container_id": space_ctr.get("container_id"),
        "name": name.strip(),
        "content": None,
        "override_statuses": override_statuses[:] if isinstance(override_statuses, list) else None,
        "archived": False,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }
    containers.append(row)
    _save("containers.json", containers)
    _log("OK", workspace_id=wsid, container_id=row["container_id"])
    return {"folder": row, "space": {"container_id": space_ctr.get("container_id"), "name": space_ctr.get("name")}}

def get_folder(folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, re, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_folder"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, workspace_id=None, detail=None):
        logs = _load("request_logs.json")
        row = {
            "request_id": "req_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(24)),
            "ts": _now(),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    _id_re = re.compile(r"^cu_ctr_[0-9A-Z]{18,}$")
    def _is_str(x): return isinstance(x, str)
    def _validate_optional_id(val, field):
        if val is None: return None
        if not _is_str(val) or not _id_re.match(val):
            return _err("VALIDATION_ERROR", f"Invalid {field} format.", field=field)
        return None

    for v, f in [(folderId, "folderId"), (spaceId, "spaceId")]:
        e = _validate_optional_id(v, f)
        if e:
            _log("VALIDATION_ERROR", detail={"field": f})
            return e

    for v, f in [(folderName, "folderName"), (spaceName, "spaceName")]:
        if v is not None and not _is_str(v):
            _log("VALIDATION_ERROR", detail={"field": f})
            return _err("VALIDATION_ERROR", f"{f} must be a string.", field=f)

    if not folderId and not folderName:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Either folderId or folderName must be provided.")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")

    active_ws_ids = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws_ids:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    def _find_container_by_id(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == cid:
                return c
        return None

    folder = None
    workspace_id = None

    if folderId:
        c = _find_container_by_id(folderId)
        if not c or c.get("type") != "FOLDER" or c.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Folder not found.", folderId=folderId)
        if c.get("workspace_id") not in active_ws_ids:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active workspace is available to serve this request for the specified folder.")
        folder = c
        workspace_id = c.get("workspace_id")
    else:
        # name-based requires space scope
        if not (spaceId or spaceName):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "When using folderName, you must provide spaceId or spaceName to scope resolution.")
        # resolve space
        space = None
        if spaceId:
            sc = _find_container_by_id(spaceId)
            if not sc or sc.get("type") != "SPACE" or sc.get("status") == "deleted":
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)
            if sc.get("workspace_id") not in active_ws_ids:
                _log("UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No active workspace is available to serve this request for the specified space.")
            space = sc
        else:
            matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "SPACE" and c.get("status") != "deleted" and c.get("name") == spaceName and c.get("workspace_id") in active_ws_ids]
            if not matches:
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Space not found.", spaceName=spaceName)
            space_ids = {m.get("container_id") for m in matches}
            if len(space_ids) != 1:
                _log("CONFLICT")
                return _err("CONFLICT", "Multiple spaces match spaceName; provide spaceId.", spaceName=spaceName)
            space = matches[0]

        workspace_id = space.get("workspace_id")

        candidates = [c for c in containers if isinstance(c, dict) and c.get("type") == "FOLDER" and c.get("status") != "deleted" and c.get("name") == folderName and c.get("parent_container_id") == space.get("container_id") and c.get("workspace_id") == workspace_id]
        if not candidates:
            _log("NOT_FOUND", workspace_id=workspace_id)
            return _err("NOT_FOUND", "Folder not found.", folderName=folderName)
        if len({c.get("container_id") for c in candidates}) != 1:
            _log("CONFLICT", workspace_id=workspace_id)
            return _err("CONFLICT", "Multiple folders match folderName in the provided space; provide folderId.", folderName=folderName)
        folder = candidates[0]

    # enrich with space metadata (id/name) when possible
    space_meta = None
    pid = folder.get("parent_container_id")
    if pid:
        p = _find_container_by_id(pid)
        if p and p.get("type") == "SPACE" and p.get("status") != "deleted":
            space_meta = {"spaceId": p.get("container_id"), "spaceName": p.get("name")}

    _log("OK", workspace_id=workspace_id)
    return {
        "ok": True,
        "folder": folder,
        "space": space_meta
    }

def update_folder(folderId=None, folderName=None, spaceId=None, spaceName=None, name=None, override_statuses=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_folder"

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    tasks = _load("tasks.json")
    activity = _load("task_activity.json")
    time_docs = _load("time_and_docs.json")

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, message=None):
        nonlocal activity
        try:
            row = {
                "activity_id": "cu_act_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "workspace_id": (resolved_workspace_id if resolved_workspace_id else (workspaces[0]["workspace_id"] if workspaces else "unknown")),
                "type": "SPACE_TAG",
                "task_id": None,
                "clickup_task_id": None,
                "space_container_id": None,
                "clickup_comment_id": None,
                "comment_text": None,
                "comment_assignee_clickup_user_id": None,
                "notify_all": None,
                "clickup_attachment_id": None,
                "filename": None,
                "source_type": None,
                "source_ref": None,
                "size_bytes": None,
                "tag_name": None,
                "tag_fg_color": None,
                "tag_bg_color": None,
                "status": "active",
                "created_at": _now(),
                "updated_at": _now(),
                "endpoint": endpoint,
                "http_status": status,
                "error_code": error_code,
                "error_message": message,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            activity.append(row)
            _save("task_activity.json", activity)
        except Exception:
            return

    def _is_str(x): return isinstance(x, str)
    def _valid_id(x, pat): return _is_str(x) and re.match(pat, x) is not None

    def _active_workspaces():
        return [w for w in workspaces if w.get("status") == "active"]

    def _resolve_space_by_id_or_name(sid, sname):
        if sid is not None:
            if not _valid_id(sid, r"^cu_ctr_[0-9A-Z]{18,}$"):
                return None, _err("VALIDATION_ERROR", "spaceId must match ^cu_ctr_[0-9A-Z]{18,}$")
            sp = next((c for c in containers if c.get("container_id") == sid and c.get("type") == "SPACE" and c.get("status") != "deleted"), None)
            if not sp:
                return None, _err("NOT_FOUND", "Space not found")
            return sp, None
        if sname is not None:
            if not _is_str(sname) or not sname.strip():
                return None, _err("VALIDATION_ERROR", "spaceName must be a non-empty string")
            matches = [c for c in containers if c.get("type") == "SPACE" and c.get("status") != "deleted" and c.get("name") == sname]
            if len(matches) == 0:
                return None, _err("NOT_FOUND", "Space not found")
            if len(matches) > 1:
                return None, _err("CONFLICT", "Multiple spaces matched spaceName; use spaceId", matches=[m.get("container_id") for m in matches])
            return matches[0], None
        return None, _err("VALIDATION_ERROR", "spaceId or spaceName is required to scope folderName resolution")

    def _resolve_folder():
        # Returns (folder_container_row, error)
        if folderId is not None:
            if not _valid_id(folderId, r"^cu_ctr_[0-9A-Z]{18,}$"):
                return None, _err("VALIDATION_ERROR", "folderId must match ^cu_ctr_[0-9A-Z]{18,}$")
            fol = next((c for c in containers if c.get("container_id") == folderId and c.get("type") == "FOLDER" and c.get("status") != "deleted"), None)
            if not fol:
                return None, _err("NOT_FOUND", "Folder not found")
            return fol, None

        if folderName is None or (not _is_str(folderName)) or not folderName.strip():
            return None, _err("VALIDATION_ERROR", "folderId or folderName is required")

        # Need space scope for folderName
        space, e = _resolve_space_by_id_or_name(spaceId, spaceName)
        if e:
            return None, e

        matches = [c for c in containers
                   if c.get("type") == "FOLDER"
                   and c.get("status") != "deleted"
                   and c.get("name") == folderName
                   and c.get("parent_container_id") == space.get("container_id")]
        if len(matches) == 0:
            return None, _err("NOT_FOUND", "Folder not found in the specified space")
        if len(matches) > 1:
            return None, _err("CONFLICT", "Multiple folders matched folderName within the specified space; use folderId",
                              matches=[m.get("container_id") for m in matches])
        return matches[0], None

    resolved_workspace_id = None
    try:
        if name is None and override_statuses is None:
            _log(400, "VALIDATION_ERROR", "No update fields provided")
            return _err("VALIDATION_ERROR", "At least one update field (name or override_statuses) must be provided")

        if name is not None:
            if not _is_str(name) or not name.strip():
                _log(400, "VALIDATION_ERROR", "Invalid name")
                return _err("VALIDATION_ERROR", "name must be a non-empty string")

        if override_statuses is not None:
            if not isinstance(override_statuses, list):
                _log(400, "VALIDATION_ERROR", "Invalid override_statuses")
                return _err("VALIDATION_ERROR", "override_statuses must be an array")
            # must be "valid array payload": accept list elements as objects (additional properties allowed)
            for i, it in enumerate(override_statuses):
                if not isinstance(it, dict):
                    _log(400, "VALIDATION_ERROR", "Invalid override_statuses item")
                    return _err("VALIDATION_ERROR", "override_statuses items must be objects", index=i)

        # Ambient auth: require at least one active workspace exists
        if not _active_workspaces():
            _log(401, "UNAUTHORIZED", "No active workspace connection")
            return _err("UNAUTHORIZED", "No active workspace is available to serve this request")

        folder, e = _resolve_folder()
        if e:
            _log(404 if e["error"]["code"] == "NOT_FOUND" else 400, e["error"]["code"], e["error"]["message"])
            return e

        resolved_workspace_id = folder.get("workspace_id")
        ws = next((w for w in workspaces if w.get("workspace_id") == resolved_workspace_id and w.get("status") == "active"), None)
        if not ws:
            _log(401, "UNAUTHORIZED", "Workspace disabled")
            return _err("UNAUTHORIZED", "Workspace is not active")

        # Validate folder parent is SPACE (constraint)
        parent = next((c for c in containers if c.get("container_id") == folder.get("parent_container_id") and c.get("status") != "deleted"), None)
        if not parent or parent.get("type") != "SPACE":
            _log(409, "CONFLICT", "Folder has invalid parent")
            return _err("CONFLICT", "Folder parent constraint violated (expected parent SPACE)")

        # Apply updates (only provided fields)
        changed = False
        if name is not None and folder.get("name") != name:
            folder["name"] = name
            changed = True
        if override_statuses is not None:
            # even if same logically, treat as update if provided
            folder["override_statuses"] = override_statuses
            changed = True

        if not changed:
            _log(200, None, None)
            return {"folder": folder, "updated": False}

        folder["updated_at"] = _now()
        _save("containers.json", containers)

        _log(200, None, None)
        return {"folder": folder, "updated": True}
    except Exception as ex:
        _log(500, "CONFLICT", "Internal error")
        return _err("CONFLICT", "Internal error", detail=str(ex))

def delete_folder(folderId=None, folderName=None, spaceId=None, spaceName=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "delete_folder"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, container_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "container_id": container_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if folderId is None and (folderName is None or not isinstance(folderName, str) or not folderName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["folderId", "folderName"]})
        return _err("VALIDATION_ERROR", "Either folderId or folderName must be provided.", fields=["folderId", "folderName"])
    if folderId is not None and not isinstance(folderId, str):
        _log("VALIDATION_ERROR", detail={"field": "folderId"})
        return _err("VALIDATION_ERROR", "folderId must be a string when provided.", field="folderId")
    if folderName is not None and not isinstance(folderName, str):
        _log("VALIDATION_ERROR", detail={"field": "folderName"})
        return _err("VALIDATION_ERROR", "folderName must be a string when provided.", field="folderName")
    if spaceId is not None and not isinstance(spaceId, str):
        _log("VALIDATION_ERROR", detail={"field": "spaceId"})
        return _err("VALIDATION_ERROR", "spaceId must be a string when provided.", field="spaceId")
    if spaceName is not None and not isinstance(spaceName, str):
        _log("VALIDATION_ERROR", detail={"field": "spaceName"})
        return _err("VALIDATION_ERROR", "spaceName must be a string when provided.", field="spaceName")

    containers = _load("containers.json")
    tasks_rows = _load("tasks.json")
    workspaces = _load("workspaces.json")
    if not isinstance(containers, list): containers = []
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(workspaces, list): workspaces = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    folder = None
    if folderId is not None:
        fid = folderId.strip()
        matches = [c for c in containers if isinstance(c, dict) and c.get("container_id") == fid and c.get("type") == "FOLDER" and c.get("status") != "deleted" and c.get("workspace_id") in active_ws]
        if len(matches) != 1:
            _log("NOT_FOUND", detail={"field": "folderId"})
            return _err("NOT_FOUND", "Folder not found.", field="folderId")
        folder = matches[0]
    else:
        # name-based requires space scope (business rule)
        if (spaceId is None or not isinstance(spaceId, str) or not spaceId.strip()) and (spaceName is None or not isinstance(spaceName, str) or not spaceName.strip()):
            _log("VALIDATION_ERROR", detail={"fields": ["spaceId", "spaceName"]})
            return _err("VALIDATION_ERROR", "spaceId or spaceName is required when deleting by folderName.", fields=["spaceId", "spaceName"])
        fn = folderName.strip()
        # resolve space
        if spaceId is not None:
            sid = spaceId.strip()
            space_matches = [c for c in containers if isinstance(c, dict) and c.get("container_id") == sid and c.get("type") == "SPACE" and c.get("status") != "deleted" and c.get("workspace_id") in active_ws]
            if len(space_matches) != 1:
                _log("NOT_FOUND", detail={"field": "spaceId"})
                return _err("NOT_FOUND", "Space not found.", field="spaceId")
            sid = space_matches[0].get("container_id")
            wsid = space_matches[0].get("workspace_id")
        else:
            sn = spaceName.strip()
            space_matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "SPACE" and c.get("status") != "deleted" and (c.get("name") or "") == sn and c.get("workspace_id") in active_ws]
            if len(space_matches) == 0:
                _log("NOT_FOUND", detail={"field": "spaceName"})
                return _err("NOT_FOUND", "Space not found.", field="spaceName")
            if len(space_matches) > 1:
                _log("CONFLICT", detail={"field": "spaceName", "matches": len(space_matches)})
                return _err("CONFLICT", "spaceName is ambiguous; provide spaceId.", field="spaceName", matches=len(space_matches))
            sid = space_matches[0].get("container_id")
            wsid = space_matches[0].get("workspace_id")

        folder_matches = [c for c in containers if isinstance(c, dict) and c.get("type") == "FOLDER" and c.get("status") != "deleted" and c.get("workspace_id") == wsid and c.get("parent_container_id") == sid and (c.get("name") or "") == fn]
        if len(folder_matches) == 0:
            _log("NOT_FOUND", detail={"field": "folderName"})
            return _err("NOT_FOUND", "Folder not found in the provided space scope.", field="folderName")
        if len(folder_matches) > 1:
            _log("CONFLICT", detail={"field": "folderName", "matches": len(folder_matches)})
            return _err("CONFLICT", "folderName is ambiguous within the provided space scope; provide folderId.", field="folderName", matches=len(folder_matches))
        folder = folder_matches[0]

    workspace_id = folder.get("workspace_id")
    folder_id = folder.get("container_id")
    nowz = _utcnow_z()

    # Cascade: folder -> lists -> tasks (mark deleted)
    list_ids = [c.get("container_id") for c in containers if isinstance(c, dict) and c.get("type") == "LIST" and c.get("status") != "deleted" and c.get("parent_container_id") == folder_id and c.get("workspace_id") == workspace_id]

    for c in containers:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != workspace_id:
            continue
        if c.get("status") == "deleted":
            continue
        if c.get("container_id") == folder_id and c.get("type") == "FOLDER":
            c["status"] = "deleted"
            c["updated_at"] = nowz
        elif c.get("type") == "LIST" and c.get("parent_container_id") == folder_id:
            c["status"] = "deleted"
            c["updated_at"] = nowz

    for t in tasks_rows:
        if not isinstance(t, dict):
            continue
        if t.get("workspace_id") != workspace_id:
            continue
        if t.get("status") == "deleted":
            continue
        if t.get("list_container_id") in set(list_ids):
            t["status"] = "deleted"
            t["updated_at"] = nowz

    # Ensure folder actually mutated (no success without effect)
    if folder.get("status") == "deleted":
        _log("NOT_FOUND", workspace_id=workspace_id, container_id=folder_id, detail={"reason": "already_deleted"})
        return _err("NOT_FOUND", "Folder not found.", field="folderId")

    _save("containers.json", containers)
    _save("tasks.json", tasks_rows)
    _log("OK", workspace_id=workspace_id, container_id=folder_id, detail={"lists_deleted": len(list_ids)})
    return {"deleted": True, "folder_id": folder_id}

