    if taskId is None and (taskName is None or not isinstance(taskName, str) or not taskName.strip()):
        _log("VALIDATION_ERROR", detail={"fields": ["taskId", "taskName"]})
        return _err("VALIDATION_ERROR", "You must provide taskId or taskName.", fields=["taskId", "taskName"])
    if taskId is not None and not isinstance(taskId, str):
        _log("VALIDATION_ERROR", detail={"field": "taskId"})
        return _err("VALIDATION_ERROR", "taskId must be a string when provided.", field="taskId")
    if taskName is not None and not isinstance(taskName, str):
        _log("VALIDATION_ERROR", detail={"field": "taskName"})
        return _err("VALIDATION_ERROR", "taskName must be a string when provided.", field="taskName")
    if listId is not None and not isinstance(listId, str):
        _log("VALIDATION_ERROR", detail={"field": "listId"})
        return _err("VALIDATION_ERROR", "listId must be a string when provided.", field="listId")
    if listName is not None and not isinstance(listName, str):
        _log("VALIDATION_ERROR", detail={"field": "listName"})
        return _err("VALIDATION_ERROR", "listName must be a string when provided.", field="listName")

    tasks_rows = _load("tasks.json")
    containers = _load("containers.json")
    workspaces = _load("workspaces.json")
    activity = _load("task_activity.json")
    if not isinstance(tasks_rows, list): tasks_rows = []
    if not isinstance(containers, list): containers = []
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(activity, list): activity = []

    active_ws = {w.get("workspace_id") for w in workspaces if isinstance(w, dict) and w.get("status") == "active"}
    if not active_ws:
        _log("UNAUTHORIZED", detail={"reason": "no_active_workspace"})
        return _err("UNAUTHORIZED", "No active workspace is available to serve this request.")

    # resolve task (taskName may be ambiguous without list scope; listId/listName are acceptable scopes)
    resolved = None
    if taskId is not None:
        tid = taskId.strip()
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("task_id") == tid)]
        if len(candidates) == 0:
            candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("clickup_task_id") == tid or (t.get("clickup_custom_id") and t.get("clickup_custom_id") == tid))]
        if len(candidates) != 1:
            _log("NOT_FOUND", detail={"field": "taskId"})
            return _err("NOT_FOUND", "Task not found.", field="taskId")
        resolved = candidates[0]
    else:
        tn = taskName.strip()
        candidates = [t for t in tasks_rows if isinstance(t, dict) and t.get("status") != "deleted" and t.get("workspace_id") in active_ws and (t.get("name") or "") == tn]
        if listId is not None:
            lid = listId.strip()
            candidates = [t for t in candidates if t.get("list_container_id") == lid]
        elif listName is not None and listName.strip():
            ln = listName.strip()
            list_ids_by_ws = {}
            for c in containers:
                if not isinstance(c, dict): 
                    continue
                if c.get("status") == "deleted" or c.get("type") != "LIST":
                    continue
                if (c.get("name") or "") == ln and c.get("workspace_id") in active_ws:
                    list_ids_by_ws.setdefault(c.get("workspace_id"), set()).add(c.get("container_id"))
            scoped = []
            for t in candidates:
                ws = t.get("workspace_id")
                if ws in list_ids_by_ws and t.get("list_container_id") in list_ids_by_ws[ws]:
                    scoped.append(t)
            candidates = scoped

        if len(candidates) == 0:
            _log("NOT_FOUND", detail={"field": "taskName"})
            return _err("NOT_FOUND", "Task not found.", field="taskName")
        if len(candidates) > 1:
            _log("CONFLICT", detail={"field": "taskName", "matches": len(candidates)})
            return _err("CONFLICT", "taskName is ambiguous; provide taskId or scope with listId/listName.", field="taskName", matches=len(candidates))
        resolved = candidates[0]

    workspace_id = resolved.get("workspace_id")
    clickup_task_id = resolved.get("clickup_task_id")
    if workspace_id not in active_ws:
        _log("UNAUTHORIZED", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"reason": "workspace_not_active"})
        return _err("UNAUTHORIZED", "Workspace is not active for this operation.", workspace_id=workspace_id)

    # Find the task's space via list -> parent (folder/space) -> space
    def _find_container(cid):
        for c in containers:
            if isinstance(c, dict) and c.get("container_id") == cid and c.get("status") != "deleted":
                return c
        return None

    list_ctr = _find_container(resolved.get("list_container_id"))
    if not list_ctr or list_ctr.get("type") != "LIST":
        _log("NOT_FOUND", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"reason": "list_missing"})
        return _err("NOT_FOUND", "Task list container not found (cannot resolve space).")
    parent = _find_container(list_ctr.get("parent_container_id"))
    space_ctr = None
    if parent and parent.get("type") == "SPACE":
        space_ctr = parent
    elif parent and parent.get("type") == "FOLDER":
        space_ctr = _find_container(parent.get("parent_container_id"))
    if not space_ctr or space_ctr.get("type") != "SPACE":
        _log("NOT_FOUND", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"reason": "space_missing"})
        return _err("NOT_FOUND", "Space not found for task (cannot validate tag).")

    space_container_id = space_ctr.get("container_id")

    # Validate tag exists as SPACE_TAG in this space
    space_tags = [a for a in activity if isinstance(a, dict) and a.get("status") != "deleted" and a.get("type") == "SPACE_TAG" and a.get("workspace_id") == workspace_id and a.get("space_container_id") == space_container_id and (a.get("tag_name") or "") == tg]
    if len(space_tags) == 0:
        _log("NOT_FOUND", workspace_id=workspace_id, task_id=resolved.get("task_id"), detail={"field": "tagName"})
        return _err("NOT_FOUND", "Tag does not exist in this space; create it first.", field="tagName")

    # Idempotency: if already linked, return existing TASK_TAG
    existing_link = None
    for a in activity:
        if not isinstance(a, dict):
            continue
        if a.get("status") == "deleted":
            continue
        if a.get("type") != "TASK_TAG":
            continue
        if a.get("workspace_id") == workspace_id and a.get("clickup_task_id") == clickup_task_id and (a.get("tag_name") or "") == tg:
            existing_link = a
            break
    if existing_link is not None:
        _log("OK", workspace_id=workspace_id, task_id=resolved.get("task_id"), activity_id=existing_link.get("activity_id"), detail={"idempotent": True})
        return {"tag": existing_link}

    nowz = _utcnow_z()
    new_activity_id = _gen_id("cu_act")
    row = {
        "activity_id": new_activity_id,
        "workspace_id": workspace_id,
        "type": "TASK_TAG",
        "task_id": resolved.get("task_id"),
        "clickup_task_id": clickup_task_id,
        "space_container_id": space_container_id,
        "clickup_comment_id": None,
        "comment_text": None,
        "comment_assignee_clickup_user_id": None,
        "notify_all": None,
        "clickup_attachment_id": None,
        "filename": None,
        "source_type": None,
        "source_ref": None,
        "size_bytes": None,
        "tag_name": tg,
        "tag_fg_color": space_tags[0].get("tag_fg_color"),
        "tag_bg_color": space_tags[0].get("tag_bg_color"),
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }
    activity.append(row)
    _save("task_activity.json", activity)

    # update denormalized tags on task row
    mutated_task = False
    for t in tasks_rows:
        if isinstance(t, dict) and t.get("task_id") == resolved.get("task_id"):
            cur = t.get("tags")
            if not isinstance(cur, list):
                cur = []
            if tg not in cur:
                cur.append(tg)
                t["tags"] = cur
                t["updated_at"] = nowz
                mutated_task = True
            break
    if mutated_task:
        _save("tasks.json", tasks_rows)

    _log("OK", workspace_id=workspace_id, task_id=resolved.get("task_id"), activity_id=new_activity_id)
    return {"tag": row}

def remove_tag_from_task(workspaceId, tagName, taskId=None, taskName=None, listName=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "remove_tag_from_task"
    status = "success"
    err_obj = None

    workspaces = _load("workspaces.json")
    tasks = _load("tasks.json")
    containers = _load("containers.json")
    activity = _load("task_activity.json")
    request_logs = _load("request_logs.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_val, error_code=None):
        nonlocal request_logs
        now = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "request_id": f"req_{int(time.time()*1000)}_{len(request_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspaceId,
            "status": status_val,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", request_logs)

    def _validate():
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[A-Za-z0-9]+$", workspaceId):
            return _err("VALIDATION_ERROR", "workspaceId is required and must match ^cu_wsp_[A-Za-z0-9]+$",
                        field="workspaceId")
        if not isinstance(tagName, str) or not tagName.strip():
            return _err("VALIDATION_ERROR", "tagName is required", field="tagName")
        if taskId is None and taskName is None:
            return _err("VALIDATION_ERROR", "Either taskId or taskName is required to resolve the task",
                        field="taskId")
        if taskId is not None:
            if not isinstance(taskId, str) or not re.match(r"^cu_tsk_[A-Za-z0-9]+$", taskId):
                return _err("VALIDATION_ERROR", "taskId must match ^cu_tsk_[A-Za-z0-9]+$", field="taskId")
        if taskName is not None and (not isinstance(taskName, str) or not taskName.strip()):
            return _err("VALIDATION_ERROR", "taskName must be a non-empty string", field="taskName")
        if listName is not None and (not isinstance(listName, str) or not listName.strip()):
            return _err("VALIDATION_ERROR", "listName must be a non-empty string when provided", field="listName")
        return None

    try:
        v = _validate()
        if v:
            status = "error"
            err_obj = v
            _log("error", v["error"]["code"])
            return v

        ws = next((w for w in workspaces if w.get("workspace_id") == workspaceId), None)
        if not ws:
            status = "error"
            err_obj = _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)
            _log("error", err_obj["error"]["code"])
            return err_obj
        if ws.get("status") != "active":
            status = "error"
            err_obj = _err("UNAUTHORIZED", "Workspace is disabled", workspaceId=workspaceId)
            _log("error", err_obj["error"]["code"])
            return err_obj

        # Resolve list scope if listName provided
        scoped_list_ids = None
        if listName is not None:
            matching_lists = [
                c for c in containers
                if c.get("workspace_id") == workspaceId
                and c.get("status") != "deleted"
                and c.get("type") == "LIST"
                and (c.get("name") or "").strip().lower() == listName.strip().lower()
            ]
            if len(matching_lists) == 0:
                status = "error"
                err_obj = _err("NOT_FOUND", "List not found for provided listName", listName=listName)
                _log("error", err_obj["error"]["code"])
                return err_obj
            if len(matching_lists) > 1:
                status = "error"
                err_obj = _err("CONFLICT", "Multiple lists match listName; provide a more specific scope",
                               listName=listName, match_count=len(matching_lists))
                _log("error", err_obj["error"]["code"])
                return err_obj
            scoped_list_ids = {matching_lists[0].get("container_id")}

        # Resolve task
        task_row = None
        if taskId is not None:
            task_row = next((t for t in tasks
                             if t.get("workspace_id") == workspaceId
                             and t.get("status") != "deleted"
                             and t.get("task_id") == taskId), None)
            if not task_row:
                status = "error"
                err_obj = _err("NOT_FOUND", "Task not found", taskId=taskId)
                _log("error", err_obj["error"]["code"])
                return err_obj
        else:
            matches = [
                t for t in tasks
                if t.get("workspace_id") == workspaceId
                and t.get("status") != "deleted"
                and (t.get("name") or "").strip().lower() == taskName.strip().lower()
            ]
            if scoped_list_ids is not None:
                matches = [t for t in matches if t.get("list_container_id") in scoped_list_ids]
            if len(matches) == 0:
                status = "error"
                err_obj = _err("NOT_FOUND", "Task not found", taskName=taskName, listName=listName)
                _log("error", err_obj["error"]["code"])
                return err_obj
            if len(matches) > 1:
                status = "error"
                err_obj = _err("CONFLICT",
                               "Multiple tasks match taskName; provide listName to disambiguate",
                               taskName=taskName, match_count=len(matches))
                _log("error", err_obj["error"]["code"])
                return err_obj
            task_row = matches[0]

        # Remove association: delete TASK_TAG activity rows (soft delete)
        cu_tid = task_row.get("clickup_task_id")
        to_delete = []
        for a in activity:
            if a.get("workspace_id") != workspaceId:
                continue
            if a.get("status") == "deleted":
                continue
            if a.get("type") != "TASK_TAG":
                continue
            # Match by internal task_id OR vendor id
            if a.get("task_id") == task_row.get("task_id") or (cu_tid and a.get("clickup_task_id") == cu_tid):
                if (a.get("tag_name") or "").strip().lower() == tagName.strip().lower():
                    to_delete.append(a)

        if not to_delete:
            status = "error"
            err_obj = _err("NOT_FOUND", "Tag is not associated with the task", tagName=tagName,
                           taskId=task_row.get("task_id"))
            _log("error", err_obj["error"]["code"])
            return err_obj

        now = _iso_now()
        for a in to_delete:
            a["status"] = "deleted"
            a["updated_at"] = now

        # Update denormalized tags in tasks row if present
        if isinstance(task_row.get("tags"), list):
            remaining = []
            for tg in task_row.get("tags"):
                if isinstance(tg, str):
                    if tg.strip().lower() != tagName.strip().lower():
                        remaining.append(tg)
                elif isinstance(tg, dict) and "name" in tg:
                    if (str(tg.get("name") or "")).strip().lower() != tagName.strip().lower():
                        remaining.append(tg)
                else:
                    remaining.append(tg)
            task_row["tags"] = remaining
            task_row["updated_at"] = now

        _save("task_activity.json", activity)
        _save("tasks.json", tasks)

        _log("success", None)
        return {
            "workspaceId": workspaceId,
            "task": {
                "taskId": task_row.get("task_id"),
                "clickupTaskId": task_row.get("clickup_task_id"),
                "name": task_row.get("name"),
                "listContainerId": task_row.get("list_container_id"),
                "tags": task_row.get("tags") if isinstance(task_row.get("tags"), list) else None,
                "updatedAt": task_row.get("updated_at")
            },
            "removed": {
                "tagName": tagName,
                "associationsDeleted": len(to_delete)
            }
        }
    except Exception as e:
        status = "error"
        err_obj = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log("error", err_obj["error"]["code"])
        return err_obj

def get_workspace_members(workspaceId, forceRefresh=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_workspace_members"

    workspaces = _load("workspaces.json")
    request_logs = _load("request_logs.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_val, error_code=None):
        now = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "request_id": f"req_{int(time.time()*1000)}_{len(request_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspaceId,
            "status": status_val,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", request_logs)

    def _validate():
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[A-Za-z0-9]+$", workspaceId):
            return _err("VALIDATION_ERROR", "workspaceId is required and must match ^cu_wsp_[A-Za-z0-9]+$",
                        field="workspaceId")
        if forceRefresh is not None and not isinstance(forceRefresh, bool):
            return _err("VALIDATION_ERROR", "forceRefresh must be a boolean when provided", field="forceRefresh")
        return None

    try:
        v = _validate()
        if v:
            _log("error", v["error"]["code"])
            return v

        ws = next((w for w in workspaces if w.get("workspace_id") == workspaceId), None)
        if not ws:
            e = _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)
            _log("error", e["error"]["code"])
            return e
        if ws.get("status") != "active":
            e = _err("UNAUTHORIZED", "Workspace is disabled", workspaceId=workspaceId)
            _log("error", e["error"]["code"])
            return e

        # Member cache TTL (configured server-side); use 15 minutes default.
        TTL_SECONDS = 15 * 60

        def _parse_dt(s):
            if not s or not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        now_dt = datetime.datetime.utcnow()
        synced_at = _parse_dt(ws.get("members_synced_at"))
        cache_age = None if synced_at is None else (now_dt - synced_at).total_seconds()
        stale = (ws.get("members_cache") is None) or (synced_at is None) or (cache_age is not None and cache_age > TTL_SECONDS)

        # No real ClickUp connectivity in this datastore-backed server; refresh means "touch/update timestamp"
        do_refresh = bool(forceRefresh) or stale
        if do_refresh:
            ws["members_synced_at"] = _iso_now()
            ws["updated_at"] = ws["members_synced_at"]
            if ws.get("members_cache") is None:
                ws["members_cache"] = []
            _save("workspaces.json", workspaces)

        members = ws.get("members_cache")
        if members is None:
            members = []

        _log("success", None)
        return {
            "workspaceId": workspaceId,
            "members": members,
            "cache": {
                "refreshed": do_refresh,
                "membersSyncedAt": ws.get("members_synced_at")
            }
        }
    except Exception as e:
        err = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log("error", err["error"]["code"])
        return err

