            vals = []
            if isinstance(m, dict):
                for k in ("name", "username", "email"):
                    v = m.get(k)
                    if isinstance(v, str) and v.strip():
                        vals.append(v.strip().lower())
                # ClickUp often nests user profile as {"user": {...}}
                u = m.get("user")
                if isinstance(u, dict):
                    for k in ("username", "email", "name"):
                        v = u.get(k)
                        if isinstance(v, str) and v.strip():
                            vals.append(v.strip().lower())
            return vals

        matches = []
        for m in members:
            ss = _member_strings(m)
            if any(q == s for s in ss):
                matches.append(m)

        # If no exact match, allow substring
        if not matches:
            for m in members:
                ss = _member_strings(m)
                if any(q in s for s in ss):
                    matches.append(m)

        result = None
        if len(matches) == 1:
            result = matches[0]
        elif len(matches) > 1:
            # Ambiguous; return null (tool spec: member object if found, or null)
            result = None

        _log("success", None)
        return {
            "workspaceId": workspaceId,
            "query": query,
            "member": result
        }
    except Exception as e:
        err = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log("error", err["error"]["code"])
        return err

def resolve_assignees(workspaceId, assignees, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "resolve_assignees"

    workspaces = _load("workspaces.json")
    request_logs = _load("request_logs.json")

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_val, error_code=None):
        now = _iso_now()
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "request_id": f"req_{int(time.time()*1000)}_{len(request_logs)+1}",
            "endpoint": endpoint,
            "workspace_id": workspaceId,
            "status": status_val,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", request_logs)

    def _validate():
        if not isinstance(workspaceId, str) or not re.match(r"^cu_wsp_[A-Za-z0-9]+$", workspaceId):
            return _err("VALIDATION_ERROR", "workspaceId is required and must match ^cu_wsp_[A-Za-z0-9]+$",
                        field="workspaceId")
        if not isinstance(assignees, list) or any(not isinstance(a, str) or not a.strip() for a in assignees):
            return _err("VALIDATION_ERROR", "assignees must be an array of non-empty strings", field="assignees")
        return None

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _extract_user_id(m):
        # Try common ClickUp shapes
        if isinstance(m, dict):
            for k in ("id", "user_id", "clickup_user_id"):
                v = m.get(k)
                if isinstance(v, str) and v.strip():
                    return v
            u = m.get("user")
            if isinstance(u, dict):
                for k in ("id", "user_id"):
                    v = u.get(k)
                    if isinstance(v, str) and v.strip():
                        return v
        return None

    def _member_strings(m):
        vals = []
        if isinstance(m, dict):
            for k in ("name", "username", "email"):
                v = m.get(k)
                if isinstance(v, str) and v.strip():
                    vals.append(v.strip().lower())
            u = m.get("user")
            if isinstance(u, dict):
                for k in ("username", "email", "name"):
                    v = u.get(k)
                    if isinstance(v, str) and v.strip():
                        vals.append(v.strip().lower())
        return vals

    try:
        v = _validate()
        if v:
            _log("error", v["error"]["code"])
            return v

        ws = next((w for w in workspaces if w.get("workspace_id") == workspaceId), None)
        if not ws:
            e = _err("NOT_FOUND", "Workspace not found", workspaceId=workspaceId)
            _log("error", e["error"]["code"])
            return e
        if ws.get("status") != "active":
            e = _err("UNAUTHORIZED", "Workspace is disabled", workspaceId=workspaceId)
            _log("error", e["error"]["code"])
            return e

        # Refresh if stale (per business rule)
        TTL_SECONDS = 15 * 60
        now_dt = datetime.datetime.utcnow()
        synced_at = _parse_dt(ws.get("members_synced_at"))
        stale = (ws.get("members_cache") is None) or (synced_at is None) or ((now_dt - synced_at).total_seconds() > TTL_SECONDS if synced_at else True)
        if stale:
            ws["members_synced_at"] = _iso_now()
            ws["updated_at"] = ws["members_synced_at"]
            if ws.get("members_cache") is None:
                ws["members_cache"] = []
            _save("workspaces.json", workspaces)

        members = ws.get("members_cache") or []

        resolved_ids = []
        errors = []

        for raw in assignees:
            q = raw.strip().lower()
            # Find exact matches first, then substring
            exact = []
            for m in members:
                ss = _member_strings(m)
                if any(q == s for s in ss):
                    exact.append(m)
            cand = exact
            if not cand:
                for m in members:
                    ss = _member_strings(m)
                    if any(q in s for s in ss):
                        cand.append(m)

            if len(cand) == 0:
                errors.append({"assignee": raw, "code": "NOT_FOUND", "message": "Assignee not found in workspace members"})
                continue
            if len(cand) > 1:
                errors.append({"assignee": raw, "code": "CONFLICT", "message": "Assignee is ambiguous; provide email for disambiguation"})
                continue

            uid = _extract_user_id(cand[0])
            if not uid:
                errors.append({"assignee": raw, "code": "CONFLICT", "message": "Member record missing user id"})
                continue
            resolved_ids.append(uid)

        if errors:
            e = _err("VALIDATION_ERROR", "One or more assignees could not be resolved", errors=errors, resolved=resolved_ids)
            _log("error", e["error"]["code"])
            return e

        # De-duplicate while preserving order
        seen = set()
        uniq_ids = []
        for uid in resolved_ids:
            if uid not in seen:
                seen.add(uid)
                uniq_ids.append(uid)

        _log("success", None)
        return {
            "workspaceId": workspaceId,
            "assignees": assignees,
            "clickupUserIds": uniq_ids
        }
    except Exception as e:
        err = _err("CONFLICT", "Unexpected server error", detail=str(e))
        _log("error", err["error"]["code"])
        return err

def create_document(workspaceId, name, parent, visibility, createPage, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_document"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, workspace_id=None, entity_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "entity_id": entity_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(workspaceId, str) or not workspaceId.strip():
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "workspaceId"})
        return _err("VALIDATION_ERROR", "workspaceId is required and must be a string.", field="workspaceId")
    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "name"})
        return _err("VALIDATION_ERROR", "name is required.", field="name")
    if not isinstance(parent, dict) or "type" not in parent or "id" not in parent or any(k not in ("type", "id") for k in parent.keys()):
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "parent"})
        return _err("VALIDATION_ERROR", "parent must be an object with required fields {type, id}.", field="parent")
    if parent.get("type") not in (4, 5, 6, 7, 12):
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "parent.type"})
        return _err("VALIDATION_ERROR", "parent.type must be one of 4,5,6,7,12.", field="parent.type")
    if not isinstance(parent.get("id"), str) or not parent.get("id").strip():
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "parent.id"})
        return _err("VALIDATION_ERROR", "parent.id must be a non-empty string.", field="parent.id")
    if visibility not in ("private", "workspace", "public", "unknown"):
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "visibility"})
        return _err("VALIDATION_ERROR", "visibility must be one of private, workspace, public, unknown.", field="visibility")
    if not isinstance(createPage, bool):
        _log("VALIDATION_ERROR", workspace_id=workspaceId, detail={"field": "createPage"})
        return _err("VALIDATION_ERROR", "createPage must be a boolean.", field="createPage")

    workspaces = _load("workspaces.json")
    containers = _load("containers.json")
    entities = _load("time_and_docs.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(containers, list): containers = []
    if not isinstance(entities, list): entities = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("workspace_id") == workspaceId and w.get("status") == "active"), None)
    if ws is None:
        _log("NOT_FOUND", workspace_id=workspaceId, detail={"field": "workspaceId"})
        return _err("NOT_FOUND", "Workspace not found or not active.", field="workspaceId")

    parent_type = parent["type"]
    parent_id = parent["id"].strip()

    # resolve parent container based on type
    resolved_parent_container_id = None

    if parent_type in (4, 5, 6, 7, 12):
        if parent_type == 12:
            # WORKSPACE: allow either workspace.clickup_team_id or workspaceId itself
            if parent_id != ws.get("clickup_team_id") and parent_id != workspaceId:
                _log("NOT_FOUND", workspace_id=workspaceId, detail={"field": "parent.id"})
                return _err("NOT_FOUND", "parent.id does not match the workspace/team for this workspaceId.", field="parent.id")
            # find a WORKSPACE container for this workspace (or allow EVERYTHING/WORKSPACE synthetic)
            wctr = next((c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspaceId and c.get("type") == "WORKSPACE" and c.get("status") != "deleted"), None)
            if wctr is None:
                # fallback: ANYTHING that can act as parent for docs (EVERYTHING)
                wctr = next((c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspaceId and c.get("type") in ("WORKSPACE", "EVERYTHING") and c.get("status") != "deleted"), None)
            if wctr is None:
                _log("UNAUTHORIZED", workspace_id=workspaceId, detail={"reason": "no_parent_container"})
                return _err("UNAUTHORIZED", "No suitable parent container exists in this workspace.")
            resolved_parent_container_id = wctr.get("container_id")

        elif parent_type == 7:
            # EVERYTHING: allow parent id to be anything; resolve to EVERYTHING container in workspace
            ectr = next((c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspaceId and c.get("type") == "EVERYTHING" and c.get("status") != "deleted"), None)
            if ectr is None:
                _log("NOT_FOUND", workspace_id=workspaceId, detail={"field": "parent.type"})
                return _err("NOT_FOUND", "EVERYTHING container not found for this workspace.", field="parent.type")
            resolved_parent_container_id = ectr.get("container_id")

        else:
            # SPACE/FOLDER/LIST: parent.id is vendor container id (clickup_container_id)
            desired_type = {4: "SPACE", 5: "FOLDER", 6: "LIST"}[parent_type]
            matches = [c for c in containers if isinstance(c, dict) and c.get("workspace_id") == workspaceId and c.get("type") == desired_type and c.get("status") != "deleted" and c.get("clickup_container_id") == parent_id]
            if len(matches) == 0:
                _log("NOT_FOUND", workspace_id=workspaceId, detail={"field": "parent.id"})
                return _err("NOT_FOUND", "Parent container not found.", field="parent.id")
            if len(matches) > 1:
                _log("CONFLICT", workspace_id=workspaceId, detail={"field": "parent.id", "matches": len(matches)})
                return _err("CONFLICT", "Parent container id is ambiguous.", field="parent.id", matches=len(matches))
            resolved_parent_container_id = matches[0].get("container_id")

    nowz = _utcnow_z()
    entity_id = _gen_id("cu_ent")
    clickup_document_id = _gen_id("doc")

    # enforce unique(workspace_id, clickup_document_id) where not null
    if any(isinstance(e, dict) and e.get("workspace_id") == workspaceId and e.get("clickup_document_id") == clickup_document_id for e in entities):
        clickup_document_id = _gen_id("doc")

    row = {
        "entity_id": entity_id,
        "workspace_id": workspaceId,
        "type": "DOCUMENT",
        "task_id": None,
        "clickup_task_id": None,
        "clickup_time_entry_id": None,
        "start_time": None,
        "end_time": None,
        "duration_seconds": None,
        "billable": None,
        "description": None,
        "tags": None,
        "clickup_user_id": None,
        "document_id": None,
        "clickup_document_id": clickup_document_id,
        "clickup_page_id": None,
        "title": name.strip(),
        "content": None,
        "content_format": None,
        "parent_container_id": resolved_parent_container_id,
        "parent_type_code": parent_type,
        "visibility": visibility,
        "create_page": createPage,
        "depth": None,
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }

    entities.append(row)
    _save("time_and_docs.json", entities)
    _log("OK", workspace_id=workspaceId, entity_id=entity_id)
    return {"document": row}

def get_document(workspaceId, documentId=None, title=None, parentType=None, parentId=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None, workspace_id=None, entity_id=None):
        logs = _load("request_log.json")
        row = {
            "request_id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if workspace_id is not None:
            row["workspace_id"] = workspace_id
        if entity_id is not None:
            row["entity_id"] = entity_id
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_log.json", logs)

    try:
        if not (isinstance(workspaceId, str) and re.match(r"^cu_wsp_[A-Za-z0-9]+$", workspaceId)):
            out = _err("VALIDATION_ERROR", "workspaceId is missing or invalid.")
            _log("get_document", "VALIDATION_ERROR", "invalid_workspaceId", workspace_id=workspaceId)
            return out

        workspaces = _load("workspaces.json")
        wsp = next((w for w in workspaces if w.get("workspace_id") == workspaceId and w.get("status") == "active"), None)
        if not wsp:
            out = _err("NOT_FOUND", "Workspace not found.")
            _log("get_document", "NOT_FOUND", "workspace_not_found", workspace_id=workspaceId)
            return out

        entities = _load("time_and_docs.json")

        doc = None
        if documentId is not None:
            if not (isinstance(documentId, str) and re.match(r"^cu_ent_[A-Za-z0-9]+$", documentId)):
                out = _err("VALIDATION_ERROR", "documentId is invalid.")
                _log("get_document", "VALIDATION_ERROR", "invalid_documentId", workspace_id=workspaceId)
                return out
            doc = next((e for e in entities
                        if e.get("workspace_id") == workspaceId and e.get("entity_id") == documentId
                        and e.get("type") == "DOCUMENT" and e.get("status") != "deleted"), None)
            if not doc:
                out = _err("NOT_FOUND", "Document not found.")
                _log("get_document", "NOT_FOUND", "doc_not_found_by_id", workspace_id=workspaceId, entity_id=documentId)
                return out
            _log("get_document", "ok", workspace_id=workspaceId, entity_id=documentId)
            return {"document": doc}

        # Title-based resolution requires complete scope
        if not (isinstance(title, str) and title.strip()):
            out = _err("VALIDATION_ERROR", "Either documentId or (title + parentType + parentId) must be provided.")
            _log("get_document", "VALIDATION_ERROR", "missing_identifier", workspace_id=workspaceId)
            return out
        if parentType is None or parentId is None:
            out = _err("VALIDATION_ERROR", "parentType and parentId are required when searching by title.")
            _log("get_document", "VALIDATION_ERROR", "missing_scope", workspace_id=workspaceId)
            return out
        if parentType not in ("SPACE", "FOLDER", "LIST", "EVERYTHING", "WORKSPACE"):
            out = _err("VALIDATION_ERROR", "parentType is unsupported.")
            _log("get_document", "VALIDATION_ERROR", "invalid_parentType", workspace_id=workspaceId)
            return out
        if not isinstance(parentId, str) or not parentId:
            out = _err("VALIDATION_ERROR", "parentId is invalid.")
            _log("get_document", "VALIDATION_ERROR", "invalid_parentId", workspace_id=workspaceId)
            return out

        # parentId here is INTERNAL container id per tool spec
        parent_container_id = parentId
        if parentType in ("SPACE", "FOLDER", "LIST", "EVERYTHING", "WORKSPACE"):
            containers = _load("containers.json")
            if parentType in ("SPACE", "FOLDER", "LIST"):
                c = next((x for x in containers if x.get("workspace_id") == workspaceId and x.get("container_id") == parent_container_id
                          and x.get("type") == parentType and x.get("status") == "active"), None)
                if not c:
                    out = _err("NOT_FOUND", "Parent container not found.")
                    _log("get_document", "NOT_FOUND", "parent_not_found", workspace_id=workspaceId)
                    return out
            else:
                c = next((x for x in containers if x.get("workspace_id") == workspaceId and x.get("container_id") == parent_container_id
                          and x.get("type") == parentType and x.get("status") == "active"), None)
                if not c:
                    # Allow documents with null parent_container_id for EVERYTHING/WORKSPACE; in that case parentId must match actual stored parent_container_id
                    pass

        matches = [e for e in entities
                   if e.get("workspace_id") == workspaceId and e.get("type") == "DOCUMENT" and e.get("status") != "deleted"
                   and (e.get("title") == title)
                   and (e.get("parent_container_id") == parent_container_id)]
        if len(matches) == 0:
            out = _err("NOT_FOUND", "Document not found for given scope.")
            _log("get_document", "NOT_FOUND", "doc_not_found_by_title", workspace_id=workspaceId)
            return out
        if len(matches) > 1:
            out = _err("CONFLICT", "Multiple documents match this title within the provided scope.", count=len(matches))
            _log("get_document", "CONFLICT", "multiple_matches", workspace_id=workspaceId)
            return out

        doc = matches[0]
        _log("get_document", "ok", workspace_id=workspaceId, entity_id=doc.get("entity_id"))
        return {"document": doc}
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log("get_document", "VALIDATION_ERROR", "unexpected_error", workspace_id=workspaceId)
        return out

def list_documents(workspaceId, parentType=None, parentId=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None, workspace_id=None):
        logs = _load("request_log.json")
        row = {
            "request_id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if workspace_id is not None:
            row["workspace_id"] = workspace_id
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_log.json", logs)

    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            parts = s.split(":", 1)
            if len(parts) != 2 or parts[0] != "idx":
                return None
            return int(parts[1])
        except Exception:
            return None

    def _encode_cursor(i):
        s = f"idx:{i}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    try:
        if not (isinstance(workspaceId, str) and re.match(r"^cu_wsp_[A-Za-z0-9]+$", workspaceId)):
            out = _err("VALIDATION_ERROR", "workspaceId is missing or invalid.")
            _log("list_documents", "VALIDATION_ERROR", "invalid_workspaceId", workspace_id=workspaceId)
            return out

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            out = _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
            _log("list_documents", "VALIDATION_ERROR", "invalid_limit", workspace_id=workspaceId)
            return out

        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "title"):
            out = _err("VALIDATION_ERROR", "sort must be one of created_at, updated_at, title.")
            _log("list_documents", "VALIDATION_ERROR", "invalid_sort", workspace_id=workspaceId)
            return out

        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            out = _err("VALIDATION_ERROR", "order must be one of asc, desc.")
            _log("list_documents", "VALIDATION_ERROR", "invalid_order", workspace_id=workspaceId)
            return out

        pt = None
        if parentType is not None:
            if not isinstance(parentType, str):
                out = _err("VALIDATION_ERROR", "parentType must be a string.")
                _log("list_documents", "VALIDATION_ERROR", "invalid_parentType", workspace_id=workspaceId)
                return out
            pt = parentType.upper()
            if pt not in ("SPACE", "FOLDER", "LIST", "EVERYTHING", "WORKSPACE"):
                out = _err("VALIDATION_ERROR", "parentType is unsupported.")
                _log("list_documents", "VALIDATION_ERROR", "invalid_parentType_value", workspace_id=workspaceId)
                return out

        if parentId is not None and (not isinstance(parentId, str) or not parentId):
            out = _err("VALIDATION_ERROR", "parentId is invalid.")
            _log("list_documents", "VALIDATION_ERROR", "invalid_parentId", workspace_id=workspaceId)
            return out

        if parentId is not None and pt is None:
            out = _err("VALIDATION_ERROR", "parentType is required when parentId is provided.")
            _log("list_documents", "VALIDATION_ERROR", "parentId_without_type", workspace_id=workspaceId)
            return out

        workspaces = _load("workspaces.json")
        wsp = next((w for w in workspaces if w.get("workspace_id") == workspaceId and w.get("status") == "active"), None)
        if not wsp:
            out = _err("NOT_FOUND", "Workspace not found.")
            _log("list_documents", "NOT_FOUND", "workspace_not_found", workspace_id=workspaceId)
            return out

        # Validate parentId exists when provided (internal container id), except allow null-parent docs for EVERYTHING/WORKSPACE only if parentId matches a real container.
        if parentId is not None:
            containers = _load("containers.json")
            pc = next((c for c in containers if c.get("workspace_id") == workspaceId and c.get("container_id") == parentId and c.get("status") == "active"), None)
            if not pc:
                out = _err("NOT_FOUND", "Parent container not found.")
                _log("list_documents", "NOT_FOUND", "parent_not_found", workspace_id=workspaceId)
                return out
            if pt != pc.get("type"):
                out = _err("VALIDATION_ERROR", "parentType does not match the provided parentId container type.")
                _log("list_documents", "VALIDATION_ERROR", "parent_mismatch", workspace_id=workspaceId)
                return out

        entities = _load("time_and_docs.json")
        docs = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("type") == "DOCUMENT" and e.get("status") != "deleted"]

        if pt is not None:
            code_map = {"SPACE": 4, "FOLDER": 5, "LIST": 6, "EVERYTHING": 7, "WORKSPACE": 12}
            docs = [d for d in docs if d.get("parent_type_code") == code_map[pt]]
        if parentId is not None:
            docs = [d for d in docs if d.get("parent_container_id") == parentId]

        def _key(d):
            v = d.get(sort)
            if v is None:
                return ""
            return v

        reverse = (order == "desc")
        docs.sort(key=_key, reverse=reverse)

        start = 0
        if cursor:
            start = _decode_cursor(cursor)
            if start is None or start < 0:
                out = _err("VALIDATION_ERROR", "cursor is malformed.")
                _log("list_documents", "VALIDATION_ERROR", "bad_cursor", workspace_id=workspaceId)
                return out

        total = len(docs)
        page = docs[start:start + limit]
        next_cursor = None
        if start + limit < total:
            next_cursor = _encode_cursor(start + limit)

        resp = {
            "documents": page,
            "meta": {
                "total": total,
                "limit": limit,
                "has_more": next_cursor is not None,
                "next_cursor": next_cursor,
                "sort": sort,
                "order": order,
            }
        }
        _log("list_documents", "ok", workspace_id=workspaceId)
        return resp
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log("list_documents", "VALIDATION_ERROR", "unexpected_error", workspace_id=workspaceId)
        return out

def list_document_pages(workspaceId, documentId, depth=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, detail=None, workspace_id=None, entity_id=None):
        logs = _load("request_log.json")
        row = {
            "request_id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if workspace_id is not None:
            row["workspace_id"] = workspace_id
        if entity_id is not None:
            row["entity_id"] = entity_id
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_log.json", logs)

    try:
        if not (isinstance(workspaceId, str) and re.match(r"^cu_wsp_[A-Za-z0-9]+$", workspaceId)):
            out = _err("VALIDATION_ERROR", "workspaceId is missing or invalid.")
            _log("list_document_pages", "VALIDATION_ERROR", "invalid_workspaceId", workspace_id=workspaceId)
            return out

        if not (isinstance(documentId, str) and re.match(r"^cu_ent_[A-Za-z0-9]+$", documentId)):
            out = _err("VALIDATION_ERROR", "documentId is missing or invalid.")
            _log("list_document_pages", "VALIDATION_ERROR", "invalid_documentId", workspace_id=workspaceId)
            return out

        if depth is None:
            depth = 999999
        if not isinstance(depth, int) or depth < 0:
            out = _err("VALIDATION_ERROR", "depth must be an integer >= 0.")
            _log("list_document_pages", "VALIDATION_ERROR", "invalid_depth", workspace_id=workspaceId, entity_id=documentId)
            return out

        workspaces = _load("workspaces.json")
        wsp = next((w for w in workspaces if w.get("workspace_id") == workspaceId and w.get("status") == "active"), None)
        if not wsp:
            out = _err("NOT_FOUND", "Workspace not found.")
            _log("list_document_pages", "NOT_FOUND", "workspace_not_found", workspace_id=workspaceId, entity_id=documentId)
            return out

        entities = _load("time_and_docs.json")
        doc = next((e for e in entities if e.get("workspace_id") == workspaceId and e.get("entity_id") == documentId
                    and e.get("type") == "DOCUMENT" and e.get("status") != "deleted"), None)
        if not doc:
            out = _err("NOT_FOUND", "Document not found.")
            _log("list_document_pages", "NOT_FOUND", "doc_not_found", workspace_id=workspaceId, entity_id=documentId)
            return out

        # No separate ACL model in schema; thus no FORBIDDEN possible to derive offline.
        pages = [e for e in entities if e.get("workspace_id") == workspaceId and e.get("type") == "DOCUMENT_PAGE"
                 and e.get("document_id") == documentId and e.get("status") != "deleted"]

        # Depth filtering: use stored 'depth' if present; if absent, treat as 0.
        def _page_depth(p):
            d = p.get("depth")
            return d if isinstance(d, int) and d >= 0 else 0

        pages = [p for p in pages if _page_depth(p) <= depth]

        # Deterministic ordering: depth asc then created_at asc then entity_id
        def _key(p):
            return (_page_depth(p), p.get("created_at") or "", p.get("entity_id") or "")
        pages.sort(key=_key)

        resp = {
            "document": doc,
            "pages": pages,
            "meta": {"depth": depth, "count": len(pages)}
        }
        _log("list_document_pages", "ok", workspace_id=workspaceId, entity_id=documentId)
        return resp
    except Exception as e:
        out = _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
        _log("list_document_pages", "VALIDATION_ERROR", "unexpected_error", workspace_id=workspaceId, entity_id=documentId)
        return out

def get_document_pages(workspace_id, document_id=None, clickup_document_id=None, page_ids=None, depth=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    # --- audit / rate limit (best-effort, schema may not include request log)
    def _record(status, credential=None, extra=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "request_id": "cu_req_" + os.urandom(9).hex().upper(),
                "endpoint": "get_document_pages",
                "workspace_id": workspace_id,
                "credential": credential,
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    # --- validation
    if not isinstance(workspace_id, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18}$", workspace_id or ""):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is invalid.", field="workspace_id")

    if (document_id is None and clickup_document_id is None) or (document_id is not None and clickup_document_id is not None):
        _record("VALIDATION_ERROR")
        return _err(
            "VALIDATION_ERROR",
            "Exactly one of document_id or clickup_document_id must be provided.",
            fields=["document_id", "clickup_document_id"],
        )

    if document_id is not None:
        if not isinstance(document_id, str) or not re.match(r"^cu_ent_[0-9A-Z]{18}$", document_id or ""):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "document_id is invalid.", field="document_id")

    if clickup_document_id is not None and not isinstance(clickup_document_id, str):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "clickup_document_id must be a string.", field="clickup_document_id")

    if page_ids is not None:
        if not isinstance(page_ids, list) or any((not isinstance(x, str) or not x) for x in page_ids):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_ids must be an array of non-empty strings.", field="page_ids")

    if depth is not None:
        if not isinstance(depth, int) or depth < 0:
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "depth must be an integer >= 0.", field="depth")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    # --- workspace exists and active
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp or wsp.get("status") != "active":
        _record("NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    ents = _load("time_and_docs.json")
    if not isinstance(ents, list):
        ents = []

    # Resolve document
    doc = None
    if document_id is not None:
        doc = next((e for e in ents if e.get("entity_id") == document_id and e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT" and e.get("status") != "deleted"), None)
        if not doc:
            _record("NOT_FOUND")
            return _err("NOT_FOUND", "Document not found.", document_id=document_id)
    else:
        doc = next((e for e in ents if e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT" and e.get("clickup_document_id") == clickup_document_id and e.get("status") != "deleted"), None)
        if not doc:
            _record("NOT_FOUND")
            return _err("NOT_FOUND", "Document not found.", clickup_document_id=clickup_document_id)

    # Collect pages for this document
    doc_entity_id = doc.get("entity_id")
    pages_all = [e for e in ents if e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT_PAGE" and e.get("document_id") == doc_entity_id and e.get("status") != "deleted"]

    # Optional depth: stored as e.get("depth") hint; if absent, treat as 0 (root)
    if depth is not None:
        pages_all = [p for p in pages_all if (p.get("depth") if isinstance(p.get("depth"), int) else 0) <= depth]

    # If page_ids provided: return those pages only (no pagination)
    if page_ids is not None:
        by_pid = {p.get("clickup_page_id"): p for p in pages_all if p.get("clickup_page_id")}
        items = [by_pid[pid] for pid in page_ids if pid in by_pid]
        # Preserve order; missing pages are simply omitted (read tools return empty set, not errors)
        _record("OK")
        return {
            "document": {"entity_id": doc.get("entity_id"), "clickup_document_id": doc.get("clickup_document_id"), "title": doc.get("title")},
            "pages": items,
            "meta": {"total": len(items), "has_more": False, "next_cursor": None},
        }

    # Pagination over created_at then entity_id (stable); cursor is "ts|id" (opaque)
    def _key(p):
        return (p.get("created_at") or "", p.get("entity_id") or "")

    pages_all.sort(key=_key)

    start_after = None
    if cursor:
        # parse best-effort
        if "|" in cursor:
            a, b = cursor.split("|", 1)
            start_after = (a, b)
        else:
            start_after = (cursor, "")

    if start_after is not None:
        pages_all = [p for p in pages_all if _key(p) > start_after]

    items = pages_all[:limit]
    has_more = len(pages_all) > len(items)
    next_cursor = None
    if has_more and items:
        last = items[-1]
        next_cursor = f"{last.get('created_at') or ''}|{last.get('entity_id') or ''}"

    _record("OK")
    return {
        "document": {"entity_id": doc.get("entity_id"), "clickup_document_id": doc.get("clickup_document_id"), "title": doc.get("title")},
        "pages": items,
        "meta": {"total": len(items), "has_more": has_more, "next_cursor": next_cursor},
    }

def create_document_page(workspace_id, document_id=None, clickup_document_id=None, body=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_document_page"

    def _utcnow_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _log(status_code, entity_id=None, detail=None):
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "request_id": _gen_id("req"),
            "endpoint": endpoint,
            "timestamp": _utcnow_z(),
            "status": status_code,
            "workspace_id": workspace_id,
            "entity_id": entity_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "detail": detail
        })
        _save("request_log.json", logs)

    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _log("VALIDATION_ERROR", detail={"field": "workspace_id"})
        return _err("VALIDATION_ERROR", "workspace_id is required and must be a string.", field="workspace_id")
    if body is None or not isinstance(body, dict):
        _log("VALIDATION_ERROR", detail={"field": "body"})
        return _err("VALIDATION_ERROR", "body is required and must be an object.", field="body")
    if "title" not in body or not isinstance(body.get("title"), str) or not body.get("title").strip():
        _log("VALIDATION_ERROR", detail={"field": "body.title"})
        return _err("VALIDATION_ERROR", "body.title is required and must be a non-empty string.", field="body.title")

    if document_id is None and clickup_document_id is None:
        _log("VALIDATION_ERROR", detail={"fields": ["document_id", "clickup_document_id"]})
        return _err("VALIDATION_ERROR", "Provide document_id or clickup_document_id.", fields=["document_id", "clickup_document_id"])
    if document_id is not None and not isinstance(document_id, str):
        _log("VALIDATION_ERROR", detail={"field": "document_id"})
        return _err("VALIDATION_ERROR", "document_id must be a string when provided.", field="document_id")
    if clickup_document_id is not None and not isinstance(clickup_document_id, str):
        _log("VALIDATION_ERROR", detail={"field": "clickup_document_id"})
        return _err("VALIDATION_ERROR", "clickup_document_id must be a string when provided.", field="clickup_document_id")

    content_format = body.get("content_format")
    if content_format is not None and content_format not in ("text", "markdown", "html", "clickup_doc"):
        _log("VALIDATION_ERROR", detail={"field": "body.content_format"})
        return _err("VALIDATION_ERROR", "body.content_format must be one of text, markdown, html, clickup_doc.", field="body.content_format")
    visibility = body.get("visibility")
    if visibility is not None and visibility not in ("private", "workspace", "public", "unknown"):
        _log("VALIDATION_ERROR", detail={"field": "body.visibility"})
        return _err("VALIDATION_ERROR", "body.visibility must be one of private, workspace, public, unknown.", field="body.visibility")
    if body.get("content") is not None and not isinstance(body.get("content"), str):
        _log("VALIDATION_ERROR", detail={"field": "body.content"})
        return _err("VALIDATION_ERROR", "body.content must be a string when provided.", field="body.content")
    if body.get("parent_page_id") is not None and not isinstance(body.get("parent_page_id"), str):
        _log("VALIDATION_ERROR", detail={"field": "body.parent_page_id"})
        return _err("VALIDATION_ERROR", "body.parent_page_id must be a string when provided.", field="body.parent_page_id")

    workspaces = _load("workspaces.json")
    entities = _load("time_and_docs.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(entities, list): entities = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("workspace_id") == workspace_id and w.get("status") == "active"), None)
    if ws is None:
        _log("NOT_FOUND", detail={"field": "workspace_id"})
        return _err("NOT_FOUND", "Workspace not found or not active.", field="workspace_id")

    doc_by_internal = None
    doc_by_vendor = None
    if document_id is not None:
        did = document_id.strip()
        doc_by_internal = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT" and e.get("status") != "deleted" and e.get("entity_id") == did), None)
        if doc_by_internal is None:
            _log("NOT_FOUND", detail={"field": "document_id"})
            return _err("NOT_FOUND", "Document not found.", field="document_id")
    if clickup_document_id is not None:
        cdid = clickup_document_id.strip()
        doc_by_vendor = next((e for e in entities if isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT" and e.get("status") != "deleted" and e.get("clickup_document_id") == cdid), None)
        if doc_by_vendor is None:
            _log("NOT_FOUND", detail={"field": "clickup_document_id"})
            return _err("NOT_FOUND", "Document not found.", field="clickup_document_id")

    if doc_by_internal is not None and doc_by_vendor is not None and doc_by_internal.get("entity_id") != doc_by_vendor.get("entity_id"):
        _log("CONFLICT", detail={"fields": ["document_id", "clickup_document_id"]})
        return _err("CONFLICT", "document_id and clickup_document_id refer to different documents.", fields=["document_id", "clickup_document_id"])

    doc = doc_by_internal or doc_by_vendor
    nowz = _utcnow_z()

    entity_id = _gen_id("cu_ent")
    clickup_page_id = _gen_id("pg")

    # enforce unique(workspace_id, clickup_page_id) where not null
    if any(isinstance(e, dict) and e.get("workspace_id") == workspace_id and e.get("clickup_page_id") == clickup_page_id for e in entities):
        clickup_page_id = _gen_id("pg")

    page_row = {
        "entity_id": entity_id,
        "workspace_id": workspace_id,
        "type": "DOCUMENT_PAGE",
        "task_id": None,
        "clickup_task_id": None,
        "clickup_time_entry_id": None,
        "start_time": None,
        "end_time": None,
        "duration_seconds": None,
        "billable": None,
        "description": None,
        "tags": None,
        "clickup_user_id": None,
        "document_id": doc.get("entity_id"),
        "clickup_document_id": doc.get("clickup_document_id"),
        "clickup_page_id": clickup_page_id,
        "title": body.get("title").strip(),
        "content": body.get("content"),
        "content_format": content_format,
        "parent_container_id": None,
        "parent_type_code": None,
        "visibility": visibility,
        "create_page": None,
        "depth": None,
        "status": "active",
        "created_at": nowz,
        "updated_at": nowz
    }

    entities.append(page_row)
    _save("time_and_docs.json", entities)

    _log("OK", entity_id=entity_id, detail={"document_id": doc.get("entity_id")})
    return {"page": page_row}

