        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "request_id": "cu_req_" + os.urandom(9).hex().upper(),
                "endpoint": "update_document_page",
                "workspace_id": workspace_id,
                "credential": credential,
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^cu_wsp_[0-9A-Z]{18}$", workspace_id or ""):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id is invalid.", field="workspace_id")

    if body is None or not isinstance(body, dict):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "body is required and must be an object.", field="body")

    if (page_id is None and entity_id is None) or (page_id is not None and entity_id is not None):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Exactly one of page_id or entity_id must be provided.", fields=["page_id", "entity_id"])

    if page_id is not None and (not isinstance(page_id, str) or not page_id):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_id must be a non-empty string.", field="page_id")

    if entity_id is not None:
        if not isinstance(entity_id, str) or not re.match(r"^cu_ent_[0-9A-Z]{18}$", entity_id or ""):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "entity_id is invalid.", field="entity_id")

    cf = body.get("content_format")
    if cf is not None:
        if not isinstance(cf, str) or cf not in ("text", "markdown", "html", "clickup_doc"):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.content_format is invalid.", field="body.content_format")

    cm = body.get("content_mode")
    if cm is not None:
        if not isinstance(cm, str) or cm not in ("replace", "append"):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.content_mode is invalid.", field="body.content_mode")
    else:
        cm = "replace"

    # Must update at least one supported field
    supported = {"title", "subtitle", "content", "content_format", "content_mode"}
    if not any(k in body for k in supported):
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "At least one updatable field must be provided in body.", field="body")

    # Workspace must exist/active
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("workspace_id") == workspace_id), None)
    if not wsp or wsp.get("status") != "active":
        _record("NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    ents = _load("time_and_docs.json")
    if not isinstance(ents, list):
        ents = []

    page = None
    page_idx = None
    if entity_id is not None:
        for i, e in enumerate(ents):
            if e.get("entity_id") == entity_id and e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT_PAGE" and e.get("status") != "deleted":
                page = e
                page_idx = i
                break
        if not page:
            _record("NOT_FOUND")
            return _err("NOT_FOUND", "Page not found.", entity_id=entity_id)
    else:
        for i, e in enumerate(ents):
            if e.get("workspace_id") == workspace_id and e.get("type") == "DOCUMENT_PAGE" and e.get("clickup_page_id") == page_id and e.get("status") != "deleted":
                page = e
                page_idx = i
                break
        if not page:
            _record("NOT_FOUND")
            return _err("NOT_FOUND", "Page not found.", page_id=page_id)

    # Apply updates
    changed = False

    if "title" in body:
        if body["title"] is not None and (not isinstance(body["title"], str) or not body["title"].strip()):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.title must be a non-empty string when provided.", field="body.title")
        if body["title"] is None:
            # keep title required-ish; disallow nulling
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.title cannot be null.", field="body.title")
        if page.get("title") != body["title"]:
            page["title"] = body["title"]
            changed = True

    if "subtitle" in body:
        if body["subtitle"] is not None and not isinstance(body["subtitle"], str):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.subtitle must be a string when provided.", field="body.subtitle")
        # store subtitle in description field per schema
        if page.get("description") != body.get("subtitle"):
            page["description"] = body.get("subtitle")
            changed = True

    if "content_format" in body:
        if page.get("content_format") != body.get("content_format"):
            page["content_format"] = body.get("content_format")
            changed = True

    if "content" in body:
        if body["content"] is not None and not isinstance(body["content"], str):
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.content must be a string when provided.", field="body.content")
        new_content = body.get("content")
        old_content = page.get("content") or ""
        if new_content is None:
            # treat explicit null as no-op? better: invalid since content should be string if provided
            _record("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body.content cannot be null; omit the field to leave unchanged.", field="body.content")
        if cm == "replace":
            if page.get("content") != new_content:
                page["content"] = new_content
                changed = True
        else:  # append
            appended = old_content + new_content
            if page.get("content") != appended:
                page["content"] = appended
                changed = True
            # preserve content_format: if provided, set; else keep existing

    if not changed:
        # Idempotent update: still return the page, but ensure observable dynamics via log.
        _record("OK", extra={"idempotent": True})
        return {"page": page, "meta": {"updated": False}}

    page["updated_at"] = now
    ents[page_idx] = page
    _save("time_and_docs.json", ents)

    _record("OK")
    return {"page": page, "meta": {"updated": True}}

def get_whoami(accessToken=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0497000" if __import__("os").path.isdir("./environment_mix/0497000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _record(status, credential=None, extra=None):
        try:
            logs = _load("request_log.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "request_id": "cu_req_" + os.urandom(9).hex().upper(),
                "endpoint": "get_whoami",
                "workspace_id": None,
                "credential": credential,
                "status": status,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_log.json", logs)
        except Exception:
            pass

    # In this local datastore, there may be no explicit credential collection.
    # Contract: UNAUTHORIZED if credential missing/invalid when explicit parameter exists.
    # We'll accept either:
    # - a matching row in credentials.json where token/id equals accessToken (if file exists)
    # - OR, if no credentials store exists, we cannot validate a token, so require it and fail.
    if accessToken is None:
        _record("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "accessToken is required for this endpoint in the current datastore.")

    if not isinstance(accessToken, str) or not accessToken:
        _record("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string.", field="accessToken")

    creds = _load("credentials.json")
    cred = None
    if isinstance(creds, list):
        for c in creds:
            if c.get("accessToken") == accessToken or c.get("token") == accessToken or c.get("id") == accessToken or c.get("credential_id") == accessToken:
                cred = c
                break

    if not cred:
        _record("UNAUTHORIZED", credential=accessToken)
        return _err("UNAUTHORIZED", "Invalid credentials.")

    # Attempt to compute basic entitlement snapshot based on request logs (if present)
    logs = _load("request_log.json")
    used = 0
    last_24h = 0
    if isinstance(logs, list):
        used = sum(1 for r in logs if r.get("credential") == cred.get("id") or r.get("credential") == accessToken or r.get("credential") == cred.get("credential_id"))
        # last 24h best-effort
        try:
            cutoff = (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(hours=24)).isoformat()
            last_24h = sum(
                1
                for r in logs
                if (r.get("credential") == cred.get("id") or r.get("credential") == accessToken or r.get("credential") == cred.get("credential_id"))
                and isinstance(r.get("timestamp"), str)
                and r.get("timestamp") >= cutoff
            )
        except Exception:
            last_24h = 0

    # Determine accessible workspaces best-effort
    workspaces = _load("workspaces.json")
    active_workspaces = []
    if isinstance(workspaces, list):
        for w in workspaces:
            if w.get("status") == "active":
                active_workspaces.append({"workspace_id": w.get("workspace_id"), "clickup_team_id": w.get("clickup_team_id"), "name": w.get("name")})

    resp = {
        "subject": {
            "credential_id": cred.get("credential_id") or cred.get("id"),
            "type": cred.get("type") or "access_token",
            "label": cred.get("label") or None,
        },
        "scopes": cred.get("scopes") or cred.get("scope") or [],
        "entitlements": {
            "workspaces": active_workspaces,
        },
        "usage": {
            "requests_total": used,
            "requests_last_24h": last_24h,
        },
    }

    _record("OK", credential=cred.get("credential_id") or cred.get("id") or accessToken)
    return resp
